//! Compile-outcome tests for the type inference / generic resolution paths that
//! have been the source of recurring bugs. Each case asserts whether a source
//! compiles cleanly or fails, run through the real pipeline on a large-stack
//! worker (so a recursion bug surfaces as an error, not an aborted suite).
//!
//! `#[ignore]`d tests are KNOWN BUGS (see vilan/proposal/analyzer-refactor.md):
//! they assert the *desired* outcome, so removing `#[ignore]` when the bug is
//! fixed turns them green — that's how we track progress against the plan.

use std::path::{Path, PathBuf};

use vilan_core::{BuildOptions, PackageSpec, Platform, Workspace, analyze_source, transform};

fn std_spec() -> PackageSpec {
    vilan_core::manifest::resolve_std(
        &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../vilan/std"),
    )
}

/// Compile a source through the full pipeline (analyze → context → infer →
/// transform) on a 256 MB-stack worker, matching the CLI. Returns the emitted JS
/// on a clean compile, or the diagnostics. A panic becomes an error rather than
/// aborting the test process.
fn compile(source: &str) -> Result<String, Vec<String>> {
    compile_on(source, Platform::default())
}

/// `compile` for a browser build — the platform whose layer holds `std::ui` /
/// `std::dom` / `std::router`, none of which the default (node) platform can
/// import.
fn compile_browser(source: &str) -> Result<String, Vec<String>> {
    compile_on(source, Platform::Browser)
}

fn compile_on(source: &str, platform: Platform) -> Result<String, Vec<String>> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let leaked: &'static str = Box::leak(source.into_boxed_str());
                let (program, errors) = analyze_source(
                    leaked,
                    &std_spec(),
                    Path::new("."),
                    Path::new("test.vl"),
                    Some(platform),
                    &Workspace::default(),
                );
                match program {
                    Some(program) if errors.is_empty() => {
                        transform(&program, &BuildOptions::default())
                            .map_err(|error| vec![error.msg])
                    }
                    _ => Err(errors.into_iter().map(|error| error.msg).collect()),
                }
            }))
            .unwrap_or_else(|_| Err(vec!["compiler panicked".to_string()]))
        })
        .expect("spawn worker")
        .join()
        .unwrap_or_else(|_| {
            Err(vec![
                "compiler thread aborted (likely a stack overflow)".to_string(),
            ])
        })
}

/// Compile a browser program with the HMR instrumentation flag set to `hmr`,
/// returning the emitted JS. `hmr = true` is the `run --watch` browser path; the
/// `false` arm must be byte-identical to a normal `compile_browser`.
fn compile_browser_with_hmr(source: &str, hmr: bool) -> Result<String, Vec<String>> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let leaked: &'static str = Box::leak(source.into_boxed_str());
                let (program, errors) = analyze_source(
                    leaked,
                    &std_spec(),
                    Path::new("."),
                    Path::new("test.vl"),
                    Some(Platform::Browser),
                    &Workspace::default(),
                );
                match program {
                    Some(program) if errors.is_empty() => {
                        let mut options = BuildOptions::default();
                        options.hmr = hmr;
                        transform(&program, &options).map_err(|error| vec![error.msg])
                    }
                    _ => Err(errors.into_iter().map(|error| error.msg).collect()),
                }
            }))
            .unwrap_or_else(|_| Err(vec!["compiler panicked".to_string()]))
        })
        .expect("spawn worker")
        .join()
        .unwrap_or_else(|_| Err(vec!["compiler thread aborted".to_string()]))
}

#[track_caller]
fn compile_hmr(source: &str) -> String {
    match compile_browser_with_hmr(source, true) {
        Ok(js) => js,
        Err(errors) => panic!("expected a clean HMR compile, got: {errors:#?}"),
    }
}

/// The djb2 fingerprint the HMR instrumentation stamped for `key`, read out of the
/// emitted `__hmr_adopt*("<key>", <fp>, ...)` (or expose) call.
fn hmr_fingerprint(js: &str, key: &str) -> Option<u32> {
    let needle = format!("\"{key}\", ");
    let start = js.find(&needle)? + needle.len();
    let rest = &js[start..];
    let end = rest.find(|c: char| !c.is_ascii_digit())?;
    rest[..end].parse().ok()
}

// --- A13 S2a: HMR identity, fingerprints, and adopt/expose emission -----------

#[test]
fn hmr_value_binding_wraps_initializer_and_exposes_it() {
    // A plain-data binding adopts the value itself: `__hmr_adopt(key, fp, () =>
    // <init>)`, and exposes it with a `() => <name>` getter at the module tail.
    let js = compile_hmr(
        r#"
        import std::print;
        mut count = 0;
        fun main() { count = count + 1; print(count); }
        "#,
    );
    assert!(
        js.contains(r#"__hmr_adopt("pkg::count", "#),
        "value binding should wrap with __hmr_adopt: {js}"
    );
    assert!(
        js.contains(r#"__hmr_expose("pkg::count", "#),
        "value binding should be exposed: {js}"
    );
    // The adopt thunk returns the original initializer, the getter reads the live
    // binding.
    assert!(
        js.contains("return 0;"),
        "thunk returns the initializer: {js}"
    );
    assert!(
        js.contains("return count;"),
        "getter reads the binding: {js}"
    );
}

#[test]
fn hmr_mut_binding_is_let_and_immutable_binding_is_const() {
    // The declaration keyword is preserved through the wrap: a `mut` binding stays
    // JS `let`, an immutable one stays `const`.
    let js = compile_hmr(
        r#"
        import std::print;
        mut counter = 0;
        let label = "hi";
        fun main() { counter = counter + 1; print(label); }
        "#,
    );
    assert!(
        js.contains(r#"let counter = __hmr_adopt("pkg::counter", "#),
        "mut binding is a JS `let`: {js}"
    );
    assert!(
        js.contains(r#"const label = __hmr_adopt("pkg::label", "#),
        "immutable binding is a JS `const`: {js}"
    );
}

#[test]
fn hmr_signal_binding_uses_payload_form() {
    // A `Signal<T>` adopts through the payload form, and its getter reads the value
    // cell (`[0].v`) so only the value crosses — old subscribers die.
    let js = compile_hmr(
        r#"
        import std::print;
        import std::reactive::Signal;
        let ticker = Signal::new(0);
        fun main() { print(ticker.get()); }
        "#,
    );
    assert!(
        js.contains(r#"__hmr_adopt_signal("pkg::ticker", "#),
        "signal binding uses the signal payload adopt: {js}"
    );
    assert!(
        js.contains("return ticker[0].v;"),
        "signal getter reads the value cell: {js}"
    );
}

#[test]
fn hmr_shared_binding_uses_payload_form() {
    // A `Shared<T>` adopts through the payload form; its getter reads the cell slot
    // (`.v`).
    let js = compile_hmr(
        r#"
        import std::print;
        import std::shared::Shared;
        let cell = Shared::new(0);
        fun main() { print(cell.read()); }
        "#,
    );
    assert!(
        js.contains(r#"__hmr_adopt_shared("pkg::cell", "#),
        "shared binding uses the shared payload adopt: {js}"
    );
    assert!(
        js.contains("return cell.v;"),
        "shared getter reads the cell slot: {js}"
    );
}

#[test]
fn hmr_excluded_binding_is_emitted_unwrapped_and_unexposed() {
    // A binding whose type carries code (a struct with a closure field) is not
    // transferable: it emits its declaration exactly as usual — no adopt wrap — and
    // is never exposed.
    let js = compile_hmr(
        r#"
        import std::print;
        struct Holder { action: || i32 }
        let holder = Holder { action = || 42 };
        fun main() { print((holder.action)()); }
        "#,
    );
    assert!(
        !js.contains("pkg::holder"),
        "an excluded binding is neither adopted nor exposed: {js}"
    );
    assert!(
        js.contains("const holder = ") && !js.contains("const holder = __hmr"),
        "the excluded binding still emits its plain, unwrapped declaration: {js}"
    );
}

#[test]
fn hmr_nested_module_binding_key_carries_the_module_path() {
    // A binding declared inside a `mod` is keyed `pkg::<module>::<name>` — from its
    // DECLARING scope, so a `use` re-export cannot relabel its home.
    let js = compile_hmr(
        r#"
        import std::print;
        mod inner { export let greeting = "hey"; }
        use inner::greeting;
        fun main() { print(greeting); }
        "#,
    );
    assert!(
        js.contains(r#"__hmr_adopt("pkg::inner::greeting", "#),
        "nested binding carries its module path: {js}"
    );
    assert!(
        js.contains(r#"__hmr_expose("pkg::inner::greeting", "#),
        "nested binding is exposed under its module path: {js}"
    );
}

#[test]
fn hmr_fingerprint_is_stable_for_equal_types_and_differs_on_a_type_change() {
    // Two bindings of the same type share a fingerprint; changing a struct field's
    // type flips it (so the swap falls back to fresh init instead of adopting a
    // stale shape). The fingerprint is over the structural type, not the value.
    let same = compile_hmr(
        r#"
        import std::print;
        let a = 1;
        let b = 2;
        fun main() { print(a); print(b); }
        "#,
    );
    let fp_a = hmr_fingerprint(&same, "pkg::a").expect("fp a");
    let fp_b = hmr_fingerprint(&same, "pkg::b").expect("fp b");
    assert_eq!(fp_a, fp_b, "same type (i32) hashes the same");

    let point_i32 = compile_hmr(
        r#"
        import std::print;
        struct Point { x: i32 }
        let p = Point { x = 1 };
        fun main() { print(p.x); }
        "#,
    );
    let point_str = compile_hmr(
        r#"
        import std::print;
        struct Point { x: str }
        let p = Point { x = "a" };
        fun main() { print(p.x); }
        "#,
    );
    let fp_int = hmr_fingerprint(&point_i32, "pkg::p").expect("fp int point");
    let fp_str = hmr_fingerprint(&point_str, "pkg::p").expect("fp str point");
    assert_ne!(
        fp_int, fp_str,
        "a changed field type must change the fingerprint"
    );
}

#[test]
fn hmr_function_local_is_not_wrapped_or_exposed() {
    // A function-local `let` is function-minted state, NOT a module-level binding
    // (hmr.md §3: it must reset on a swap). Its declaring scope is a function body,
    // never a root / `mod` body, so it is never classified — no adopt, no expose.
    let js = compile_hmr(
        r#"
        import std::print;
        fun main() { let local = 5; print(local); }
        "#,
    );
    assert!(
        !js.contains("__hmr_"),
        "a function-local must carry no HMR instrumentation: {js}"
    );
    assert!(
        js.contains("const local = 5;"),
        "the local emits its plain declaration: {js}"
    );
}

#[test]
fn hmr_module_and_local_same_name_only_wraps_the_module_binding() {
    // A module `mut n` and a same-named function-local `let n` must not collide:
    // only the module binding wraps + exposes under `pkg::n`; the local (which
    // would otherwise match the module seed on a swap and return the stale value)
    // emits unwrapped.
    let js = compile_hmr(
        r#"
        import std::print;
        mut n = 0;
        fun helper() { let n = 99; print(n); }
        fun main() { n = n + 1; helper(); print(n); }
        "#,
    );
    // The module binding wraps and is exposed.
    assert!(
        js.contains(r#"__hmr_adopt("pkg::n", "#),
        "the module binding wraps: {js}"
    );
    assert!(
        js.contains(r#"__hmr_expose("pkg::n", "#),
        "the module binding is exposed: {js}"
    );
    // Exactly one adopt and one expose — the local did not add its own.
    assert_eq!(
        js.matches("__hmr_adopt").count(),
        1,
        "only the module binding adopts, not the local: {js}"
    );
    assert_eq!(
        js.matches("__hmr_expose").count(),
        1,
        "only the module binding is exposed, not the local: {js}"
    );
    // The local `n` inside `helper` emits its own plain declaration.
    assert!(
        js.contains("= 99;"),
        "the same-named local emits unwrapped: {js}"
    );
}

#[test]
fn hmr_closure_body_local_is_not_wrapped() {
    // A local minted inside a closure body is likewise function-minted state, not
    // module-level — no adopt wrap.
    let js = compile_hmr(
        r#"
        import std::print;
        let make = || { let inner = 7; inner };
        fun main() { print(make()); }
        "#,
    );
    assert!(
        !js.contains(r#"__hmr_adopt("pkg::inner""#),
        "a closure-body local must not be wrapped: {js}"
    );
}

#[test]
fn hmr_disabled_is_byte_identical_and_has_no_instrumentation() {
    // The flag-off path is byte-identical to a normal browser compile, and carries
    // no `__hmr_` tokens at all — the equivalence-gate guarantee that `build`
    // output is untouched.
    let source = r#"
        import std::print;
        import std::reactive::Signal;
        mut count = 0;
        let ticker = Signal::new(0);
        fun main() { count = count + 1; print(count); print(ticker.get()); }
        "#;
    let off = compile_browser_with_hmr(source, false).expect("compiles with hmr off");
    let baseline = compile_browser(source).expect("compiles normally");
    assert_eq!(
        off, baseline,
        "hmr = false must be byte-identical to a normal compile"
    );
    assert!(
        !off.contains("__hmr_"),
        "a non-HMR compile carries no HMR instrumentation: {off}"
    );
}

// --- A13 S2b: the dev::stash / dev::take transfer bound (hmr.md §4) -----------

/// A closure argument to `stash` is rejected — it carries code the new bundle
/// cannot adopt, the one thing the transfer bound forbids.
#[test]
fn hmr_stash_rejects_a_closure_argument() {
    assert_fails_browser_with(
        r#"
        import std::dev;

        fun main() {
            dev::stash("handler", || 0);
        }
        "#,
        "cannot cross a hot swap",
    );
}

/// A `Shared` argument to `stash` is rejected — a reactive cell's identity (its
/// subscribers) does not survive a swap; only a plain value would.
#[test]
fn hmr_stash_rejects_a_shared_argument() {
    assert_fails_browser_with(
        r#"
        import std::dev;
        import std::shared::Shared;

        fun main() {
            dev::stash("cell", Shared::new(0));
        }
        "#,
        "cannot cross a hot swap",
    );
}

/// The bound is by containment: a struct whose field holds a closure is rejected
/// just as a bare closure is.
#[test]
fn hmr_stash_rejects_a_struct_that_holds_a_closure() {
    assert_fails_browser_with(
        r#"
        import std::dev;

        struct Handlers { on_click: || void }

        fun main() {
            dev::stash("handlers", Handlers { on_click = || {} });
        }
        "#,
        "cannot cross a hot swap",
    );
}

/// A plain-data struct stashes cleanly — the bound admits scalars, `str`, lists,
/// options, and structs/enums built from them.
#[test]
fn hmr_stash_accepts_a_plain_struct() {
    assert_compiles_browser(
        r#"
        import std::dev;

        struct Session { id: i32, name: str }

        fun main() {
            dev::stash("session", Session { id = 1, name = "ada" });
        }
        "#,
    );
}

/// `take` is bound the same way: an annotated non-transferable element is
/// rejected at the call site.
#[test]
fn hmr_take_rejects_a_non_transferable_element() {
    assert_fails_browser_with(
        r#"
        import std::dev;
        import std::shared::Shared;
        import std::option::Option::{ self, Some, None };

        fun main() {
            let cell: Option<Shared<i32>> = dev::take("cell");
            match cell {
                Some(let c) => {},
                None => {},
            }
        }
        "#,
        "cannot cross a hot swap",
    );
}

/// A plain-data `take` and `on_teardown` compile cleanly — the hooks are inert
/// std surface without a shim, and their bounds admit plain data.
#[test]
fn hmr_take_and_on_teardown_accept_plain_usage() {
    assert_compiles_browser(
        r#"
        import std::dev;
        import std::option::Option::{ self, Some, None };

        fun main() {
            dev::on_teardown(|| {});
            let count: Option<i32> = dev::take("count");
            match count {
                Some(let n) => {},
                None => {},
            }
        }
        "#,
    );
}

#[track_caller]
fn assert_compiles(source: &str) {
    if let Err(errors) = compile(source) {
        panic!("expected a clean compile, got: {errors:#?}");
    }
}

#[track_caller]
fn assert_fails(source: &str) {
    assert!(
        compile(source).is_err(),
        "expected a compile error, but it compiled cleanly"
    );
}

/// Asserts compilation fails with a diagnostic containing `message_part` — like
/// [`assert_fails`] but pinning *which* error, so a test can't pass on an
/// unrelated failure.
#[track_caller]
fn assert_fails_with(source: &str, message_part: &str) {
    match compile(source) {
        Ok(_) => panic!("expected a compile error, but it compiled cleanly"),
        Err(errors) => assert!(
            errors.iter().any(|error| error.contains(message_part)),
            "no diagnostic contains {message_part:?}; got: {errors:#?}"
        ),
    }
}

/// Asserts compilation fails with EXACTLY ONE diagnostic containing
/// `message_part` — for a rule whose reach is wide enough that the multiplicity
/// is part of the claim (B103: one inferred `List<Guard>` reaches R10 as the
/// literal, the binding, every read of it, and the aggregate holding it, and it
/// is one mistake).
#[track_caller]
fn assert_fails_once_with(source: &str, message_part: &str) {
    match compile(source) {
        Ok(_) => panic!("expected a compile error, but it compiled cleanly"),
        Err(errors) => {
            let matching = errors
                .iter()
                .filter(|error| error.contains(message_part))
                .count();
            assert_eq!(
                matching, 1,
                "expected exactly one diagnostic containing {message_part:?}; got: {errors:#?}"
            );
        }
    }
}

/// Asserts compilation fails and that NO diagnostic mentions `message_part` —
/// for a fix whose point is that a misleading message is gone, not merely that
/// a better one was added beside it.
#[track_caller]
fn assert_fails_without(source: &str, message_part: &str) {
    match compile(source) {
        Ok(_) => panic!("expected a compile error, but it compiled cleanly"),
        Err(errors) => assert!(
            errors.iter().all(|error| !error.contains(message_part)),
            "a diagnostic still contains {message_part:?}; got: {errors:#?}"
        ),
    }
}

#[track_caller]
fn assert_compiles_browser(source: &str) {
    if let Err(errors) = compile_browser(source) {
        panic!("expected a clean browser compile, got: {errors:#?}");
    }
}

/// Asserts a browser compile fails with a diagnostic containing `message_part`.
#[track_caller]
fn assert_fails_browser_with(source: &str, message_part: &str) {
    match compile_browser(source) {
        Ok(_) => panic!("expected a browser compile error, but it compiled cleanly"),
        Err(errors) => assert!(
            errors.iter().any(|error| error.contains(message_part)),
            "no browser diagnostic contains {message_part:?}; got: {errors:#?}"
        ),
    }
}

/// The analyzer's diagnostics as `(message, span range)` pairs — the E7 span
/// harness's raw material (`compile` keeps only the messages).
fn failure_diagnostics(source: &str) -> Vec<(String, std::ops::Range<usize>)> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (_program, errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            errors
                .into_iter()
                .map(|error| (error.msg, error.span.into_range()))
                .collect()
        })
        .unwrap()
        .join()
        .unwrap()
}

/// Asserts compilation fails with a diagnostic whose message contains
/// `message_part` and whose span covers exactly the first occurrence of
/// `spanning` in the source — spans pin like messages (backlog E7). The
/// distinct `spanning` snippet locates the *pertinent* expression, so a
/// diagnostic that regresses to an enclosing aggregate span fails here.
#[track_caller]
/// Like `failure_diagnostics`, but keeps each diagnostic's secondary note
/// (diagnostics-standard.md C3).
fn failure_diagnostics_with_notes(
    source: &str,
) -> Vec<(
    String,
    std::ops::Range<usize>,
    Option<(String, std::ops::Range<usize>, bool)>,
)> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (_program, errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            errors
                .into_iter()
                .map(|error| {
                    (
                        error.msg,
                        error.span.into_range(),
                        error
                            .note
                            .map(|note| (note.msg, note.span.into_range(), note.source.is_some())),
                    )
                })
                .collect()
        })
        .unwrap()
        .join()
        .unwrap()
}

/// Asserts a diagnostic whose message contains `message_part` carries a
/// secondary NOTE anchored at `note_spanning`'s occurrence in the source,
/// with a note message containing `note_part` (diagnostics-standard.md C2/C3).
fn assert_fails_noting(source: &str, message_part: &str, note_spanning: &str, note_part: &str) {
    let expected_start = source
        .find(note_spanning)
        .expect("the `note_spanning` snippet must occur in the source");
    let expected = expected_start..expected_start + note_spanning.len();
    let diagnostics = failure_diagnostics_with_notes(source);
    let matching: Vec<_> = diagnostics
        .iter()
        .filter(|(message, _, _)| message.contains(message_part))
        .collect();
    assert!(
        !matching.is_empty(),
        "no diagnostic contains {message_part:?}; got: {diagnostics:#?}"
    );
    assert!(
        matching.iter().any(|(_, _, note)| note
            .as_ref()
            .is_some_and(|(msg, range, _)| msg.contains(note_part) && *range == expected)),
        "no {message_part:?} diagnostic notes {note_part:?} at {expected:?} ({note_spanning:?}); got: {matching:#?}"
    );
}

/// `assert_fails_noting` for the R11 family's shape: the error is at the
/// instantiation site in this program and the note points into the std body
/// being instantiated. The note's span is therefore an offset into a file this
/// test never wrote, so it is checked by its `source` marker (present ⇒ a
/// different file) and its text, not a range.
///
/// It also asserts the program produces exactly ONE diagnostic, which is the
/// half that makes it a pin rather than a restatement: the value that genuinely
/// cannot be handled must be the only thing reported, with no leading
/// distraction about the receiver (B63).
#[track_caller]
fn assert_only_failure_noting_into_std(source: &str, message_part: &str, note_part: &str) {
    let diagnostics = failure_diagnostics_with_notes(source);
    assert_eq!(
        diagnostics.len(),
        1,
        "expected exactly one diagnostic; got: {diagnostics:#?}"
    );
    let (message, _, note) = &diagnostics[0];
    assert!(
        message.contains(message_part),
        "the diagnostic does not contain {message_part:?}: {message:?}"
    );
    assert!(
        note.as_ref().is_some_and(
            |(msg, _, from_other_source)| msg.contains(note_part) && *from_other_source
        ),
        "the diagnostic does not note {note_part:?} in another source; got: {note:#?}"
    );
}

/// `assert_fails_noting`, but the note spans the Nth occurrence (0-based) of
/// `note_spanning` — for notes that point at a declaration the diagnosed use
/// necessarily precedes (use-before-declaration's declared-later note).
#[track_caller]
fn assert_fails_noting_nth(
    source: &str,
    message_part: &str,
    note_spanning: &str,
    occurrence: usize,
    note_part: &str,
) {
    let mut start = 0;
    let mut at = None;
    for _ in 0..=occurrence {
        at = source[start..]
            .find(note_spanning)
            .map(|found| start + found);
        match at {
            Some(position) => start = position + 1,
            None => panic!("occurrence {occurrence} of {note_spanning:?} not found"),
        }
    }
    let expected_start = at.unwrap();
    let expected = expected_start..expected_start + note_spanning.len();
    let diagnostics = failure_diagnostics_with_notes(source);
    let matching: Vec<_> = diagnostics
        .iter()
        .filter(|(message, _, _)| message.contains(message_part))
        .collect();
    assert!(
        !matching.is_empty(),
        "no diagnostic contains {message_part:?}; got: {diagnostics:#?}"
    );
    assert!(
        matching.iter().any(|(_, _, note)| note
            .as_ref()
            .is_some_and(|(msg, range, _)| msg.contains(note_part) && *range == expected)),
        "no {message_part:?} diagnostic notes {note_part:?} at {expected:?} (occurrence {occurrence} of {note_spanning:?}); got: {matching:#?}"
    );
}

/// Like [`failure_diagnostics_with_notes`], but keeping each diagnostic's
/// E78 requirement trace: `(message, span, trace)` with one
/// `(label message, span range, cross-source?)` entry per hop, in the
/// analyzer's own order — entry → read.
fn failure_diagnostics_with_trace(
    source: &str,
) -> Vec<(
    String,
    std::ops::Range<usize>,
    Vec<(String, std::ops::Range<usize>, bool)>,
)> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (_program, errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            errors
                .into_iter()
                .map(|error| {
                    (
                        error.msg,
                        error.span.into_range(),
                        error
                            .trace
                            .into_iter()
                            .map(|hop| {
                                (
                                    hop.note.msg,
                                    hop.note.span.into_range(),
                                    hop.note.source.is_some(),
                                )
                            })
                            .collect(),
                    )
                })
                .collect()
        })
        .unwrap()
        .join()
        .unwrap()
}

/// Asserts the ONE diagnostic containing `message_part` carries EXACTLY the
/// expected requirement trace (backlog E78): `expected` lists, in order
/// (entry → read), each label's span as (snippet, 0-based occurrence in the
/// source) plus a fragment of its message. Exactness is the pin: an extra
/// label — a covered call taking blame, a hop past the cap — fails here as
/// surely as a missing one.
#[track_caller]
fn assert_traces(source: &str, message_part: &str, expected: &[(&str, usize, &str)]) {
    let occurrence_span = |snippet: &str, occurrence: usize| -> std::ops::Range<usize> {
        let mut start = 0;
        let mut at = None;
        for _ in 0..=occurrence {
            at = source[start..].find(snippet).map(|found| start + found);
            match at {
                Some(position) => start = position + 1,
                None => panic!("occurrence {occurrence} of {snippet:?} not found"),
            }
        }
        let found = at.unwrap();
        found..found + snippet.len()
    };
    let diagnostics = failure_diagnostics_with_trace(source);
    let matching: Vec<_> = diagnostics
        .iter()
        .filter(|(message, _, _)| message.contains(message_part))
        .collect();
    assert_eq!(
        matching.len(),
        1,
        "expected exactly one diagnostic containing {message_part:?}; got: {diagnostics:#?}"
    );
    let (_, _, trace) = matching[0];
    assert_eq!(
        trace.len(),
        expected.len(),
        "the trace must carry exactly the expected labels; got: {trace:#?}"
    );
    for (index, ((snippet, occurrence, label_part), (label, range, cross_source))) in
        expected.iter().zip(trace).enumerate()
    {
        let expected_range = occurrence_span(snippet, *occurrence);
        assert!(
            label.contains(label_part),
            "trace[{index}] message {label:?} lacks {label_part:?}"
        );
        assert_eq!(
            *range, expected_range,
            "trace[{index}] must span occurrence {occurrence} of {snippet:?}"
        );
        assert!(
            !cross_source,
            "trace[{index}] unexpectedly points into another file"
        );
    }
}

/// `assert_fails_spanning`, but targeting the Nth occurrence (0-based) of
/// `spanning` — for snippets that necessarily appear earlier in another
/// role (an attribute name also being the macro definition's, a use after
/// its declaration).
fn assert_fails_spanning_nth(source: &str, spanning: &str, occurrence: usize, message_part: &str) {
    let mut start = 0;
    let mut at = None;
    for _ in 0..=occurrence {
        at = source[start..].find(spanning).map(|found| start + found);
        match at {
            Some(position) => start = position + 1,
            None => panic!("occurrence {occurrence} of {spanning:?} not found"),
        }
    }
    let expected_start = at.unwrap();
    let expected = expected_start..expected_start + spanning.len();
    let diagnostics = failure_diagnostics(source);
    assert!(
        diagnostics
            .iter()
            .any(|(message, range)| message.contains(message_part) && *range == expected),
        "no {message_part:?} diagnostic spans occurrence {occurrence} of {spanning:?} at {expected:?}; got: {diagnostics:#?}"
    );
}

fn assert_fails_spanning(source: &str, spanning: &str, message_part: &str) {
    let expected_start = source
        .find(spanning)
        .expect("the `spanning` snippet must occur in the source");
    let expected = expected_start..expected_start + spanning.len();
    let diagnostics = failure_diagnostics(source);
    let matching: Vec<_> = diagnostics
        .iter()
        .filter(|(message, _)| message.contains(message_part))
        .collect();
    assert!(
        !matching.is_empty(),
        "no diagnostic contains {message_part:?}; got: {diagnostics:#?}"
    );
    assert!(
        matching.iter().any(|(_, range)| *range == expected),
        "no {message_part:?} diagnostic spans {expected:?} ({spanning:?}); spans: {:#?}",
        matching
            .iter()
            .map(|(message, range)| (message.as_str(), range.clone(), &source[range.clone()]))
            .collect::<Vec<_>>()
    );
}

/// The analyzer's non-fatal warning messages (e.g. unused `[must_use]` results).
fn warnings(source: &str) -> Vec<String> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (program, _errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            program
                .map(|program| {
                    program
                        .warnings
                        .into_iter()
                        .map(|warning| warning.msg)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default()
        })
        .expect("spawn worker")
        .join()
        .unwrap_or_default()
}

/// [`warnings`] with each warning's span, through a CLEAN analysis against the
/// given std: panics unless analysis produced a program with zero diagnostics
/// (a warning that rides an error is not the non-fatal path), then returns
/// `(message, span)` per warning in the analyzer's own (C1-sorted) order.
fn warning_diagnostics_with_std(
    source: &str,
    std: PackageSpec,
) -> Vec<(String, std::ops::Range<usize>)> {
    let source = source.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (program, errors) = analyze_source(
                leaked,
                &std,
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            let messages: Vec<String> = errors.into_iter().map(|error| error.msg).collect();
            assert!(
                messages.is_empty(),
                "expected a clean analysis, got: {messages:#?}"
            );
            program
                .expect("analysis should produce a program")
                .warnings
                .into_iter()
                .map(|warning| (warning.msg, warning.span.into_range()))
                .collect::<Vec<_>>()
        })
        .expect("spawn worker")
        .join()
        .unwrap()
}

/// [`warning_diagnostics_with_std`] against the real std.
fn warning_diagnostics(source: &str) -> Vec<(String, std::ops::Range<usize>)> {
    warning_diagnostics_with_std(source, std_spec())
}

/// The warning twin of [`assert_fails_spanning`] (deprecation.md §1's C2 pin):
/// asserts a warning containing `message_part` spans the FIRST occurrence of
/// `spanning`, and — through [`warning_diagnostics`] — that the analysis was
/// clean and produced a program.
#[track_caller]
fn assert_warns_spanning(source: &str, spanning: &str, message_part: &str) {
    let expected_start = source
        .find(spanning)
        .expect("the `spanning` snippet must occur in the source");
    let expected = expected_start..expected_start + spanning.len();
    let warnings = warning_diagnostics(source);
    let matching: Vec<_> = warnings
        .iter()
        .filter(|(message, _)| message.contains(message_part))
        .collect();
    assert!(
        !matching.is_empty(),
        "no warning contains {message_part:?}; got: {warnings:#?}"
    );
    assert!(
        matching.iter().any(|(_, range)| *range == expected),
        "no {message_part:?} warning spans {expected:?} ({spanning:?}); spans: {:#?}",
        matching
            .iter()
            .map(|(message, range)| (message.as_str(), range.clone(), &source[range.clone()]))
            .collect::<Vec<_>>()
    );
}

/// The rendered per-function requirement line (`platform_color::requirements`
/// — the hover's data) for the named function, through the real pipeline on
/// the default platform. `None` = the function is colorless. Panics on
/// analysis errors or an unknown name, so a pin can't pass vacuously.
fn requirement_line_of(source: &str, function_name: &str) -> Option<String> {
    let source = source.to_string();
    let function_name = function_name.to_string();
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (program, errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            let messages: Vec<String> = errors.into_iter().map(|error| error.msg).collect();
            assert!(
                messages.is_empty(),
                "expected a clean analysis, got: {messages:#?}"
            );
            let program = program.expect("analysis should produce a program");
            let function_id = program
                .functions
                .iter()
                .find(|(_, function)| function.name == function_name.as_str())
                .map(|(id, _)| *id)
                .or_else(|| {
                    // A layer function may be a bodiless extern (e.g.
                    // `std::fs::write_file`), seeded exactly like one with a body.
                    program
                        .external_functions
                        .iter()
                        .find(|(_, function)| function.name == function_name.as_str())
                        .map(|(id, _)| *id)
                })
                .or_else(|| {
                    // A module-level binding: its initializer is code, so it
                    // carries a requirement line like a function does.
                    program
                        .variables
                        .iter()
                        .find(|(_, variable)| variable.name == function_name.as_str())
                        .map(|(id, _)| *id)
                })
                .unwrap_or_else(|| panic!("no function or binding named `{function_name}`"));
            vilan_core::platform_color::requirements(&program)
                .get(&function_id)
                .cloned()
        })
        .expect("spawn worker")
        .join()
        .expect("worker panicked")
}

/// Execute already-compiled JS with `node`, returning its stdout on a clean
/// exit or the stderr lines otherwise. Split out of `compile_and_run` (E32)
/// so a caller that needs to bound wall clock can time only the RUN: the
/// `compile` step above re-analyzes all of `std` in-process on every call
/// and can itself take seconds under nextest's full parallelism, which must
/// not count against a budget that is really about the emitted program's
/// own behavior.
fn run_js(js: &str) -> Result<String, Vec<String>> {
    use std::sync::atomic::{AtomicU32, Ordering};
    static COUNTER: AtomicU32 = AtomicU32::new(0);

    let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
    // `.mjs`, exactly as the CLI's `run`/`test`/watch scripts: a process
    // runtime classifies before it parses, and a harness that ran its bundles
    // as CommonJS could not see an ESM-only defect at all
    // (`top-level-await.md` §8.1).
    let path = std::env::temp_dir().join(format!("vilan_test_{}_{unique}.mjs", std::process::id()));
    std::fs::write(&path, js).map_err(|error| vec![error.to_string()])?;
    let output = std::process::Command::new("node").arg(&path).output();
    let _ = std::fs::remove_file(&path);
    match output {
        Ok(output) if output.status.success() => {
            Ok(String::from_utf8_lossy(&output.stdout).into_owned())
        }
        Ok(output) => Err(vec![String::from_utf8_lossy(&output.stderr).into_owned()]),
        Err(error) => Err(vec![format!("could not run node: {error}")]),
    }
}

/// Compile and run, returning `(stdout, stderr, exit code)` whatever the exit —
/// for pinning the entry shim's failure contract (J6), where the exit CODE and
/// what reached stderr are the claims, not the stdout.
fn compile_and_run_status(source: &str) -> (String, String, i32) {
    use std::sync::atomic::{AtomicU32, Ordering};
    static COUNTER: AtomicU32 = AtomicU32::new(0);

    let javascript = compile(source).expect("expected a clean compile");
    let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
    let path = std::env::temp_dir().join(format!("vilan_exit_{}_{unique}.mjs", std::process::id()));
    std::fs::write(&path, javascript).expect("write script");
    let output = std::process::Command::new("node")
        .arg(&path)
        .output()
        .expect("run node");
    let _ = std::fs::remove_file(&path);
    (
        String::from_utf8_lossy(&output.stdout).into_owned(),
        String::from_utf8_lossy(&output.stderr).into_owned(),
        output.status.code().unwrap_or(-1),
    )
}

/// Compile, then execute the emitted JS with `node`, returning its stdout. A
/// compile failure or a non-zero exit becomes `Err`. This catches *runtime*
/// miscompiles — a program that type-checks but emits the wrong code (e.g. a
/// generic dispatch that resolves to `undefined`) — which `assert_compiles`
/// alone cannot see.
fn compile_and_run(source: &str) -> Result<String, Vec<String>> {
    run_js(&compile(source)?)
}

/// `compile_and_run`, but timing only the RUN (E32): `compile` happens
/// first and is excluded from the returned `Duration`. For claims about the
/// emitted PROGRAM's own runtime behavior (a cancellation reacting inside
/// some window), the harness's compile step is noise — it reruns `std`
/// analysis in-process and can itself run to several seconds under load,
/// which used to be folded into (and starve) these tests' timing budget.
fn compile_and_run_timed(source: &str) -> (Result<String, Vec<String>>, std::time::Duration) {
    match compile(source) {
        Ok(js) => {
            let started = std::time::Instant::now();
            let result = run_js(&js);
            (result, started.elapsed())
        }
        Err(errors) => (Err(errors), std::time::Duration::ZERO),
    }
}

#[track_caller]
fn assert_compiles_and_runs(source: &str, expected_stdout: &str) {
    match compile_and_run(source) {
        Ok(stdout) => assert_eq!(stdout, expected_stdout, "stdout mismatch"),
        Err(errors) => panic!("expected a clean run, got: {errors:#?}"),
    }
}

/// `assert_compiles_and_runs`, bounding only the RUN's wall clock (E32):
/// compile happens first, untimed, so the budget measures the emitted
/// program's own behavior rather than the harness's (load-sensitive)
/// compile step.
#[track_caller]
fn assert_runs_within(source: &str, expected_stdout: &str, budget: std::time::Duration) {
    let (outcome, elapsed) = compile_and_run_timed(source);
    match outcome {
        Ok(stdout) => assert_eq!(stdout, expected_stdout, "stdout mismatch"),
        Err(errors) => panic!("expected a clean run, got: {errors:#?}"),
    }
    assert!(
        elapsed < budget,
        "the run alone (compile excluded) took {elapsed:?}, budget was {budget:?}"
    );
}

/// Like `compile_and_run`, but a ZERO-exit run yields `(stdout, stderr)` — for
/// pinning what a program reports while CONTINUING (the unobserved
/// task-failure report goes to stderr; the process does not crash).
fn compile_and_run_capturing_stderr(source: &str) -> Result<(String, String), Vec<String>> {
    use std::sync::atomic::{AtomicU32, Ordering};
    static COUNTER: AtomicU32 = AtomicU32::new(0);

    let js = compile(source)?;
    let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
    let path = std::env::temp_dir().join(format!("vilan_task_{}_{unique}.mjs", std::process::id()));
    std::fs::write(&path, js).map_err(|error| vec![error.to_string()])?;
    let output = std::process::Command::new("node").arg(&path).output();
    let _ = std::fs::remove_file(&path);
    match output {
        Ok(output) if output.status.success() => Ok((
            String::from_utf8_lossy(&output.stdout).into_owned(),
            String::from_utf8_lossy(&output.stderr).into_owned(),
        )),
        Ok(output) => Err(vec![String::from_utf8_lossy(&output.stderr).into_owned()]),
        Err(error) => Err(vec![format!("could not run node: {error}")]),
    }
}

// --- Regression guards (must keep passing) ----------------------------------

#[test]
fn generic_method_calls_generic_methods_on_self() {
    // Bug A (fixed): `update` calls both `self.set` and `self.get` — two generic
    // method calls on the same receiver. This used to overflow the compiler.
    assert_compiles(
        r#"
        import std::shared::Shared;
        struct Cell<T> { value: Shared<T> }
        impl Cell<type T> {
            fun new(value: T): Cell<T> { Cell { value = Shared::new(value) } }
            fun get(self): T { self.value.read() }
            fun set(self, value: T) { self.value.write() = value; }
            fun update(self, f: |T| T) { self.set(f(self.get())); }
        }
        fun main() { let c = Cell::new(0); c.update(|n| n + 1); }
        "#,
    );
}

#[test]
fn reactive_map_sub_and_set_with() {
    assert_compiles(
        r#"
        import std::print;
        import std::reactive::{ Signal, Owner };
        fun main() {
            let owner = Owner::new();
            let count = Signal::new(0);
            let doubled = count.map(|n| n * 2);
            owner.take(doubled.sub(|n| print(n)));
            count.set_with(|n| n + 1);
        }
        "#,
    );
}

#[test]
fn owner_disposes_subscriptions_across_re_renders() {
    // A2: the leak fix. Mimics `bind_each` — `source` drives re-renders; each
    // render disposes the previous rows' subscriptions (`rows.dispose()`) and
    // creates fresh ones. After several renders only the *current* rows fire, so
    // the count stays bounded (a leak would give 6, not 2).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::reactive::{ Signal, Owner };
        fun main() {
            let source = Signal::new(0);
            let data = Signal::new(0);
            let rows = Owner::new();
            let fires = Shared::new(0);
            let outer = Owner::new();
            outer.take(source.sub(|_| {
                rows.dispose();
                rows.take(data.sub(|_| { fires.write() = fires.read() + 1; }));
                rows.take(data.sub(|_| { fires.write() = fires.read() + 1; }));
            }));
            source.set(1);
            source.set(2);
            fires.write() = 0;
            data.set(99);
            print(fires.read());
        }
        "#,
        "2\n",
    );
}

#[test]
fn generic_dispatch_to_extern_impl() {
    // A trait method on a generic, dispatching to a primitive's `[extern]` impl.
    assert_compiles(
        r#"
        import std::print;
        import std::display::{ Display, format };
        fun show<T: Display>(x: T): str { x.to_string() }
        fun main() { print(format(42)); print(show("hi")); }
        "#,
    );
}

#[test]
fn return_type_only_generic() {
    // A generic fixed only by the return type (no argument binds it).
    assert_compiles(
        r#"
        import std::print;
        import std::default::Default;
        fun make<T: Default>(): T { T::default() }
        fun main() { let n: i32 = make(); print(n); }
        "#,
    );
}

#[test]
fn collection_json_roundtrip() {
    assert_compiles(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::result::Result::{ self, Ok, Err };
        fun main() {
            let nums: Result<List<i32>, str> = List::from_json("[1,2,3]");
            print(nums is Ok(let ns) && ns.to_json() == "[1,2,3]");
        }
        "#,
    );
}

#[test]
fn nested_generic_containers() {
    // `Option<List<i32>>` etc. — generic args nested several deep must resolve.
    assert_compiles(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            let x: Option<List<i32>> = Some([1, 2, 3]);
            match x {
                Some(let list) => print(list.len()),
                None => print(0),
            }
        }
        "#,
    );
}

#[test]
fn recursion_self_and_mutual() {
    assert_compiles(
        r#"
        import std::print;
        fun fib(n: i32): i32 { if n < 2 { n } else { fib(n - 1) + fib(n - 2) } }
        fun is_even(n: i32): bool { if n == 0 { true } else { is_odd(n - 1) } }
        fun is_odd(n: i32): bool { if n == 0 { false } else { is_even(n - 1) } }
        fun main() { print(fib(10)); print(is_even(4)); }
        "#,
    );
}

#[test]
fn calling_a_non_function_still_errors() {
    // A real error must still be reported (not silently swallowed).
    assert_fails(
        r#"
        struct Point { x: i32 }
        fun main() { let p = Point { x = 1 }; p(); }
        "#,
    );
}

#[test]
fn generic_struct_infers_type_arg_from_literal() {
    // A generic struct built by literal infers its parameter from the field
    // value (`Box { value = 5 }` -> `Box<i32>`), so a later method dispatches
    // against the concrete element. Previously the initializer dropped the
    // inferred arg (`Box<>`), leaving `T` abstract.
    assert_compiles(
        r#"
        import std::print;
        import std::display::Display;
        struct Box<T> { value: T }
        impl Box<type T> { fun get(self): T { self.value } }
        fun main() { let b = Box { value = 5 }; print(b.get().to_string()); }
        "#,
    );
}

#[test]
fn generic_struct_infers_type_arg_from_constructor() {
    // The same inference through a static constructor: `Box::new(5)` binds the
    // *impl's* `T` from the argument even though `new` declares no generics of
    // its own. (Bug B in disguise — `Signal::new(0).map(|n| ..)` left `n`
    // abstract only because `count` itself was an abstract `Signal<T>`.)
    assert_compiles(
        r#"
        import std::print;
        import std::display::Display;
        struct Box<T> { value: T }
        impl Box<type T> {
            fun new(value: T): Box<T> { Box { value = value } }
            fun get(self): T { self.value }
        }
        fun main() { print(Box::new(5).get().to_string()); }
        "#,
    );
}

#[test]
fn generic_call_on_closure_parameter() {
    // Bug B (fixed): a closure passed to a generic method (`count.map(|n|
    // n.to_string())`) used to type `n` as an abstract generic, so the method
    // call on it couldn't dispatch. The real cause was that `Signal::new(0)`
    // left `count` as an abstract `Signal<T>`; with construction now inferring
    // `Signal<i32>`, `n` is `i32` and `to_string` dispatches.
    assert_compiles(
        r#"
        import std::print;
        import std::reactive::Signal;
        import std::display::Display;
        fun main() {
            let count = Signal::new(0);
            let label = count.map(|n| n.to_string());
            label.sub(|s| print(s));
        }
        "#,
    );
}

#[test]
fn format_through_nested_generic() {
    // Bug C (fixed): a generic function passing its type parameter to another
    // generic call (`show<T: Display>(x) { format(x) }`) used to leave the nested
    // `format` un-monomorphized — its `value.to_string()` resolved to the empty
    // abstract `Display::to_string`, printing `undefined`. The cause was a binding
    // direction: the call reconciled argument-against-parameter, so a generic
    // argument bound *its own* constraint instead of the callee's. Reconciling
    // parameter-first binds `format`'s `U = T`, so it monomorphizes per `show`
    // instantiation.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::{ Display, format };
        fun show<T: Display>(x: T): str { format(x) }
        fun main() { print(show(7)); print(show("hi")); }
        "#,
        "7\nhi\n",
    );
}

#[test]
fn chained_derive_binds_method_generic_from_closure_return() {
    // A chained `derive` (`count.map(|n| n * 2).map(|m| format(m))`) used to
    // emit `undefined`: the first `derive<U>` left its result `Signal<U>` abstract
    // because `U` (its *own* generic) was never bound from the closure's return
    // type, so the second `derive` saw an abstract element. Method calls now bind
    // their own generics from arguments, like free-function calls do.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        import std::display::format;
        fun main() {
            let count = Signal::new(3);
            let label = count.map(|n| n * 2).map(|m| format(m));
            label.sub(|s| print(s));
            count.set(10);
        }
        "#,
        "6\n20\n",
    );
}

#[test]
fn format_in_closure_argument() {
    // Bug c′ (fixed): a free generic function called with an unannotated closure
    // parameter (`count.map(|n| format(n))`) emitted `undefined`. The call
    // resolved while `n` was still `Unknown` (its type lands only once `derive`
    // resolves), committed with no generic binding, and was never revisited.
    // Fixed by deferring the call while an argument is an unknown closure
    // parameter — the same rule the method-call resolver already applies to an
    // unknown closure *receiver* — so it re-resolves once `n` becomes `i32`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        import std::display::format;
        fun main() {
            let count = Signal::new(0);
            let label = count.map(|n| format(n));
            label.sub(|s| print(s));
            count.set(5);
        }
        "#,
        "0\n5\n",
    );
}

#[test]
fn method_closure_param_inferred_from_argument_generic() {
    // A method's own generic bound from a (nested) argument must reach its closure
    // parameters: `pick<T, K>(rows: List<List<T>>, key: |T| K, get: |T| i32)` typed
    // `|p| p.id`'s `p` as the abstract `T` until the own-generic binding ran first.
    // This is the `bind_each(source: Signal<List<T>>, |todo| todo.id, ..)` shape.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        struct P { id: i32 }
        struct Holder { tag: i32 }
        impl Holder {
            fun pick<T, K>(self, rows: List<List<T>>, key: |T| K, get: |T| i32): i32 {
                get(rows[0][0])
            }
        }
        fun main() {
            let h = Holder { tag = 0 };
            print(h.pick([[P { id = 42 }]], |p| p.id, |p| p.id).to_string());
        }
        "#,
        "42\n",
    );
}

#[test]
fn logical_or_operator() {
    // `||` is logical-or: binds looser than `&&`, short-circuits, and an empty
    // closure `|| body` still parses (it's tried before the operator).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun boom(): bool { print("evaluated"); true }
        fun main() {
            let a = "x";
            print(a == "x" || a == "y");
            print(a == "z" || a == "y");
            print(a == "x" && false || a == "x");
            print(true || boom());
            let f = || 7;
            print(f());
        }
        "#,
        "true\nfalse\ntrue\ntrue\n7\n",
    );
}

#[test]
fn reactive_combine_variadic() {
    // The driving example: `combine` is variadic over its inputs' distinct types
    // via a mapped-tuple parameter, yielding a `Signal` of the tuple that
    // recomputes when any input changes. The consumer destructures the tuple with
    // a closure tuple binder.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        import std::reactive::{ Signal, combine };
        fun main() {
            let a = Signal::new(1);
            let b = Signal::new("x");
            let c = Signal::new(true);
            let combined: Signal<(i32, str, bool)> = combine((a, b, c));
            combined.sub(|(n, s, flag)| print(i"{n.to_string()} {s} {flag}"));
            a.set(2);
            b.set("y");
        }
        "#,
        "1 x true\n2 x true\n2 y true\n",
    );
}

#[test]
fn tuple_comprehension_over_mapped_source() {
    // A tuple comprehension `(x in xs => e)` maps each element of a mapped-tuple
    // source through the body, typing as `(U in T: <body>)`. Here `source.len()`
    // collapses `(List<i32>, List<str>)` to `(i32, str) = T`. Lowers to a runtime
    // `.map`, so it's arity-independent.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun lengths<T: (2..)>(sources: (U in T: List<U>)): T {
            (source in sources => source.len())
        }
        fun main() {
            let (a, b) = lengths(([1, 2, 3], ["a", "b"]));
            print(i"{a.to_string()} {b.to_string()}");
        }
        "#,
        "3 2\n",
    );
}

#[test]
fn mapped_tuple_forward_expansion() {
    // A mapped tuple type with a concrete source expands element-wise:
    // `(U in (i32, str): List<U>)` is `(List<i32>, List<str>)`, so each binding
    // dispatches concretely.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun main() {
            let pair: (U in (i32, str): List<U>) = ([1, 2], ["x", "y", "z"]);
            let (nums, strs) = pair;
            print(i"{nums.len().to_string()} {strs.len().to_string()}");
        }
        "#,
        "2 3\n",
    );
}

#[test]
fn mapped_tuple_inverted_inference() {
    // A generic function over a mapped parameter infers the source tuple `T` from
    // the argument by inverting the template per element: `id(([1,2,3], ["a","b"]))`
    // binds `T = (i32, str)`, so the result mapped type re-expands to
    // `(List<i32>, List<str>)`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun id<T: (2..)>(sources: (U in T: List<U>)): (U in T: List<U>) { sources }
        fun main() {
            let (nums, strs) = id(([1, 2, 3], ["a", "b"]));
            print(i"{nums.len().to_string()} {strs.len().to_string()}");
        }
        "#,
        "3 2\n",
    );
}

#[test]
fn tuple_arity_bounds_parse() {
    // The tuple-bound grammar — `(..)`, `(2..)`, `(..10)`, and a per-element
    // bound `(2..: Display)` — parses and the parameter behaves as a generic
    // tuple. (Arity isn't enforced, mirroring trait bounds, which aren't either.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun any<T: (..)>(x: T): T { x }
        fun two<T: (2..)>(x: T): T { x }
        fun small<T: (..10)>(x: T): T { x }
        fun shown<T: (2..: Display)>(x: T): T { x }
        fun main() {
            let (a, b) = two((1, 2));
            let (c, d, e) = any((3, 4, 5));
            print(i"{a.to_string()} {b.to_string()} {c.to_string()} {d.to_string()} {e.to_string()}");
        }
        "#,
        "1 2 3 4 5\n",
    );
}

#[test]
fn nested_tuple_flat_lowering() {
    // A nested tuple stores flat (`((1,2),3)` -> `[1,2,3]`), so a matching nested
    // pattern reads flat offsets and a sub-tuple capture reslices — all behaviorally
    // transparent. Distinct types are preserved: the pattern must match the nesting.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun main() {
            let a = (1, 2);
            let b = (a, 3);
            let ((x, y), z) = b;
            print(i"{x.to_string()} {y.to_string()} {z.to_string()}");
            let (pair, last) = b;
            let (pa, pb) = pair;
            print(i"{pa.to_string()} {pb.to_string()} {last.to_string()}");
        }
        "#,
        "1 2 3\n1 2 3\n",
    );
}

#[test]
fn parameter_tuple_destructuring() {
    // A tuple binder in parameter position — both a function parameter
    // (`fun f((a, b): T)`) and a closure parameter (`|(a, b)|`) — destructures,
    // typing each binding from the matched tuple element.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun sum_pair((a, b): (i32, i32)): i32 { a + b }
        fun apply(pair: (i32, str), f: |(i32, str)| str): str { f(pair) }
        fun main() {
            print(sum_pair((3, 4)).to_string());
            print(apply((7, "x"), |(n, label)| i"{n.to_string()}{label}"));
        }
        "#,
        "7\n7x\n",
    );
}

#[test]
fn nested_parameter_tuple_destructuring() {
    // A nested tuple binder in a closure parameter, dispatched through a generic
    // reactive `derive` so the parameter type is inferred, not annotated.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun main() {
            let f = |(a, (b, c)): (i32, (i32, str))| i"{a.to_string()} {b.to_string()} {c}";
            print(f((1, (2, "z"))));
        }
        "#,
        "1 2 z\n",
    );
}

#[test]
fn let_tuple_destructuring() {
    // `let (a, b, c) = tuple` destructures, typing each binding from the tuple's
    // element types (so a method call on a binding dispatches concretely).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun pair(): (i32, str) { (7, "x") }
        fun main() {
            let (a, (b, c)) = (1, (2, 3));
            let (n, label) = pair();
            print(i"{a} {b} {c} {n.to_string()} {label}");
        }
        "#,
        "1 2 3 7 x\n",
    );
}

// --- Transparent references (implicit place, explicit value) ----------------

#[test]
fn transparent_references_write_through() {
    // R5: assigning *through* a view writes to its referent with no `*` — a view
    // binding, a `&mut` parameter, a re-borrow, a `borrows`-returning call, and a
    // captured `Option<&mut T>`, for plain `=` and compound `+=` / `/=`. Reading a
    // view as a value keeps its explicit `*`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun add_ten(x: &mut i32) { x += 10; }
        fun same(x: &mut i32): &mut i32 borrows x { x }
        struct Cell { value: i32 }
        impl Cell { fun slot(&mut self): Option<&mut i32> { Some(&mut self.value) } }
        fun main() {
            mut a: i32 = 10;
            let b: &mut i32 = &mut a;
            let c: &mut i32 = b;
            b = 20;
            print(i"{a} {*b} {*c}");
            add_ten(&mut a);
            print(i"{a} {*b}");
            add_ten(b);
            print(i"{a} {*b}");
            same(c) /= 10;
            print(i"{a} {*b}");
            mut cell = Cell { value = 100 };
            match cell.slot() {
                Some(let s) => { s += 5 }
                None => {}
            }
            print(cell.value);
        }
        "#,
        "20 20 20\n30 30\n40 40\n4 4\n105\n",
    );
}

#[test]
fn transparent_references_reject_deref_assignment() {
    // R6: `*` is value extraction (an rvalue) and may not be an assignment
    // target — write `v = …`, not `*v = …`.
    assert_fails(
        r#"
        fun main() { mut a = 5; let v: &mut i32 = &mut a; *v = 9; }
        "#,
    );
}

#[test]
fn transparent_references_reject_mut_view_binding() {
    // R7: a view binding cannot be `mut` — a view cannot be rebound.
    assert_fails(
        r#"
        fun main() { mut a = 5; mut v: &mut i32 = &mut a; v = 9; }
        "#,
    );
}

#[test]
fn transparent_references_reject_view_into_value_binding() {
    // R1: a value annotation cannot bind a view — write `*` to copy the value out.
    assert_fails(
        r#"
        fun main() { mut a = 5; let v: &mut i32 = &mut a; let b: i32 = v; }
        "#,
    );
}

#[test]
fn a_view_annotation_over_a_value_initializer_names_the_mismatch() {
    // R1's view-annotated arm, textually (ledger row 18): the annotation
    // promises a view and the initializer is a value.
    assert_fails_with(
        r#"
        fun main() { mut a = 5; let v: &mut i32 = 9; }
        "#,
        "'v' is annotated as a view (`&[mut] T`) but its initializer is not a view; bind a `&[mut] place` to alias it.",
    );
}

#[test]
fn a_value_annotation_over_a_view_initializer_names_the_mismatch() {
    // R1's value-annotated arm, textually (ledger row 18) — the textual twin
    // of transparent_references_reject_view_into_value_binding above.
    assert_fails_with(
        r#"
        fun main() { mut a = 5; let v: &mut i32 = &mut a; let b: i32 = v; }
        "#,
        "'b' is annotated as a value but its initializer is a view; write `*` to copy the value out, or annotate `&[mut] T` to alias it.",
    );
}

#[test]
fn an_inline_option_view_transient_writes_through() {
    // C5.2: constructing an `Option<&mut T>` inline and immediately matching it —
    // the transient the spec's open question sanctioned. The `Some(&mut a)` never
    // outlives the `match`, so it doesn't escape; the capture binds the view and
    // writes through. Both the direct subject and the conditional form (`match if
    // c { Some(..) } else { None }`, the inline analogue of `Arena::get`).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut a = 5;
            match Some(&mut a) {          // direct scalar transient
                Some(let v) => { v = 99; }
                None => {}
            }
            print(a);                    // 99 — written through

            mut b = 10;
            let take = false;
            match if take { Some(&mut b) } else { None } {   // conditional
                Some(let v) => { v = 1; }
                None => { print("none"); }
            }
            print(b);                    // 10 — None branch, untouched
        }
        "#,
        "99\nnone\n10\n",
    );
}

#[test]
fn an_inline_aggregate_option_view_transient_writes_through() {
    // C5.2, aggregate flavor: the payload is a `&mut struct`, so the capture is
    // the value's own reference and `.field` write-through reaches the original.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Node { value: i32 }
        fun main() {
            mut node = Node { value = 1 };
            match Some(&mut node) {
                Some(let v) => { v.value = 42; }
                None => {}
            }
            print(node.value);           // 42
        }
        "#,
        "42\n",
    );
}

#[test]
fn a_view_parameter_forwarded_into_an_inline_transient_writes_through() {
    // C5.2, forward flavor: a bare `&mut` parameter passed straight into the
    // inline constructor (`Some(p)`) — the capture aliases the same view, so the
    // write reaches the caller's value. Scalar (`(base, key)`) and aggregate.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Node { value: i32 }
        fun bump_scalar(p: &mut i32) {
            match Some(p) { Some(let v) => { v += 1; } None => {} }
        }
        fun bump_field(p: &mut Node) {
            match Some(p) { Some(let v) => { v.value += 1; } None => {} }
        }
        fun main() {
            mut a = 41;
            bump_scalar(&mut a);
            print(a);              // 42

            mut n = Node { value = 41 };
            bump_field(&mut n);
            print(n.value);        // 42
        }
        "#,
        "42\n42\n",
    );
}

#[test]
fn a_forwarded_immutable_view_transient_rejects_a_write() {
    // C5.2 boundary: forwarding a `&` (read-only) view keeps its convention — a
    // write through the capture is still rejected.
    assert_fails(
        r#"
        import std::option::Option::{ self, Some, None };
        fun peek(p: &i32) {
            match Some(p) { Some(let v) => { v = 9; } None => {} }
        }
        fun main() { mut a = 5; peek(&a); }
        "#,
    );
}

#[test]
fn a_stored_inline_option_view_is_rejected() {
    // C5.2 boundary: the sanction is for the *transient* only. Binding the same
    // `Some(&mut a)` to a `let` stores the view in an enum payload that outlives
    // the statement — a real escape, still rejected.
    assert_fails(
        r#"
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut a = 5;
            let stored = Some(&mut a);
            match stored {
                Some(let v) => { v = 9; }
                None => {}
            }
        }
        "#,
    );
}

#[test]
fn transparent_references_reject_value_into_view_binding() {
    // R1: a view annotation (`&mut T`) cannot bind a value.
    assert_fails(
        r#"
        fun main() { mut a = 5; let v: &mut i32 = &mut a; let b: &mut i32 = *v; }
        "#,
    );
}

// --- C8: `Arena.get` migrated to the view-returning form --------------------
// `fun get(&self, handle): Option<&T> borrows self` (memory-management-rev-1
// §"A reusable arena in std"; spec §6.0/§6.7's table names this as current).
// The recognized wrapped-view leaf is `Some(&<T-place>)`, so std's `Slot` now
// stores `value: T` (not `Option<T>`) to expose that place; occupancy is
// generation-only, exactly as the proposal's own `get`/`remove` check.

#[test]
fn arena_get_returns_a_readable_view() {
    // The view reads into the arena: both a scalar field and a `List` field of
    // the live value are reachable through the `Some(let node)` capture — the
    // graph-walk shape a view-returning `get` exists for.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        struct Node { value: i32, edges: List<i32> }
        fun main() {
            mut arena: Arena<Node> = Arena::new();
            let h = arena.insert(Node { value = 7, edges = [1, 2] });
            match arena.get(h) {
                Some(let node) => {
                    print(node.value);           // 7 — field read through the view
                    mut total = 0;
                    for edge in node.edges { total = total + edge; }
                    print(total);                // 3 — list field walked through the view
                }
                None => { print(-1); }
            }
        }
        "#,
        "7\n3\n",
    );
}

#[test]
fn arena_get_on_a_stale_handle_is_none() {
    // Removal bumps the slot's generation, so the old handle no longer matches
    // and `get` returns `None`. A reused slot takes the bumped generation, so an
    // old handle to it stays stale; an untouched handle keeps reading.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun read(arena: Arena<i32>, handle: Handle<i32>): i32 {
            match arena.get(handle) { Some(let v) => *v, None => -1 }
        }
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let a = arena.insert(10);
            let b = arena.insert(20);
            arena.remove(b);
            print(read(arena, b));               // -1 — stale after removal
            let c = arena.insert(30);            // reuses b's slot at a new generation
            print(read(arena, c));               // 30
            print(read(arena, b));               // -1 — old handle stays stale
            print(read(arena, a));               // 10 — untouched
        }
        "#,
        "-1\n30\n-1\n10\n",
    );
}

#[test]
fn arena_get_on_a_data_arena_round_trips() {
    // A scalar/data arena's whole cycle is unchanged by the migration: insert,
    // read via `get`, overwrite via `set`, `remove` (owned `Option<T>`), `len`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let a = arena.insert(1);
            let b = arena.insert(2);
            print(arena.len());                  // 2
            arena.set(b, 99);
            match arena.get(b) { Some(let v) => print(*v), None => print(-1) }  // 99
            print(arena.remove(a).unwrap_or(-1)); // 1
            print(arena.len());                  // 1
        }
        "#,
        "2\n99\n1\n1\n",
    );
}

#[test]
fn arena_get_returns_a_view_not_a_copy() {
    // The distinguisher from the old copy-returning `get(): Option<T>`: the
    // `Some(let view)` capture is now a *view*, so storing it in a struct field
    // is a view escape. Under the old form `view` was an owned `Cell` and this
    // compiled — turning it into an error is exactly what the migration does.
    assert_fails_with(
        r#"
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        struct Cell { n: i32 }
        struct Keeper { held: Cell }
        fun main() {
            mut arena: Arena<Cell> = Arena::new();
            let h = arena.insert(Cell { n = 1 });
            match arena.get(h) {
                Some(let view) => { let k = Keeper { held = view }; }
                None => {}
            }
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn arena_mutation_under_a_live_get_view_is_rejected() {
    // C10 closed (rule-4 completion S3): a wrapped-view `match` capture anchors
    // at the arena, so a BUMPING mutation (`insert` — grows/reuses slots) inside
    // the arm fires E2. (`set` no longer invalidates — it is the stable table
    // row; the accept twin is `arena_set_under_a_live_get_view_is_accepted`.)
    assert_fails_with(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let h = arena.insert(10);
            match arena.get(h) {
                Some(let v) => { arena.insert(30); print(*v); }
                None => {}
            }
        }
        "#,
        "while a view into it is live",
    );
}

#[test]
fn arena_set_under_a_live_get_view_is_accepted() {
    // The C10+C6 showcase: the capture is anchored (C10), and `set` — an
    // in-place slot overwrite, the stable table row — does not bump (C6), so
    // holding the view across it is legal.
    assert_compiles(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let h = arena.insert(10);
            let h2 = arena.insert(11);
            match arena.get(h) {
                Some(let v) => { arena.set(h2, 20); print(*v); }
                None => {}
            }
        }
        "#,
    );
}

// --- C7: wire-blessed handles (`claims-and-epochs.md` §6) -------------------
// A handle is a NAME — durable identity plus the epoch to re-validate against —
// so it is the one alias that crosses the wire. `Handle<T>` now carries
// `[derive(Wire)]`; the `T` is phantom, so the payload is exactly the two
// integers, and a `[derive(Wire)]` type may carry a handle field.

#[test]
fn a_handle_round_trips_through_the_json_codec() {
    // The naming-layer idiom end to end: a handle issued by a server-side arena
    // encodes as `{index, generation}`, decodes back, and still resolves.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::json::{ encode_json, decode_json };
        import std::result::Result::{ self, Ok, Err };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let handle = arena.insert(7);
            let text = encode_json(handle);
            print(text);
            let back: Result<Handle<i32>, str> = decode_json(text);
            match back {
                Ok(let name) => print(arena.get(name).unwrap_or(-1)),
                Err(let reason) => print(reason),
            }
        }
        "#,
        "{\"index\":0,\"generation\":0}\n7\n",
    );
}

#[test]
fn a_handle_round_trips_through_the_binary_codec() {
    // The same name over the binary codec — the visitor impls the derive emits
    // are codec-neutral, so both channels rebuild the same two integers.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::binary::{ encode_binary, decode_binary };
        import std::result::Result::{ self, Ok, Err };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let a = arena.insert(5);
            let b = arena.insert(6);
            let back: Result<Handle<i32>, str> = decode_binary(encode_binary(b));
            match back {
                Ok(let name) => print(arena.get(name).unwrap_or(-1)),
                Err(let reason) => print(reason),
            }
            print(arena.get(a).unwrap_or(-1));
        }
        "#,
        "6\n5\n",
    );
}

#[test]
fn a_stale_handle_from_the_wire_resolves_to_none() {
    // The distributed staleness story: a client acting on an entity another
    // client deleted gets the SAME clean `None` as local code holding a stale
    // handle — no phantom write, one rule from a local `List` to an RPC
    // boundary.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::json::{ encode_json, decode_json };
        import std::result::Result::{ self, Ok, Err };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::new();
            let handle = arena.insert(7);
            let quoted = encode_json(handle);        // the client keeps the name
            arena.remove(handle);                    // someone else deletes it
            let back: Result<Handle<i32>, str> = decode_json(quoted);
            match back {
                Ok(let name) => print(arena.get(name).unwrap_or(-1)),  // -1
                Err(let reason) => print(reason),
            }
            // `set` through a stale name changes nothing, and reports it.
            match back {
                Ok(let name) => print(arena.set(name, 99)),            // false
                Err(let reason) => print(reason),
            }
        }
        "#,
        "-1\nfalse\n",
    );
}

#[test]
fn a_wire_type_may_carry_a_handle_field() {
    // The phantom-parameter case the derive had to tolerate: `Handle<T>` is an
    // APPLIED derived type, which the all-fields Wire check used to reject
    // outright ("which is not Wire"). The `T` never reaches the payload.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::json::{ encode_json, decode_json };
        import std::result::Result::{ self, Ok, Err };
        import std::option::Option::{ self, Some, None };
        [derive(Wire)]
        struct Rename { node: Handle<str>, title: str }
        fun main() {
            mut arena: Arena<str> = Arena::new();
            let handle = arena.insert("old");
            let command = Rename { node = handle, title = "new" };
            let text = encode_json(command);
            print(text);
            let back: Result<Rename, str> = decode_json(text);
            match back {
                Ok(let request) => {
                    arena.set(request.node, request.title);
                    print(arena.get(request.node).unwrap_or("gone"));
                }
                Err(let reason) => print(reason),
            }
        }
        "#,
        "{\"node\":{\"index\":0,\"generation\":0},\"title\":\"new\"}\nnew\n",
    );
}

#[test]
fn a_handle_names_an_entity_whose_type_is_not_itself_wire() {
    // A name is not the thing it names: `Handle<T>` is sendable whatever `T` is
    // — the point of the naming layer (the entity stays on the server). The
    // generic argument is deliberately unconstrained, which is sound only
    // because a derived type's parameters are necessarily phantom
    // (`a_wire_type_with_a_parameter_typed_field_is_rejected` is the other half).
    assert_compiles(
        r#"
        import std::arena::{ Arena, Handle };
        struct Session { socket: |str| void }
        [derive(Wire)]
        struct Close { target: Handle<Session> }
        fun main() {
            mut sessions: Arena<Session> = Arena::new();
            let handle = sessions.insert(Session { socket = |line| {} });
            let close = Close { target = handle };
        }
        "#,
    );
}

#[test]
fn a_wire_type_with_a_parameter_typed_field_is_rejected() {
    // The guard behind C7's unconstrained generic arguments: a `[derive(Wire)]`
    // type whose field is typed by a PARAMETER is rejected at its own
    // declaration (the derive emits no generic impls), so no derived type can
    // put a generic argument on the wire. If generic Wire derives ever land,
    // `is_wire_type` must start checking the arguments.
    assert_fails_with(
        r#"
        [derive(Wire)]
        struct Pair<T> { value: T, count: i32 }
        "#,
        "which is not Wire",
    );
}

#[test]
fn a_branded_arena_rejects_a_foreign_handle() {
    // `claims-and-epochs.md` §6's capability note: per-session arenas are the
    // blessed default, and anything cross-tenant adds a per-arena random brand
    // so a handle from one arena names nothing in another. Without a brand, an
    // equal-index/equal-generation handle from a DIFFERENT arena resolves —
    // which is why the per-session scoping stays the rule and the brand is the
    // belt to it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun main() {
            // The UNBRANDED control first — it is what makes this pin
            // discriminate: two plain arenas number from 0, so the foreign
            // handle resolves to the other arena's slot of the same index.
            mut plain: Arena<i32> = Arena::new();
            mut plain_other: Arena<i32> = Arena::new();
            let loose = plain.insert(7);
            plain_other.insert(9);
            print(plain_other.get(loose).unwrap_or(-1));   // 9 — the confusion

            mut mine: Arena<i32> = Arena::branded();
            mut theirs: Arena<i32> = Arena::branded();
            let handle = mine.insert(7);
            theirs.insert(9);
            print(theirs.get(handle).unwrap_or(-1));   // -1 — a foreign name
            print(mine.get(handle).unwrap_or(-1));     // 7
        }
        "#,
        "9\n-1\n7\n",
    );
}

#[test]
fn a_branded_arenas_generational_cycle_is_unchanged() {
    // Branding only moves where the counters START, so every generational rule
    // holds above the brand: removal bumps the slot, the old handle goes stale,
    // and a reused slot issues a fresh handle that reads. (The plain-arena twin
    // is `arena_get_on_a_stale_handle_is_none`.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::arena::{ Arena, Handle };
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut arena: Arena<i32> = Arena::branded();
            let handle = arena.insert(7);
            print(arena.get(handle).unwrap_or(-1));     // 7
            arena.remove(handle);
            print(arena.get(handle).unwrap_or(-1));     // -1 — stale
            let reused = arena.insert(30);              // reuses the slot
            print(arena.get(reused).unwrap_or(-1));     // 30
            print(arena.get(handle).unwrap_or(-1));     // -1 — stays stale
            print(arena.set(handle, 99));               // false — no phantom write
            print(arena.len());                         // 1
        }
        "#,
        "7\n-1\n30\n-1\nfalse\n1\n",
    );
}

// --- rule4-completion S1: the `borrows` root-set (inference only) -----------
// `Function.borrows` records *which* parameter positions a returned view
// projects (receiver = position 0), inferred and chained. Inference-only: no
// enforcement changed, the corpus stays byte-identical. These pin the behavior
// each root-set drives; the projected positions themselves surface in the
// language-server hover tests (`borrows self`, `borrows a, b`, `borrows b`).

#[test]
fn direct_projection_borrows_the_receiver() {
    // A `&mut self` method returning `&mut self.field` projects the receiver
    // (position 0): the write through the projection reaches the receiver, and a
    // binding of the call is a writable view. The inferred twin of `borrows.vl`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Wrapper { value: i32 }
        impl Wrapper { fun slot(&mut self): &mut i32 { &mut self.value } }
        fun main() {
            mut w = Wrapper { value = 1 };
            w.slot() = 10;
            print(w.value);          // 10 — written through the projection
            let v = w.slot();
            v = 25;
            print(w.value);          // 25 — written through the bound view
        }
        "#,
        "10\n25\n",
    );
}

#[test]
fn chained_projection_maps_through_a_borrows_call() {
    // A return leaf that is itself a borrows-call: `outer` returns `self.inner()`
    // where `inner` borrows self, so the callee's {0} maps back through the
    // receiver to `outer`'s {0}. Before the root-set this call-tail was not
    // recognized as a view (it miscompiled); the chain now lowers it correctly.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Wrapper { value: i32 }
        impl Wrapper {
            fun inner(&mut self): &mut i32 borrows self { &mut self.value }
            fun outer(&mut self): &mut i32 { self.inner() }
        }
        fun main() {
            mut w = Wrapper { value = 1 };
            w.outer() = 42;
            print(w.value);          // 42
        }
        "#,
        "42\n",
    );
}

#[test]
fn chained_projection_maps_a_non_receiver_argument() {
    // The chain maps the callee's *position* through the call's arguments: a free
    // `pick(a, b)` returning `grow(b)` — where `grow` borrows its position-0
    // parameter — projects `b`, the caller's position 1, not `a`. Only `q` (bound
    // to `b`) is written; `p` is untouched, proving the mapping is positional.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun grow(x: &mut i32): &mut i32 borrows x { x }
        fun pick(a: &mut i32, b: &mut i32): &mut i32 { grow(b) }
        fun main() {
            mut p = 1;
            mut q = 2;
            pick(&mut p, &mut q) = 9;
            print(p);                // 1 — untouched
            print(q);                // 9 — projected through b
        }
        "#,
        "1\n9\n",
    );
}

#[test]
fn multi_parameter_projection_unions_branch_positions() {
    // An `if` returning a wrapped view of a *different* parameter per leg unions
    // their positions → {0, 1}: each branch's projection writes through to the
    // chosen parameter. The every-leaf-agrees rule still holds (both legs `&mut`,
    // both aggregate) — a recognized wrapped view, not an escape.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Box { x: i32 }
        fun pick(a: &mut Box, b: &mut Box, first: bool): Option<&mut i32> {
            if first { Some(&mut a.x) } else { Some(&mut b.x) }
        }
        fun main() {
            mut p = Box { x = 1 };
            mut q = Box { x = 2 };
            match pick(&mut p, &mut q, true) { Some(let v) => { v = 90; } None => {} }
            match pick(&mut p, &mut q, false) { Some(let v) => { v = 91; } None => {} }
            print(p.x);              // 90 — first branch projected a
            print(q.x);              // 91 — second branch projected b
        }
        "#,
        "90\n91\n",
    );
}

#[test]
fn a_wrapped_view_return_projects_its_parameter() {
    // The wrapped `Option<&mut T>` shape records the projected position exactly
    // like a bare view return: un-annotated, `slot` borrows self (position 0),
    // and the captured view writes through. (The `transparent-references.vl`
    // `Cell::slot` shape — the root-set now records it without changing codegen.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Cell { value: i32 }
        impl Cell { fun slot(&mut self): Option<&mut i32> { Some(&mut self.value) } }
        fun main() {
            mut cell = Cell { value = 1 };
            match cell.slot() { Some(let v) => { v = 7; } None => {} }
            print(cell.value);       // 7
        }
        "#,
        "7\n",
    );
}

#[test]
fn an_explicit_borrows_clause_agrees_with_inference() {
    // `borrows self` names position 0; inference of the same body also yields
    // {0} — they agree (the union is idempotent, no check contradicts). The
    // annotated form compiles and writes through identically to the inferred one.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Wrapper { value: i32 }
        impl Wrapper { fun slot(&mut self): &mut i32 borrows self { &mut self.value } }
        fun main() {
            mut w = Wrapper { value = 3 };
            w.slot() = 8;
            print(w.value);          // 8
        }
        "#,
        "8\n",
    );
}

#[test]
fn a_returned_view_of_a_local_is_still_rejected() {
    // The escape boundary is unchanged: a view of a *local* (not a parameter)
    // projects no position, so the root-set stays empty and the view escapes —
    // rejected exactly as before the root-set. (S1 records positions; it does
    // not relax enforcement.)
    assert_fails_with(
        r#"
        fun leak(): &mut i32 { mut local = 1; &mut local }
        fun main() { let v = leak(); }
        "#,
        "a view cannot escape its scope",
    );
}

// --- A1: `Shared::write(): &mut T borrows self` -----------------------------

#[test]
fn shared_write_view_rebinds_and_mutates_through_handles() {
    // Writing a whole value through the view rebinds the cell's slot, so every
    // handle (a clone) sees it; a method call mutates in place. The rebind must
    // NOT merge — the old aggregate-view `Object.assign` path would have left a
    // stale tail (len 3 then 4 instead of 1 then 2).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        fun main() {
            let a: Shared<List<i32>> = Shared::new([1, 2, 3]);
            let b = a.clone();
            a.write() = [9];
            print(b.read().len());
            a.write().push(8);
            print(b.read().len());
        }
        "#,
        "1\n2\n",
    );
}

#[test]
fn own_parameter_is_a_mutable_copy() {
    // `own x: T` consumes a copy the callee may mutate freely — reassign a scalar,
    // or rebind an aggregate — without affecting the caller (an aggregate is
    // cloned at the call site). Reassigning an `own` parameter used to be rejected
    // ("cannot assign to this expression"); it is now allowed.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun bump(own x: i32): i32 { x += 1; x }
        fun grow(own xs: List<i32>): i32 { xs = [7, 8, 9, 10]; xs.len() }
        fun main() {
            mut a = 10;
            print(bump(a)); // 11
            print(a);       // 10 — caller untouched
            mut list = [1, 2];
            print(grow(list)); // 4
            print(list.len()); // 2 — caller untouched
        }
        "#,
        "11\n10\n4\n2\n",
    );
}

// --- H9: `mut` parameters (proposal/mut-parameters.md) ---------------------
// `fun f(mut x: T) { body }` ≡ `fun f(x': T) { mut x = x'; body }` — binder
// mutability of the callee's by-value copy, exclusive with conventions,
// never part of the signature.

#[test]
fn a_mut_parameter_rebinds_its_copy() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun bump(mut x: i32): i32 { x = x + 1; x }
        fun main() { print(bump(1)); }
        "#,
        "2\n",
    );
}

#[test]
fn a_mut_parameter_is_invisible_to_the_caller() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun grow(mut xs: List<i32>): i32 { xs.push(9); xs.len() }
        fun main() {
            mut list = [1, 2];
            print(grow(list));  // 3 — the callee's copy grew
            print(list.len());  // 2 — the caller's value untouched
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_plain_parameter_beside_a_mut_one_still_rejects_writes() {
    // The mixed list pins two things: `mut` is per-parameter, and the plain
    // parameter's rejection now offers BOTH spellings (copy vs caller).
    assert_fails_with(
        r#"
        fun f(mut a: i32, b: i32) { a = 1; b = 2; }
        fun main() { f(1, 2); }
        "#,
        "declare it `mut b` to mutate this function's copy, or `&mut b` to mutate the caller's value",
    );
}

#[test]
fn a_mut_parameter_takes_field_writes() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Point { x: i32 }
        fun place(mut p: Point): i32 { p.x = 42; p.x }
        fun main() { print(place(Point { x = 0 })); }
        "#,
        "42\n",
    );
}

#[test]
fn a_closure_mut_parameter_works_unannotated() {
    // The field case that filed H9, verbatim: mutating a `Signal<List<T>>`
    // via `set_with(|mut list| { list.push(..); list })`. The closure's
    // parameter type lands from `set_with`'s declared signature.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        fun main() {
            mut seed = [1, 2];
            let numbers = Signal::new(seed);
            numbers.set_with(|mut list| {
                list.push(5);
                list
            });
            print(numbers.get().len());
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_closure_mut_parameter_types_from_a_declared_closure_argument() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun apply(xs: List<i32>, grow: |List<i32>| i32): i32 { grow(xs) }
        fun main() {
            mut list = [1, 2];
            print(apply(list, |mut xs| {
                xs.push(5);
                xs.len()
            }));
            print(list.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_closure_mut_parameter_works_annotated() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let bump = |mut v: i32| { v = v + 1; v };
            print(bump(1));
        }
        "#,
        "2\n",
    );
}

#[test]
fn mut_self_is_the_builder_idiom() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Point { x: i32 }
        impl Point {
            fun with_x(mut self, value: i32): Point { self.x = value; self }
        }
        fun main() {
            let original = Point { x = 0 };
            let moved = original.with_x(9);
            print(moved.x);
            print(original.x); // the receiver copy mutated; the original didn't
        }
        "#,
        "9\n0\n",
    );
}

#[test]
fn a_mut_parameter_roots_a_writable_view() {
    // `&mut x` of a `mut` parameter's copy is fine (readonly_root clears);
    // the view writes land in the copy, still invisible to the caller.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun poke(mut x: i32): i32 { let v = &mut x; v = 5; x }
        fun main() { print(poke(1)); }
        "#,
        "5\n",
    );
}

#[test]
fn a_mut_parameter_feeds_a_ref_mut_argument() {
    // A `mut` parameter is a mutable place, so passing `&mut` of it to a
    // writable-view parameter passes check_mutable_arguments.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun bump(c: &mut i32) { c += 1; }
        fun outer(mut x: i32): i32 { bump(&mut x); x }
        fun main() { print(outer(1)); }
        "#,
        "2\n",
    );
}

#[test]
fn mut_does_not_combine_with_a_convention() {
    assert_fails_with(
        r#"
        fun f(mut own x: i32) {}
        fun main() { f(1); }
        "#,
        "cannot combine with `own` or a view",
    );
}

#[test]
fn mut_does_not_combine_with_an_inferred_view_convention() {
    // `mut x: &mut i32` — no prefix, but the type makes the convention RefMut.
    assert_fails_with(
        r#"
        fun f(mut x: &mut i32) {}
        fun main() {}
        "#,
        "cannot combine with `own` or a view",
    );
}

#[test]
fn mut_needs_a_name_binder_not_a_destructure() {
    assert_fails_with(
        r#"
        fun f(mut (a, b): (i32, i32)) {}
        fun main() {}
        "#,
        "applies to a plain name",
    );
}

#[test]
fn an_external_fun_rejects_mut_parameters() {
    assert_fails_with(
        r#"
        external fun host(mut x: i32);
        fun main() {}
        "#,
        "an `external fun` has no body",
    );
}

#[test]
fn a_mut_parameter_never_takes_a_resource() {
    // R1: a resource never copies, and a `mut` parameter IS a copy — the
    // rejection steers to `own` (transfer), the sanctioned resource intake.
    assert_fails_with(
        r#"
        resource struct Conn { id: i32 }
        impl Conn { fun close(own self) {} }
        fun misuse(mut c: Conn) {}
        fun main() {}
        "#,
        "a resource never copies",
    );
}

#[test]
fn a_mut_destructure_capture_does_not_alias_its_source() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            mut (xs, n) = pair;
            xs.push(9);
            print(xs.len());
            print(pair.0.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn an_immutable_capture_is_isolated_from_source_mutation() {
    // B53, the read direction: after `let (xs, _) = pair`, growing `pair.0`
    // must not show through `xs` — the capture copied (subject roots a
    // `mut` binding, so the share elision does not apply).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            let (xs, n) = pair;
            pair.0.push(9);
            print(xs.len());
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_mut_match_capture_does_not_alias_the_subject() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            match pair {
                (mut xs, let n) => {
                    xs.push(9);
                    print(xs.len());
                    print(pair.0.len());
                }
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_returned_capture_does_not_leak_an_alias() {
    // B53's seam case, the `unwrap` leak: a capture that IS the leg's value
    // rides the return out of the callee — it must be a copy, or the
    // caller's `mut got` mutates the option's payload through the alias
    // (the "calls own their result" assumption every binding-copy elision
    // rests on).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            let held: Option<List<i32>> = Some([1, 2]);
            mut got = held.unwrap();
            got.push(9);
            print(got.len());
            match held {
                Some(let inner) => print(inner.len()),
                None => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_nested_variant_capture_does_not_alias() {
    // The capture sits two pattern levels deep (variant payload inside a
    // tuple) — collection recurses the whole tree, not just top level.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut wrapped = (Some([1, 2]), 3);
            match wrapped {
                (Some(mut xs), let n) => {
                    xs.push(9);
                    print(xs.len());
                }
                (None, _) => print(0),
            }
            match wrapped {
                (Some(let inner), _) => print(inner.len()),
                (None, _) => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn an_is_capture_does_not_alias_the_subject() {
    // B53 finding 1: `is` captures compile through the ALIAS path
    // (`compile_is_pattern` records an accessor into the subject and
    // substitutes it at every reference), which the first pass never taught
    // to copy — so this printed 3, the source's growth showing through.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            if pair is (let xs, let n) {
                pair.0.push(9);
                print(xs.len());
            }
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_mut_is_capture_does_not_write_back_to_the_subject() {
    // The write direction of the same hole: `mut v` aliased the option's
    // payload, so growing it grew what the option still holds (3/3).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut held: Option<List<i32>> = Some([1, 2]);
            if held is Some(mut v) {
                v.push(9);
                print(v.len());
            }
            match held {
                Some(let inner) => print(inner.len()),
                None => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_guarded_match_capture_does_not_alias_the_subject() {
    // A GUARD moves the leg onto the alias path too (the guard reads the
    // captures, so they cannot be `const`s inside the body) — the same
    // program as `a_mut_match_capture_does_not_alias_the_subject` printed
    // 3/3 with `if n > 0` added.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            match pair {
                (mut xs, let n) if n > 0 => {
                    xs.push(9);
                    print(xs.len());
                    print(pair.0.len());
                }
                _ => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_rejecting_guard_leaves_the_subject_untouched() {
    // The copy is made on ENTRY to the leg body, not when the pattern
    // matches: the first leg's guard rejects, so it has copied nothing and
    // consumed nothing and the SECOND guarded leg finds the subject exactly
    // as it was — and that leg's own capture is still a copy (3/3 before).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            match pair {
                (mut xs, let n) if n > 100 => {
                    xs.push(9);
                    print(0);
                }
                (mut xs, let n) if n > 0 => {
                    xs.push(7);
                    print(xs.len());
                    print(pair.0.len());
                }
                _ => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_braced_leg_capture_does_not_leak_an_alias() {
    // B53 finding 4: the value-seam scan only saw seams that were
    // syntactically a place, so BRACING the leg body — `Some(let inner) => {
    // inner }` — hid the seam and restored the `unwrap` leak (3/3). The scan
    // now looks through the forms that forward a value.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun take_it(held: Option<List<i32>>, fallback: List<i32>): List<i32> {
            match held {
                Some(let inner) => { inner }
                None => fallback,
            }
        }
        fun main() {
            let held: Option<List<i32>> = Some([1, 2]);
            mut got = take_it(held, List::new());
            got.push(9);
            print(got.len());
            match held {
                Some(let inner) => print(inner.len()),
                None => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_conditionally_returned_capture_does_not_leak_an_alias() {
    // The same hole through an `if` tail: neither `a` nor `b` is the
    // function's tail EXPRESSION, so neither rooted a seam and both shared
    // the caller's tuple (3/3).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun pick(pair: (List<i32>, List<i32>), first: bool): List<i32> {
            let (a, b) = pair;
            if first { a } else { b }
        }
        fun main() {
            let pair = ([1, 2], [5]);
            mut got = pick(pair, true);
            got.push(9);
            print(got.len());
            print(pair.0.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_shared_capture_is_not_an_elidable_move_source() {
    // B53 finding 3: the share elision and rule 2's move elision are each
    // sound alone and composed unsoundly — `xs` shared `pair.0` (immutable
    // capture, immutable subject, no seam) and was then read exactly once,
    // which made it an elidable-copy source, handing the shared storage to a
    // `mut` binding. `const xs = $a[0]; let ys = xs;` with no copy anywhere:
    // this printed 3. Only an OWNER may donate.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let pair = ([1, 2], 3);
            let (xs, n) = pair;
            mut ys = xs;
            ys.push(9);
            print(pair.0.len());
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_mut_capture_from_an_immutable_subject_copies() {
    // The share elision's other guard, on an IMMUTABLE subject (where the
    // elision is otherwise live — the sibling pins all use `mut pair`, which
    // disables it before this configuration is reached): a `mut` capture is
    // never shareable, because it can write.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let pair = ([1, 2], 3);
            mut (xs, n) = pair;
            xs.push(9);
            print(xs.len());
            print(pair.0.len());
        }
        "#,
        "3\n2\n",
    );
}

// --- B63(a): the share elision's predicate is SEMANTIC, not the diagnostic one -
//
// `readonly_root` answers "what `declare it …` advice applies", and it owes
// `None` for an `own` parameter because the advice would be `mut own x`, a parse
// error. The elision's question is different — "can this place change" — and an
// `own` parameter that nothing writes cannot. B60 reused the diagnostic helper
// for the semantic decision, which cost every `own self` combinator its share on
// data paths (`affine-moves.md` §5/§6); `share_subject_is_stable` splits them.

#[test]
fn an_own_parameter_capture_shares_when_nothing_writes_it() {
    // The elision itself, which no runtime output can see: the capture's slot
    // read emits bare. The one program-wide `__clone` site is this capture, so
    // asserting the helper is absent entirely is exact. (`Option::map`'s
    // monomorphized body in `vilan/test/closure-param-inference.js` is the
    // same elision seen in bytes — it regained its pre-B60 form here.)
    let source = r#"
        import std::print;
        fun peek(own pair: (List<i32>, i32)): i32 {
            let (first, second) = pair;
            first.len()
        }
        fun main() { print(peek(([ 1, 2 ], 3))); }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "the `own`-parameter capture still copies:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "2\n");
}

#[test]
fn an_own_parameter_capture_copies_when_a_method_writes_it() {
    // The soundness boundary the split creates, and why the predicate is a
    // WRITE SET rather than a blanket `own` admission: an `own` parameter is
    // freely writable (`h.n = 5` inside `fun f(own h: Holder)` compiles), so a
    // body that mutates it can observe the alias. `push` takes `&mut self`, so
    // the receiver's root joins the write set and the capture copies — 1, not 2.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun observe(own pair: (List<i32>, i32)): i32 {
            let (first, second) = pair;
            pair.0.push(7);
            first.len()
        }
        fun main() { print(observe(([ 1 ], 2))); }
        "#,
        "1\n",
    );
}

#[test]
fn an_own_parameter_capture_copies_when_an_assignment_writes_it() {
    // The write set's other source, on its own pin because the two are found
    // by different arms: a plain field assignment through the `own` parameter.
    // The capture must not see `[ 9, 9 ]` — 1, not 2.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { xs: List<i32> }
        fun observe(own pair: (Holder, i32)): i32 {
            let (first, second) = pair;
            pair.0.xs = [ 9, 9 ];
            first.xs.len()
        }
        fun main() { print(observe((Holder { xs = [ 1 ] }, 2))); }
        "#,
        "1\n",
    );
}

#[test]
fn a_generic_capture_moves_a_resource_instantiation() {
    // B53 finding 2, R11 (`docs/spec/memory.md`): a capture typed by a bare
    // generic parameter copied conservatively in EVERY monomorphization, so
    // `Option::unwrap`'s `Some(let x) => x` deep-copied a resource — two
    // owners with divergent state, where the spec names `unwrap(own self): T`
    // as the case that must pass with no copies.
    //
    // B60 then made the call a MOVE, so the source cannot be read afterwards
    // to compare the two (that is this test's rejection half, below); the
    // copy-vs-move evidence now runs through the destructor instead — a copy
    // would destroy two values with divergent fields, and
    // `a_moved_resource_instantiation_destroys_one_value` pins the single
    // `drop a n=7` that proves the caller holds THE resource, not a twin.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        resource struct Res {
            n: i32,
        }
        fun main() {
            mut o: Option<Res> = Some(Res { n = 1 });
            mut r = o.unwrap();
            r.n = 7;
            print(r.n);
        }
        "#,
        "7\n",
    );
}

#[test]
fn a_moved_resource_instantiation_destroys_one_value() {
    // The same fix seen through the destructor. The copy made TWO resources
    // and ran `drop` on each with divergent fields (`n=7` then `n=1`); the
    // move makes one, so both runs report the same value.
    //
    // It used to drop TWICE (`...done\ndrop a n=7`) — B60: `unwrap` took a
    // LOANED `self`, so the call marked no move and `o`'s scope-end teardown
    // still fired over the payload the caller now owned. `unwrap(own self)`
    // plus the loan-consumption rule closes it: the call is a move, so `o` is
    // not owned at scope end and the value is destroyed exactly once.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        import std::drop::{ Drop, drop };
        resource struct Res {
            tag: str,
            n: i32,
        }
        impl Res with Drop {
            fun drop(&mut self) {
                print(i"drop {self.tag} n={self.n}");
            }
        }
        fun main() {
            mut o: Option<Res> = Some(Res { tag = "a", n = 1 });
            mut r = o.unwrap();
            r.n = 7;
            print(i"r.n={r.n}");
            drop(r);
            print("done");
        }
        "#,
        "r.n=7\ndrop a n=7\ndone\n",
    );
}

#[test]
fn a_generic_aggregate_capture_moves_a_resource_instantiation() {
    // The same decision one level up: the capture is typed `Wrap<T>`, an
    // aggregate whatever `T` is, so it is not a bare generic — but `Wrap<Res>`
    // IS a resource, and the copy made two (7/1). The analyzer records which
    // constraints can turn the capture into a resource; the transformer asks
    // what this instance bound them to.
    //
    // `first_of` takes `own pair` (B60: a body may only consume what it owns —
    // it used to take the loan `pair: (Wrap<T>, i32)` and move a piece of it
    // out, which is what let `main` read `pair.0` afterwards and see the SAME
    // value through two owners). With the move enforced, the copy-vs-move
    // question is answered through the destructor: one `drop n=7` is the
    // single mutated resource; a copy would add a second at `n=1`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Res {
            n: i32,
        }
        impl Res with Drop {
            fun drop(&mut self) {
                print(i"drop n={self.n}");
            }
        }
        struct Wrap<T> {
            value: T,
        }
        fun first_of<T>(own pair: (Wrap<T>, i32)): Wrap<T> {
            let (a, b) = pair;
            a
        }
        fun main() {
            let pair = (Wrap { value = Res { n = 1 } }, 5);
            mut w = first_of(pair);
            w.value.n = 7;
            print(w.value.n);
        }
        "#,
        "7\ndrop n=7\n",
    );
}

#[test]
fn a_generic_aggregate_capture_copies_a_data_instantiation() {
    // The other half of the same gate: `Wrap<List<i32>>` is no resource, so
    // the same capture in the same function still copies. The carve-out is for
    // resources only — it is not a licence to alias.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Wrap<T> {
            value: T,
        }
        fun first_of<T>(pair: (Wrap<T>, i32)): Wrap<T> {
            let (a, b) = pair;
            a
        }
        fun main() {
            let pair = (Wrap { value = [1, 2] }, 5);
            mut w = first_of(pair);
            w.value.push(9);
            print(w.value.len());
            print(pair.0.value.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_mut_array_binder_in_a_match_stamps_its_elements() {
    // B53 finding 5: `mut` at a binder applies to every binding under it, and
    // the match/`is` grammar recursed tuples but not arrays — so `mut [a, b]`
    // in a match bound `a`/`b` IMMUTABLE ("cannot mutate immutable 'a'") while
    // the identical `mut [a, b] = arr` bound them mutable. One keyword, two
    // meanings.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let arr: [List<i32>; 2] = [[1, 2], [3]];
            match arr {
                mut [a, b] => {
                    a.push(9);
                    print(a.len());
                    print(arr[0].len());
                }
                _ => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_mut_array_binder_in_an_is_test_stamps_its_elements() {
    // The `is` half of the same grammar arm.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let arr: [List<i32>; 2] = [[1, 2], [3]];
            if arr is mut [a, b] {
                a.push(9);
                print(a.len());
                print(arr[0].len());
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_guard_that_needs_a_temporary_emits_it() {
    // B59: a guard whose expression needs hoisted statements (an `is` test, a
    // `?` lift, a nested `match`) used to drop them — an else-if chain has no
    // statement slot before a leg's condition — and the emitted condition
    // referenced a temporary that was never declared. Such a leg is now emitted
    // with its own slot, and the copies its captures owe are declared ahead of
    // the guard, so the guard's `pop` takes from the copy, not the subject.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut pair = ([1, 2], 3);
            match pair {
                (mut xs, let n) if xs.pop() is Some(_) => {
                    print(xs.len());
                    print(pair.0.len());
                }
                _ => print(0),
            }
        }
        "#,
        "1\n2\n",
    );
}

// ---------------------------------------------------------------------------
// B81 (rule 1 through a VIEWED subject). B53 made the alias path COPY what it
// captures; it left the alias path READING late. Each capture stays an
// accessor into the subject temp, re-read at every reference, which is a
// faithful snapshot only while the subject can change by REBINDING — through a
// `&mut` view it changes IN PLACE (that is how the write reaches the caller),
// so every deferred read in the leg saw post-write state. Captures of a
// writable-view subject are now read once, at the match. See
// proposal/capture-clones.md §6.
// ---------------------------------------------------------------------------

#[test]
fn an_is_capture_from_a_mut_self_subject_reads_the_prematch_value() {
    // B81's filed repro. `at` is an `i32`, so it owes no copy and kept its
    // accessor `$a[2]`; `self = Feed::Ready(..)` lowers to a write in place
    // (`__replace(self, ..)`), mutating the very array `$a` aliases, so
    // `items[at]` indexed with the INCREMENTED `at`. Printed "b\nc" for two
    // steps over ["a","b","c"].
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun step(&mut self): Option<str> {
                if self is Feed::Ready(let items, let at) {
                    self = Feed::Ready(items, at + 1);
                    Some(items[at])
                } else {
                    None
                }
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            print(feed.step().unwrap());
            print(feed.step().unwrap());
        }
        "#,
        "a\nb\n",
    );
}

#[test]
fn an_is_capture_from_a_mut_parameter_subject_is_unchanged() {
    // The twin that was always right, pinned so the fix cannot move it: a
    // by-value `mut` parameter IS the callee's own copy (H9), so the subject
    // rebinds and each call re-reads the caller's untouched value. Not a view,
    // so no capture materializes and the emitted shape is byte-for-byte what
    // B53 shipped.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        fun step(mut feed: Feed): Option<str> {
            if feed is Feed::Ready(let items, let at) {
                feed = Feed::Ready(items, at + 1);
                Some(items[at])
            } else {
                None
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            print(step(feed).unwrap());
            print(step(feed).unwrap());
        }
        "#,
        "a\na\n",
    );
}

#[test]
fn an_is_capture_from_a_mut_view_parameter_reads_the_prematch_value() {
    // The same hole reached through an ordinary `&mut` parameter rather than
    // `&mut self` — the predicate is the parameter's CONVENTION, not the
    // receiver position. Printed "b\nc".
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        fun step(feed: &mut Feed): str {
            if feed is Feed::Ready(let items, let at) {
                feed = Feed::Ready(items, at + 1);
                items[at]
            } else {
                "-"
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            print(step(&mut feed));
            print(step(&mut feed));
        }
        "#,
        "a\nb\n",
    );
}

#[test]
fn an_is_capture_from_a_dereferenced_view_local_copies_and_reads_early() {
    // The second seam, and the worse one: `is_place_expr` excludes
    // `Expr::Dereference`, so a `*view` subject collected NO capture
    // candidates at all — B53's copy rule was missing wholesale for that
    // spelling, and even the AGGREGATE capture aliased (`__at($a[1], $a[2])`,
    // no `__clone` anywhere). Both halves are pinned here: `items` must be a
    // copy and `at` must be the pre-match index. Printed "a" only after both
    // fixes; before, "b".
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            let view = &mut feed;
            if *view is Feed::Ready(let items, let at) {
                view = Feed::Ready(items, at + 1);
                print(items[at]);
            }
        }
        "#,
        "a\n",
    );
}

#[test]
fn a_destructure_of_a_dereferenced_view_copies_its_captures() {
    // The deref seam is not confined to the alias path — the capture pass
    // gates `Expr::Destructure` on the same predicate, so `let (xs, n) =
    // *view` collected no candidates either and B53's copy never fired. This
    // one has nothing to do with reading late: `xs` simply aliased the
    // subject's element, and growing it through the view grew the capture.
    // Printed 3.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = ([1, 2], 3);
            let view = &mut pair;
            let (xs, n) = *view;
            view.0.push(9);
            print(xs.len());
            print(n);
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_guarded_leg_capture_from_a_viewed_subject_reads_the_prematch_value() {
    // A guard puts the leg on the alias path too, so it carries the same hole
    // — and it is the ordering-sensitive one: `materialize_captures` runs
    // BEFORE the guard is walked and re-points the alias table, so a guard
    // that reads a materialized capture forces B59's prelude shape or the
    // emitted guard names a binding that has not been declared yet. Printed
    // "b\nc".
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun step(&mut self): str {
                match self {
                    Feed::Ready(let items, let at) if at >= 0 => {
                        self = Feed::Ready(items, at + 1);
                        items[at]
                    }
                    _ => "-",
                }
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            print(feed.step());
            print(feed.step());
        }
        "#,
        "a\nb\n",
    );
}

#[test]
fn an_unguarded_match_leg_on_a_viewed_subject_was_already_right() {
    // The negative half of the diagnosis, pinned: an UNGUARDED leg compiles
    // through `compile_pattern`, which declares every capture as a real
    // `const` at leg entry — it never reads late, so it never had the bug.
    // That asymmetry is what identified the alias path as the seam rather
    // than the view.
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun step(&mut self): str {
                match self {
                    Feed::Ready(let items, let at) => {
                        self = Feed::Ready(items, at + 1);
                        items[at]
                    }
                    Feed::Done => "-",
                }
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a", "b", "c"], 0);
            print(feed.step());
            print(feed.step());
        }
        "#,
        "a\nb\n",
    );
}

#[test]
fn both_capture_shapes_survive_an_in_place_write_through_the_view() {
    // The two payload shapes in one leg, and the sharper form of the write:
    // not a whole-subject reassignment but COMPONENT writes through the view
    // (`pair.0.push`, `pair.1 = 9`), which mutate the subject's storage
    // without going near the subject binding.
    //
    // `items` is B53's business — an aggregate capture COPIES, so growing the
    // source to 4 leaves it at 3. `at` is B81's — a scalar owes no copy, so it
    // kept an accessor and read the 9. One pin, red either way: 12 without the
    // materialization, 4 without the copy.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun grow(pair: &mut (List<str>, i32)): i32 {
            if pair is (let items, let at) {
                pair.0.push("d");
                pair.1 = 9;
                items.len() + at
            } else {
                -1
            }
        }
        fun main() {
            mut pair = (["a", "b", "c"], 0);
            print(grow(&mut pair));
            print(pair.0.len());
        }
        "#,
        "3\n4\n",
    );
}

#[test]
fn a_nested_capture_from_a_viewed_subject_reads_the_prematch_value() {
    // Every capture in the tree, not just the top level: the inner tuple's
    // `xs`/`k` and the outer `at` all read through the same subject temp.
    // 2 + 3 + 4; post-write it was 4 + 7 + 5.
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Pair {
            Two((List<i32>, i32), i32),
            Neither,
        }
        impl Pair {
            fun step(&mut self): i32 {
                if self is Pair::Two((let xs, let k), let at) {
                    self = Pair::Two(([9, 9, 9, 9], 7), 5);
                    xs.len() + k + at
                } else {
                    -1
                }
            }
        }
        fun main() {
            mut pair = Pair::Two(([1, 2], 3), 4);
            print(pair.step());
        }
        "#,
        "9\n",
    );
}

#[test]
fn a_viewed_capture_read_before_and_after_the_write_agrees() {
    // Both orders in one leg. A read BEFORE the write was always right (the
    // accessor had nothing to observe yet); the bug was only visible AFTER,
    // which is exactly what makes the two disagree. The binding is one value,
    // so 3 + 3 — not 3 + 13.
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun step(&mut self): i32 {
                if self is Feed::Ready(let items, let at) {
                    let before = at;
                    self = Feed::Ready(items, at + 10);
                    before + at
                } else {
                    -1
                }
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a"], 3);
            print(feed.step());
        }
        "#,
        "6\n",
    );
}

#[test]
fn a_resource_capture_from_a_viewed_subject_loans_the_prematch_payload() {
    // R1/R11 and B65's doctrine, at the viewed subject. A resource payload has
    // no copy to make — "there is no user-facing copy spelling in vilan to
    // name" (affine-moves.md §9.1), and `x is Some(let r)` is always a LOAN
    // whatever the subject's form — so the capture is materialized WITHOUT
    // `__clone`: `const c = $a[1]`, which fixes WHICH value is loaned without
    // minting a second owner. That is what the place-subject twin below
    // already does, and matching it is the whole rule. 1 + 0, not 9 + 5.
    assert_compiles_and_runs(
        r#"
        import std::print;
        resource struct Conn {
            id: i32,
        }
        enum Slot {
            Full(Conn, i32),
            Empty,
        }
        impl Slot {
            fun peek(&mut self): i32 {
                if self is Slot::Full(let c, let at) {
                    self = Slot::Full(Conn { id = 9 }, 5);
                    c.id + at
                } else {
                    -1
                }
            }
        }
        fun main() {
            mut slot = Slot::Full(Conn { id = 1 }, 0);
            print(slot.peek());
        }
        "#,
        "1\n",
    );
}

#[test]
fn a_resource_capture_from_a_place_subject_loans_the_prematch_payload() {
    // The place twin the rule above is calibrated against: the same program
    // with an owned `mut` local reads the pre-assignment payload because the
    // assignment REBINDS and the subject temp keeps the old aggregate. It was
    // already right, and pinning it is what makes "indistinguishable from the
    // place path" a checked claim rather than a stated one.
    assert_compiles_and_runs(
        r#"
        import std::print;
        resource struct Conn {
            id: i32,
        }
        enum Slot {
            Full(Conn, i32),
            Empty,
        }
        fun main() {
            mut slot = Slot::Full(Conn { id = 1 }, 0);
            if slot is Slot::Full(let c, let at) {
                slot = Slot::Full(Conn { id = 9 }, 5);
                print(c.id + at);
            }
        }
        "#,
        "1\n",
    );
}

#[test]
fn a_readonly_view_subject_keeps_its_shared_accessors() {
    // The scope line, and the reason the predicate asks about WRITABILITY
    // rather than view-ness. Nothing can be written through a `&` view, so its
    // subject temp is a snapshot again and its captures keep the accessor —
    // and with it B53's SHARE elision, which exists to stop read-only walkers
    // deep-copying at every level. Widening the rule to every view would have
    // taken that back for `&self` methods.
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun peek(&self): i32 {
                if self is Feed::Ready(let items, let at) {
                    items.len() + at
                } else {
                    -1
                }
            }
        }
        fun main() {
            let feed = Feed::Ready(["a", "b"], 5);
            print(feed.peek());
        }
        "#,
        "7\n",
    );
}

// ---------------------------------------------------------------------------
// B89 (the view write is a REPLACE, not a merge). Writing a whole aggregate
// through a view has to keep the pointee's identity — that is how the write
// reaches the caller — so it copies the value's slots into the pointee rather
// than rebinding. `Object.assign` did the copying, and `Object.assign` is a
// MERGE: a slot the value does not reach is left standing. Every aggregate
// whose width can shrink was wrong under it.
// ---------------------------------------------------------------------------

#[test]
fn a_shortening_write_through_a_list_view_truncates() {
    // The directly observable half, and the reason this is not merely an enum
    // bug: `Object.assign(v, [ 1 ])` over a three-element list overwrote slot 0
    // and left slots 1 and 2 alone, so the caller's list still had `len() == 3`
    // and still held `2` and `3`. Nothing in the source says "merge".
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun replace(v: &mut List<i32>) {
            v = [9];
        }
        fun main() {
            mut xs = [1, 2, 3];
            replace(&mut xs);
            print(xs.len());
            print(xs[0]);
        }
        "#,
        "1\n9\n",
    );
}

#[test]
fn a_shortening_reassign_of_a_viewed_enum_leaves_no_stale_payload() {
    // B89's filed repro. `self = Feed::Done` lowers to a write of `[ 1 ]` over
    // `[ 0, [ "a" ], 1 ]`; under the merge the payload survived in the trailing
    // slots — unreachable through the enum's own API (the tag gates every
    // read), but present, and for a RESOURCE payload it is a live object no
    // owner can reach. The emitted shape is the pin: the truncating write, and
    // the helper that truncates.
    let source = r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun finish(&mut self) {
                self = Feed::Done;
            }
        }
        fun main() {
            mut feed = Feed::Ready(["a"], 1);
            feed.finish();
            if feed is Feed::Done {
                print("done");
            }
        }
    "#;
    assert_emits_containing(source, "__replace(self, [ 1 ]);");
    assert_emits_containing(
        source,
        "if (Array.isArray(target) && Array.isArray(value)) target.length = value.length;",
    );
    assert_compiles_and_runs(source, "done\n");
}

#[test]
fn a_widening_reassign_of_a_viewed_enum_fills_every_slot() {
    // The other direction, which the fix must not break: the pointee GROWS, so
    // setting the length first opens holes that the copy then fills. A payload
    // read back after the widening write proves no slot was left a hole.
    assert_compiles_and_runs(
        r#"
        import std::print;
        enum Feed {
            Ready(List<str>, i32),
            Done,
        }
        impl Feed {
            fun start(&mut self) {
                self = Feed::Ready(["a", "b"], 7);
            }
        }
        fun main() {
            mut feed = Feed::Done;
            feed.start();
            if feed is Feed::Ready(let items, let at) {
                print(items.len());
                print(at);
            }
        }
        "#,
        "2\n7\n",
    );
}

#[test]
fn an_equal_width_write_through_a_struct_view_is_unchanged() {
    // The width-fixed case, pinned so the general form stays a superset of the
    // merge it replaced: a struct's slots are the same on both sides, so the
    // merge happened to be right there and the replace must agree with it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Point { x: i32, y: i32 }
        fun move_to(p: &mut Point) {
            p = Point { x = 7, y = 8 };
        }
        fun main() {
            mut point = Point { x = 1, y = 2 };
            move_to(&mut point);
            print(point.x);
            print(point.y);
        }
        "#,
        "7\n8\n",
    );
}

#[test]
fn a_shortening_write_through_a_view_truncates_under_const_eval() {
    // The const-eval interpreter runs the SAME emitted nodes, so it needs the
    // replace natively — a merge there would fold a stale slot into a literal.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun replace(v: &mut List<i32>): i32 {
            v = [9];
            v.len()
        }
        fun main() {
            print(const {
                mut xs = [1, 2, 3];
                replace(&mut xs)
            });
        }
        "#,
        "1\n",
    );
}

#[test]
fn a_view_write_drops_the_overwritten_variants_resource() {
    // B94, and the half B89's truncation did NOT fix. R2 (destruction.md §5)
    // says assigning onto a place that still holds a resource drops the old
    // value first, and the OWNED-place twin always implemented it:
    // `holder = Holder::Empty` on a local emits the tag-dispatching drop glue
    // before the write. Through a `&mut` view it did not — the scan that plans
    // overwrite drops tracks BINDINGS the scanned body owns, and a loan owns
    // nothing, so nothing was planned and the scope-end glue then read the NEW
    // tag and found nothing to drop. The guard was silently leaked (this
    // program printed "before\nafter"). RULED 2026-08-07: the loan drops what
    // it overwrites, twinning the owned path — the same indistinguishability
    // doctrine B81/B88 applied to captures.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop {
            fun drop(&mut self) {
                print(i"dropped {self.label}");
            }
        }
        enum Holder {
            Full(Guard),
            Empty,
        }
        impl Holder {
            fun clear(&mut self) {
                self = Holder::Empty;
            }
        }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            print("before");
            holder.clear();
            print("after");
        }
        "#,
        "before\ndropped held\nafter\n",
    );
}

// ---------------------------------------------------------------------------
// B94 (R2 through a LOAN). The rule: a write through a writable view drops the
// pointee's outgoing value, exactly as the owned-place twin drops the
// binding's. Every pin below has its owned twin's answer as the expectation,
// because "indistinguishable from the owned path" IS the rule — the two write
// the same storage under different names. See proposal/destruction.md §5 (R2)
// and proposal/capture-clones.md §8.
// ---------------------------------------------------------------------------

#[test]
fn a_view_write_of_the_same_variant_width_drops_the_old_payload() {
    // Width was never the mechanism — B89's truncation only made the shrinking
    // shape LOOK like a width bug. `Full(g1)` -> `Full(g2)` overwrites the same
    // two slots and leaked just as hard.
    let program = |write: &str| {
        format!(
            r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard {{ label: str }}
        impl Guard with Drop {{ fun drop(&mut self) {{ print(i"dropped {{self.label}}"); }} }}
        enum Holder {{ Full(Guard), Empty }}
        impl Holder {{ fun swap(&mut self) {{ self = Holder::Full(Guard {{ label = "second" }}); }} }}
        fun main() {{
            mut holder = Holder::Full(Guard {{ label = "first" }});
            print("before");
            {write}
            print("after");
        }}
        "#
        )
    };
    // The owned twin first, so the expectation below is its answer verbatim.
    assert_compiles_and_runs(
        &program(r#"holder = Holder::Full(Guard { label = "second" });"#),
        "before\ndropped first\nafter\ndropped second\n",
    );
    assert_compiles_and_runs(
        &program("holder.swap();"),
        "before\ndropped first\nafter\ndropped second\n",
    );
}

#[test]
fn a_view_write_that_grows_the_variant_drops_the_old_payload() {
    // The other width direction: a one-slot payload replaced by a three-slot
    // one. `__replace` GROWS the array here, so nothing is truncated and the
    // old payload would survive in a reachable slot — the drop is owed for the
    // ownership reason, not the layout one.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Small(Guard), Big(Guard, i32, i32), Empty }
        impl Holder {
            fun grow(&mut self) { self = Holder::Big(Guard { label = "big" }, 1, 2); }
        }
        fun main() {
            mut holder = Holder::Small(Guard { label = "small" });
            print("before");
            holder.grow();
            print("after");
        }
        "#,
        "before\ndropped small\nafter\ndropped big\n",
    );
}

#[test]
fn a_view_write_to_a_struct_pointee_drops_the_old_value() {
    // No enum tag anywhere: the pointee is the resource itself, so the glue is
    // an unconditional call rather than a tag test. Same answer as
    // `overwrite_drops_the_old_value_then_the_new_at_scope_end`, one loan over.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        fun reset(g: &mut Guard) { g = Guard { label = "new" }; }
        fun main() {
            mut guard = Guard { label = "old" };
            print("before");
            reset(&mut guard);
            print("after");
        }
        "#,
        "before\ndropped old\nafter\ndropped new\n",
    );
}

#[test]
fn a_view_write_drops_before_the_truncating_replace_clobbers_the_payload() {
    // The B89 interaction, pinned in BYTES because the runtime answer alone
    // cannot see the order. `__replace` sets `target.length = value.length`
    // before merging, so a shrinking write deletes the payload slots outright —
    // a drop emitted after it would destroy nothing. The resource here sits in
    // slot 2, BEHIND a `List` payload, so the truncation to one slot takes both.
    let source = r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(List<i32>, Guard), Empty }
        impl Holder { fun clear(&mut self) { self = Holder::Empty; } }
        fun main() {
            mut holder = Holder::Full([1, 2, 3], Guard { label = "held" });
            print("before");
            holder.clear();
            print("after");
        }
        "#;
    match compile(source) {
        Ok(js) => {
            let drop_at = js.find("$a(self);").expect("the overwrite drop is emitted");
            let write_at = js
                .find("__replace(self,")
                .expect("the truncating write is emitted");
            assert!(
                drop_at < write_at,
                "the overwrite drop must precede the truncating write:\n{js}"
            );
        }
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "before\ndropped held\nafter\n");
}

#[test]
fn a_view_write_drops_the_payload_in_the_owned_paths_order() {
    // Order is part of the doctrine, not an accident of it: a variant with two
    // resource slots destroys them in reverse declaration order
    // (destruction.md §5), and the loan path must print the same sequence as
    // the owned one because it runs the same per-type glue.
    let program = |write: &str| {
        format!(
            r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard {{ label: str }}
        impl Guard with Drop {{ fun drop(&mut self) {{ print(i"dropped {{self.label}}"); }} }}
        enum Holder {{ Pair(Guard, Guard), Empty }}
        impl Holder {{ fun clear(&mut self) {{ self = Holder::Empty; }} }}
        fun main() {{
            mut holder = Holder::Pair(Guard {{ label = "a" }}, Guard {{ label = "b" }});
            print("before");
            {write}
            print("after");
        }}
        "#
        )
    };
    assert_compiles_and_runs(
        &program("holder = Holder::Empty;"),
        "before\ndropped b\ndropped a\nafter\n",
    );
    assert_compiles_and_runs(
        &program("holder.clear();"),
        "before\ndropped b\ndropped a\nafter\n",
    );
}

#[test]
fn a_view_write_through_a_mut_parameter_drops_the_old_value() {
    // The `&mut x` parameter spelling of the same write — `&mut self` is not a
    // special case, it is one of three names for a writable view.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        fun clear(v: &mut Holder) { v = Holder::Empty; }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            print("before");
            clear(&mut holder);
            print("after");
        }
        "#,
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_view_write_through_a_mut_local_drops_the_old_value() {
    // The third spelling: a LOCAL bound to a `&mut`. `*v = ..` is not the
    // vilan surface ("a view is written through directly"), so the write is
    // spelled `v = ..` and `view_binding_mutability` is what recognizes it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            let v = &mut holder;
            print("before");
            v = Holder::Empty;
            print("after");
        }
        "#,
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_view_write_through_a_nested_reborrow_drops_the_old_value() {
    // Two loans deep: `outer` re-borrows its own `&mut` into `inner`, which
    // does the write. The question is asked where the write is, so depth costs
    // nothing — but a rule keyed on "the receiver is `self`" would miss this.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        fun inner(v: &mut Holder) { v = Holder::Empty; }
        fun outer(v: &mut Holder) { inner(&mut v); }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            print("before");
            outer(&mut holder);
            print("after");
        }
        "#,
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn repeated_view_writes_drop_each_outgoing_value_exactly_once() {
    // The double-drop question asked where it CAN be reached: two writes
    // through one loan. Each drops what it finds, and what the second finds is
    // what the first installed — the glue reads the pointee's CURRENT contents,
    // never a remembered value. "first" and "second" appear once each.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        impl Holder {
            fun churn(&mut self) {
                self = Holder::Full(Guard { label = "second" });
                self = Holder::Empty;
            }
        }
        fun main() {
            mut holder = Holder::Full(Guard { label = "first" });
            print("before");
            holder.churn();
            print("after");
        }
        "#,
        "before\ndropped first\ndropped second\nafter\n",
    );
}

#[test]
fn a_view_write_after_the_owner_moved_out_is_rejected() {
    // Why the loan arm asks no liveness question, pinned rather than argued.
    // The owned arm needs one because a body can move its own binding out and
    // must not then drop it twice; the loan arm cannot reach that state,
    // because minting the loan of a moved-out binding is itself a use-after-move
    // R1 already rejects. The owned twin of this program compiles and prints no
    // second drop (`a_moved_out_binding_is_not_overwrite_dropped`).
    assert_fails_with(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        impl Holder { fun clear(&mut self) { self = Holder::Empty; } }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            match holder {
                Holder::Full(let g) => { print("took"); }
                Holder::Empty => {}
            }
            holder.clear();
        }
        "#,
        "after it was moved",
    );
}

#[test]
fn a_moved_out_binding_is_not_overwrite_dropped() {
    // The owned twin of the pin above, and the reason the owned arm keeps its
    // flow-sensitive `owned` set: the match consumed the payload (B62 destroys
    // it at the leg's end), so the assignment that follows overwrites a binding
    // that owns nothing and must NOT drop. "dropped held" appears once.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard { label: str }
        impl Guard with Drop { fun drop(&mut self) { print(i"dropped {self.label}"); } }
        enum Holder { Full(Guard), Empty }
        fun main() {
            mut holder = Holder::Full(Guard { label = "held" });
            match holder {
                Holder::Full(let g) => { print("took"); }
                Holder::Empty => {}
            }
            print("before");
            holder = Holder::Empty;
            print("after");
        }
        "#,
        "took\ndropped held\nbefore\nafter\n",
    );
}

#[test]
fn a_mut_view_binding_of_a_resource_does_not_drop_it_at_scope_end() {
    // The same confusion in the other direction, found while proving B94 and
    // fixed by the same sentence: a loan owns nothing, so it destroys nothing
    // at its scope end either. References are TRANSPARENT — `&mut Holder` has
    // type `Holder` — so `let v = &mut holder` minted a resource-TYPED local
    // that the drop planner enrolled as an owner, and the emitted program
    // destroyed the borrowed value twice ("dropped held" printed twice, on the
    // struct pointee as well as the enum one).
    let program = |declaration: &str, borrow: &str| {
        format!(
            r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard {{ label: str }}
        impl Guard with Drop {{ fun drop(&mut self) {{ print(i"dropped {{self.label}}"); }} }}
        enum Holder {{ Full(Guard), Empty }}
        fun main() {{
            {declaration}
            let v = {borrow};
            print("hi");
        }}
        "#
        )
    };
    assert_compiles_and_runs(
        &program(
            r#"mut holder = Holder::Full(Guard { label = "held" });"#,
            "&mut holder",
        ),
        "hi\ndropped held\n",
    );
    assert_compiles_and_runs(
        &program(r#"mut guard = Guard { label = "held" };"#, "&mut guard"),
        "hi\ndropped held\n",
    );
    // The read-only loan too — `&` was never writable, but it was just as
    // wrongly enrolled as an owner.
    assert_compiles_and_runs(
        &program(r#"mut guard = Guard { label = "held" };"#, "&guard"),
        "hi\ndropped held\n",
    );
}

#[test]
fn a_view_write_to_a_data_pointee_emits_no_drop() {
    // The negative half, in bytes: the rule fires on the pointee's RESOURCE-ness,
    // not on the fact that a write goes through a view. A data pointee's write
    // is the bare `__replace` it always was, which is what keeps every
    // resource-free corpus program byte-identical.
    assert_emits_containing(
        r#"
        import std::print;
        struct Holder { n: i32 }
        impl Holder { fun clear(&mut self) { self = Holder { n = 0 }; } }
        fun main() {
            mut holder = Holder { n = 7 };
            holder.clear();
            print(holder.n);
        }
        "#,
        "function clear(self) {\n\t__replace(self, [ 0 ]);\n}",
    );
}

// ---------------------------------------------------------------------------
// B99 (R2's COMPONENT half). B94 closed the loan half and filed this one: R2 is
// spelled over a BINDING and R5 over reading and moving a field, so writing
// over one fell between them and the outgoing value was leaked outright. The
// rule now reads over the PLACE all the way down — a write over a component
// whose type is a resource drops what it replaces, owned place and view alike,
// with no liveness question (R5 makes a resource field loan-only, so a
// component place always holds a live value). See proposal/destruction.md R2
// and capture-clones.md §10.
// ---------------------------------------------------------------------------

/// The B99 pin family's shared preamble: a `Drop`-printing resource, an enum
/// that holds one, and a struct that holds the enum.
fn b99_program(body: &str) -> String {
    format!(
        r#"
        import std::print;
        import std::drop::Drop;
        resource struct Guard {{ label: str }}
        impl Guard with Drop {{ fun drop(&mut self) {{ print(i"dropped {{self.label}}"); }} }}
        enum Holder {{ Full(Guard), Empty }}
        struct Slot {{ held: Holder }}
        {body}
        "#
    )
}

/// [`b99_program`] compiled, for the pins whose claim is about emitted BYTES.
fn b99_js(body: &str) -> String {
    match compile(&b99_program(body)) {
        Ok(js) => js,
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
}

#[test]
fn a_component_write_to_a_resource_field_drops_the_old_value() {
    // The filed repro (B94's bycatch), now closed. R2 was implemented over the
    // BINDING — only a whole-binding target enrolled — so `slot.held = ..`
    // overwrote a live resource that no rule covered and printed
    // "before\nafter", leaking the guard. Whether the write is legal at all is
    // R5's question and R5 permits it (it makes a field loan-only and rejects
    // moving one OUT; it says nothing about writing over one), which is exactly
    // why R2 owes the drop.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "held" }) };
            print("before");
            slot.held = Holder::Empty;
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_nested_component_write_drops_the_old_value() {
    // The projection is asked of the PLACE, not of its depth: `o.inner.held`
    // names the storage the write clobbers exactly as `slot.held` does.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        struct Outer { inner: Slot }
        fun main() {
            mut o = Outer { inner = Slot { held = Holder::Full(Guard { label = "held" }) } };
            print("before");
            o.inner.held = Holder::Empty;
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_component_write_through_a_view_drops_the_old_value() {
    // B94's arm composes, and this is the doctrine's own test: the two
    // spellings are the same expression shape and differ only in what the root
    // binding is, so the answer must not depend on the root. The predicate is
    // the component's type, and it never asks.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun clear(s: &mut Slot) { s.held = Holder::Empty; }
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "held" }) };
            print("before");
            clear(&mut slot);
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_tuple_component_write_drops_the_old_value() {
    // The same rule at the other positional spelling.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun main() {
            mut pair = (1, Holder::Full(Guard { label = "held" }));
            print("before");
            pair.1 = Holder::Empty;
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn an_element_write_drops_the_old_value() {
    // The `Index` spelling — a fixed array of resources, which is the only
    // indexable resource aggregate (R10 rejects the native containers). The
    // trailing "dropped two"/"dropped three" are the scope-end teardown, in
    // reverse element order.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun main() {
            mut arr: [Guard; 2] = [Guard { label = "one" }, Guard { label = "two" }];
            print("before");
            arr[0] = Guard { label = "three" };
            print("after");
        }
        "#,
        ),
        "before\ndropped one\nafter\ndropped two\ndropped three\n",
    );
}

#[test]
fn a_component_write_inside_a_match_arm_drops_the_old_value() {
    // The write is planned by `plan_expr`, which descends every arm, so a
    // conditional write is covered without a liveness question — the component
    // place is live on every path that reaches it.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "held" }) };
            let n = 1;
            print("before");
            match n { 1 => { slot.held = Holder::Empty; } _ => {} }
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_component_write_to_a_data_field_emits_no_drop() {
    // The negative half, in bytes: the rule fires on the COMPONENT's
    // resource-ness, not on the fact that its aggregate holds a resource
    // somewhere. `count` is an `i32` in a struct that also holds a `Holder`, and
    // its write is the bare slot assignment it always was — which is what keeps
    // every resource-free corpus program byte-identical.
    assert_emits_containing(
        &b99_program(
            r#"
        struct Pair { held: Holder, count: i32 }
        fun main() {
            mut pair = Pair { held = Holder::Full(Guard { label = "held" }), count = 1 };
            pair.count = 5;
            print(pair.count);
        }
        "#,
        ),
        "pair[1] = 5;",
    );
}

#[test]
fn a_component_write_drops_before_the_write_clobbers_the_slot() {
    // The ordering is load-bearing rather than cosmetic, for the same reason
    // B94 pinned it on the view path: the drop's operand IS the slot the write
    // replaces, so a drop emitted afterwards would destroy the NEW value.
    // Pinned in bytes, since a runtime pin cannot tell "dropped the old one"
    // from "dropped a same-shaped new one".
    let js = b99_js(
        r#"
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "one" }) };
            slot.held = Holder::Full(Guard { label = "two" });
        }
        "#,
    );
    let drop_index = js.find("(slot[0]);").expect("the overwrite drop");
    let write_index = js.find("slot[0] = [ 0,").expect("the component write");
    assert!(
        drop_index < write_index,
        "the drop must precede the write that clobbers the slot it reads:\n{js}"
    );
}

#[test]
fn a_component_write_drops_in_the_owned_twins_order() {
    // The whole-binding twin of the same program, so the two spellings can be
    // compared: both destroy the outgoing value BEFORE the incoming one is
    // installed, and neither destroys the incoming one until its scope ends.
    let component = &b99_program(
        r#"
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "one" }) };
            print("before");
            slot.held = Holder::Full(Guard { label = "two" });
            print("after");
        }
        "#,
    );
    let binding = &b99_program(
        r#"
        fun main() {
            mut held = Holder::Full(Guard { label = "one" });
            print("before");
            held = Holder::Full(Guard { label = "two" });
            print("after");
        }
        "#,
    );
    assert_compiles_and_runs(component, "before\ndropped one\nafter\ndropped two\n");
    assert_compiles_and_runs(binding, "before\ndropped one\nafter\ndropped two\n");
}

#[test]
fn a_write_through_a_view_of_a_component_still_drops() {
    // The neighbour that was ALREADY right, pinned so the new arm cannot move
    // it: `&mut slot.held` mints a view whose own write is B94's loan arm, and
    // it takes the `__replace` path (a whole-value write through a view) rather
    // than this one. The two spellings agree, which is the point.
    assert_compiles_and_runs(
        &b99_program(
            r#"
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "held" }) };
            print("before");
            let v = &mut slot.held;
            v = Holder::Empty;
            print("after");
        }
        "#,
        ),
        "before\ndropped held\nafter\n",
    );
}

#[test]
fn a_component_write_drops_before_the_truncating_replace_on_the_view_path() {
    // B89's interaction, unchanged by B99 and pinned here because the component
    // arm shares the emission site: a write THROUGH a view still lowers to
    // `__replace`, which sets `target.length = value.length` before merging, so
    // a drop emitted after it would destroy slots that no longer exist. A
    // component write is a plain slot assignment and never truncates — the
    // ordering is owed for the simpler reason above — so both orders are pinned
    // from the one emission.
    let js = b99_js(
        r#"
        fun refill(held: &mut Holder) { held = Holder::Empty; }
        fun main() {
            mut slot = Slot { held = Holder::Full(Guard { label = "held" }) };
            refill(&mut slot.held);
        }
        "#,
    );
    let drop_index = js.find("(held);").expect("the overwrite drop");
    let replace_index = js.find("__replace(held,").expect("the truncating write");
    assert!(
        drop_index < replace_index,
        "the drop must precede `__replace`'s truncation (B89):\n{js}"
    );
}

#[test]
fn a_resource_free_component_write_plans_no_drop_pass_at_all() {
    // The early return that keeps resource-free programs byte-identical: a
    // program with no declared resource has no resource type, so the component
    // arm collects nothing and no `try`/`finally` appears.
    let js = match compile(
        r#"
        import std::print;
        struct Slot { held: i32 }
        fun main() {
            mut slot = Slot { held = 1 };
            slot.held = 2;
            print(slot.held);
        }
        "#,
    ) {
        Ok(js) => js,
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    };
    assert!(
        !js.contains("finally"),
        "a resource-free program takes no teardown:\n{js}"
    );
}

// ---------------------------------------------------------------------------
// B88 (the same seam through an OWNED place). B81 closed the alias path's late
// read for a writable-view subject and stopped there, because an owned place
// looked safe: assigning it REBINDS it, installing a fresh value and leaving
// the subject temp holding the old one. That is true of exactly one write
// form. A COMPONENT write — `t.1 = 9`, `h.pair.1 = 9`, `xs[0] = 9` — mutates
// the very object the temp aliases, and so does a `&mut` taken of the place
// and a `&mut self` method called on it. Captures of a subject some in-place
// write can reach are now read once, at the match, exactly as a viewed
// subject's are. See proposal/capture-clones.md §7.
// ---------------------------------------------------------------------------

#[test]
fn an_is_capture_from_a_component_written_place_reads_the_prematch_value() {
    // B88's filed repro. `b` is an `i32`, so it owes no copy and kept its
    // accessor `$a[1]`; `t.1 = 99` lowers to `t[1] = 99`, and `$a` IS `t`'s
    // array, so the deferred read returned the write. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut t = (7, 3);
            if t is (let a, let b) {
                t.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_place_capture_read_before_and_after_a_component_write_agrees() {
    // Both orders in one leg, the shape that makes the bug undeniable: a read
    // BEFORE the write was always right (the accessor had nothing to observe
    // yet), so the two reads of one binding DISAGREED — 3 then 99. The
    // binding is one value, so 6, not 102.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut t = (7, 3);
            if t is (let a, let b) {
                let before = b;
                t.1 = 99;
                print(before + b);
            }
        }
        "#,
        "6\n",
    );
}

#[test]
fn a_component_write_through_a_field_path_does_not_reach_a_capture() {
    // The field arm. A struct field is not patternable, so a field write
    // reaches this seam through the subject's PATH rather than the capture's:
    // the subject is `h.pair`, a `Field` place, and `h.pair.1 = 99` writes
    // into the very array that place names. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32), tag: i32 }
        fun main() {
            mut h = Holder { pair = (7, 3), tag = 0 };
            if h.pair is (let a, let b) {
                h.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_disjoint_field_write_leaves_a_sibling_subject_correct() {
    // The other side of the field arm, and the honest record of how coarse
    // the predicate is: the write lands in a DIFFERENT field of the same root,
    // so it could never have reached this subject and the program was already
    // right. Root granularity materializes it anyway — a write that reaches
    // the storage under a second name got that name from a `&mut` of the
    // ROOT, so the root is the granularity the question can be asked at
    // soundly. Pinned because the answer must not change either way.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32), tag: i32 }
        fun main() {
            mut h = Holder { pair = (7, 3), tag = 5 };
            if h.pair is (let a, let b) {
                h.tag = 1;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn an_index_write_does_not_reach_a_fixed_array_capture() {
    // The index arm, at the fixed-array binder — `marr[1] = 99` lowers to
    // `__at_put(marr, 1, 99)`, an in-place element store into the array the
    // subject temp aliases. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut marr: [i32; 2] = [7, 3];
            if marr is let [g, k] {
                marr[1] = 99;
                print(k);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn an_index_write_does_not_reach_a_capture_of_an_indexed_subject() {
    // The index arm at the SUBJECT instead: `rows[0]` is an `Index` place, and
    // `rows[0].1 = 99` writes the element it names. `place_root` walks the
    // subscript, so both sides root at `rows`. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut rows = [(7, 3)];
            if rows[0] is (let a, let b) {
                rows[0].1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_nested_component_write_does_not_reach_a_nested_capture() {
    // Depth on both sides at once: the capture sits inside a nested tuple
    // pattern and the write reaches it through two components (`n.0.1`).
    // Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut n = ((7, 3), 5);
            if n is ((let i, let j), let k) {
                n.0.1 = 99;
                print(j);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_mut_self_method_call_does_not_reach_a_capture_of_its_receiver() {
    // The write need not be spelled in the arm at all. `bump` takes `&mut
    // self` and writes a component through it, so the CALL is the in-place
    // write and the receiver's root joins the write set — the same arm of
    // `collect_written_roots` the `own`-parameter capture pins above use.
    // Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Counter { pair: (i32, i32) }
        impl Counter {
            fun bump(&mut self) { self.pair.1 = 99 }
        }
        fun main() {
            mut counter = Counter { pair = (7, 3) };
            if counter.pair is (let p, let q) {
                counter.bump();
                print(q);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_write_through_a_mut_view_of_the_subject_does_not_reach_its_captures() {
    // Why the question is asked at the ROOT and not by walking the arm: the
    // view is minted OUTSIDE the arm and written INSIDE it, so the write's own
    // place root is `vv`, not `vt`, and an arm-local write-set walk would see
    // nothing to report. Taking the `&mut` is itself a recorded write of
    // `vt`, which is what makes the root question sound. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut vt = (7, 3);
            let vv = &mut vt;
            if vt is (let a, let b) {
                vv.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_guarded_leg_capture_from_a_component_written_place_reads_the_prematch_value() {
    // A guard puts the leg on the alias path too, and its captures carry the
    // same hole. It is also the ordering-sensitive one (B59): the guard is
    // walked after `materialize_captures` has re-pointed the alias table, so a
    // guard that reads a materialized capture takes the prelude shape or names
    // a binding that has not been declared. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut gl = (7, 3);
            match gl {
                (let q, let r) if r > 0 => {
                    gl.1 = 99;
                    print(r);
                }
                _ => {}
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn an_unguarded_match_leg_on_a_component_written_place_was_already_right() {
    // The negative half of the diagnosis, the same one B81 pinned through a
    // view: an unguarded leg compiles through `compile_pattern`, which
    // declares every capture as a real `const` at leg entry, so it never read
    // late and never had the bug. Pinned so the fix cannot move it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut ml = (7, 3);
            match ml {
                (let s, let v) => {
                    ml.1 = 99;
                    print(v);
                }
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_destructure_from_a_component_written_place_was_already_right() {
    // The declared path's other spelling, for the same reason: `let (a, b) =
    // t` reads both slots eagerly, so a later component write has nothing to
    // reach back into.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut d = (7, 3);
            let (d1, d2) = d;
            d.1 = 99;
            print(d2);
        }
        "#,
        "3\n",
    );
}

#[test]
fn both_capture_shapes_survive_a_component_write_to_the_place() {
    // The place twin of `both_capture_shapes_survive_an_in_place_write_
    // through_the_view`, which is what makes "the two paths are
    // indistinguishable per shape" a checked claim: the same two payload
    // shapes, the same two component writes, an owned `mut` local instead of a
    // `&mut` parameter, and the same answers. `items` is B53's business (an
    // aggregate capture COPIES, so growing the source to 4 leaves it at 3);
    // `at` is B88's (a scalar owes no copy, so it kept an accessor and read
    // the 9). One pin, red either way: 12 without the materialization, 4
    // without the copy.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut pair = (["a", "b", "c"], 0);
            if pair is (let items, let at) {
                pair.0.push("d");
                pair.1 = 9;
                print(items.len() + at);
            }
            print(pair.0.len());
        }
        "#,
        "3\n4\n",
    );
}

#[test]
fn a_resource_capture_from_a_component_written_place_loans_the_prematch_payload() {
    // R1/R11 and B65's doctrine at the third subject form. A resource payload
    // has no copy to make — "there is no user-facing copy spelling in vilan to
    // name" (affine-moves.md §9.1) — so the capture is materialized WITHOUT
    // `__clone`: `const c = $a[0]`, which fixes WHICH value is loaned without
    // minting a second owner to destroy twice. Exactly what the viewed twin
    // does, and what the whole-assignment place twin already did. 1, not 6.
    let source = r#"
        import std::print;
        resource struct Conn { id: i32 }
        fun main() {
            mut slot = (Conn { id = 1 }, 0);
            if slot is (let c, let at) {
                slot.1 = 5;
                print(c.id + at);
            }
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "the resource capture was materialized WITH a copy:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "1\n");
}

#[test]
fn a_whole_assignment_to_the_subject_still_leaves_its_captures_aliasing() {
    // The line the rule stops at, and the reason it is not simply "every place
    // subject materializes". Assigning the whole binding REBINDS it — `t = [
    // 1, 2 ]` installs a fresh array and the subject temp keeps the old one —
    // so the accessor is a faithful snapshot and there is nothing to fix. The
    // capture must therefore stay an accessor: naming it in the output would
    // mean the predicate had widened to every place subject, which is what
    // moves six corpus goldens and takes back B53's share elision on the alias
    // path.
    let source = r#"
        import std::print;
        fun main() {
            mut t = (7, 3);
            if t is (let first, let kept) {
                t = (1, 2);
                print(kept);
            }
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("kept"),
            "a rebinding assignment materialized the capture anyway:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "3\n");
}

// ---------------------------------------------------------------------------
// B97 (the THIRD subject spelling: a `borrows` CALL). A method returning a
// `&mut` projection hands the pattern a subject that aliases the receiver's
// storage, but the expression is a CALL — and `is_capture_subject_place`
// admitted places and `*view` only, so the subject collected no candidates at
// all and BOTH rules were missing at once: B53's copy and B81/B88's
// materialization. Measured before shipping (proposal/capture-clones.md §9),
// and the doctrine per payload shape is twinned below onto this path.
// ---------------------------------------------------------------------------

#[test]
fn a_borrows_call_subject_reads_the_prematch_value() {
    // The VALUE half of the doctrine (§7.5): a scalar owes no copy, so the
    // declaration alone fixes the timing. Before B97 this subject collected no
    // candidates whatever — `const $a = slot(h); … $a[1]` — so the capture
    // re-read the mutated slot and printed 99, the same shape §6.4 found for
    // `*view`, one spelling over.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun slot(&mut self): &mut (i32, i32) borrows self { &mut self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            if h.slot() is (let a, let b) {
                h.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_call_subject_copies_its_captures() {
    // The AGGREGATE half (§7.5), and the worse of the two because it is B53's
    // ORIGINAL bug rather than a timing one: the capture aliased the
    // receiver's element outright (no `__clone` anywhere in the output), so
    // growing the source through the receiver grew the capture. Printed 3.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { cells: (List<i32>, i32) }
        impl Holder {
            fun slot(&mut self): &mut (List<i32>, i32) borrows self { &mut self.cells }
        }
        fun main() {
            mut g = Holder { cells = ([1, 2], 3) };
            if g.slot() is (let xs, let n) {
                g.cells.0.push(9);
                print(xs.len());
            }
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_resource_capture_from_a_borrows_call_subject_loans_the_prematch_payload() {
    // The RESOURCE half of the doctrine (§7.5), twinned onto the third path.
    // R1 forbids the copy and B65 forbids inventing one ("there is no
    // user-facing copy spelling in vilan to name", affine-moves.md §9.1), so
    // the capture is materialized BARE — `const c = $a[0]`, no `__clone` — which
    // fixes WHICH value is loaned without minting a second owner to destroy
    // twice. Both halves asserted: the value (1, not 6) and the absent copy.
    let source = r#"
        import std::print;
        resource struct Conn { id: i32 }
        struct Holder { slot: (Conn, i32) }
        impl Holder {
            fun view(&mut self): &mut (Conn, i32) borrows self { &mut self.slot }
        }
        fun main() {
            mut holder = Holder { slot = (Conn { id = 1 }, 0) };
            if holder.view() is (let c, let at) {
                holder.slot.1 = 5;
                print(c.id + at);
            }
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "the resource capture was materialized WITH a copy:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "1\n");
}

#[test]
fn both_capture_shapes_survive_a_write_through_a_borrows_call_subject() {
    // The two-shape twin of `both_capture_shapes_survive_a_component_write_to_
    // the_place` and its viewed sibling — what makes "the three paths are
    // indistinguishable per shape" a checked claim rather than a story. Same
    // two payload shapes, same two writes, a `borrows`-call subject instead of
    // a place or a `&mut` parameter, same answers. Red on either axis: 12
    // without the materialization, 4 without the copy.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (List<str>, i32) }
        impl Holder {
            fun view(&mut self): &mut (List<str>, i32) borrows self { &mut self.pair }
        }
        fun main() {
            mut holder = Holder { pair = (["a", "b", "c"], 0) };
            if holder.view() is (let items, let at) {
                holder.pair.0.push("d");
                holder.pair.1 = 9;
                print(items.len() + at);
            }
            print(holder.pair.0.len());
        }
        "#,
        "3\n4\n",
    );
}

#[test]
fn a_readonly_borrows_call_subject_materializes_when_a_write_reaches_the_receiver() {
    // Why the rule is not simply `returns_mut_view`, measured (§9): a `&`
    // projection cannot be written THROUGH, but the receiver it projects can
    // still be written under its own name while the leg is live, and the temp
    // aliases the receiver's storage either way. B81's writable-view arm does
    // not cover this, so the second arm asks B88's root question — of the
    // arguments the callee projects, which is where the receiver is visible.
    // Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun peek(&self): &(i32, i32) borrows self { &self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            if h.peek() is (let a, let b) {
                h.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_free_function_borrows_call_subject_reads_the_prematch_value() {
    // The receiver is not special — `borrows` names a parameter POSITION, and
    // the projection is read at the call site from whatever argument sits
    // there. A rule keyed on "the subject is a method call on a place" would
    // miss this. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun slot(h: &mut Holder): &mut (i32, i32) borrows h { &mut h.pair }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            if slot(&mut h) is (let a, let b) {
                h.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_guarded_leg_over_a_borrows_call_subject_reads_the_prematch_value() {
    // B59's placement question on the third path: a guard that reads a
    // materialized capture takes the prelude shape, and the leg still sees the
    // pre-write value. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun slot(&mut self): &mut (i32, i32) borrows self { &mut self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            print(match h.slot() {
                (let a, let b) if b > 0 => {
                    h.pair.1 = 99;
                    b
                }
                _ => 0,
            });
        }
        "#,
        "3\n",
    );
}

#[test]
fn an_unguarded_match_over_a_borrows_call_subject_copies_its_aggregate_capture() {
    // The unguarded leg never had the TIMING bug — `compile_pattern` declares
    // every capture as a real `const` at leg entry — but it had the COPY one,
    // because the copy question is settled by the candidate set both paths
    // share. Printed 3.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { cells: (List<i32>, i32) }
        impl Holder {
            fun slot(&mut self): &mut (List<i32>, i32) borrows self { &mut self.cells }
        }
        fun main() {
            mut g = Holder { cells = ([1, 2], 3) };
            match g.slot() {
                (let xs, let n) => {
                    g.cells.0.push(9);
                    print(xs.len());
                }
            }
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_let_destructure_of_a_borrows_call_copies_its_aggregate_capture() {
    // §6.4's other half at this spelling: the capture pass gates
    // `Expr::Destructure` on the same predicate, so `let (xs, n) = h.slot()`
    // never copied either and growing the element through the receiver grew
    // the capture. Printed 3.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { cells: (List<i32>, i32) }
        impl Holder {
            fun slot(&mut self): &mut (List<i32>, i32) borrows self { &mut self.cells }
        }
        fun main() {
            mut g = Holder { cells = ([1, 2], 3) };
            let (xs, n) = g.slot();
            g.cells.0.push(9);
            print(xs.len());
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_chained_borrows_projection_subject_reads_the_prematch_value() {
    // Why the writable-view arm is kept alongside the root question, measured
    // rather than argued (§9). A CHAINED projection's receiver is another
    // call, and a call has no place root — so the root arm finds nothing to
    // ask about and the subject would keep its accessor. B81's arm needs no
    // write to be found: a `&mut` projection is a writable view by
    // construction, whatever it was projected from. Printed 99 without it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { pair: (i32, i32) }
        struct Outer { inner: Inner }
        impl Outer {
            fun inner_mut(&mut self): &mut Inner borrows self { &mut self.inner }
        }
        impl Inner {
            fun slot(&mut self): &mut (i32, i32) borrows self { &mut self.pair }
        }
        fun main() {
            mut o = Outer { inner = Inner { pair = (7, 3) } };
            if o.inner_mut().slot() is (let a, let b) {
                o.inner.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_readonly_projection_of_a_writable_one_reads_the_prematch_value() {
    // The same arm read ONE LEVEL UP, and the shape that shows the two halves
    // are not the same question. `peek()` returns `&`, so the outer call is
    // not itself a writable view; its receiver is `inner_mut()`, which is —
    // and the storage the temp aliases is therefore writable after all. The
    // root arm cannot reach it (the receiver is a call, so it has no root),
    // and the outer call's own convention says the wrong thing. Printed 99
    // without the recursion into the projected receiver.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { pair: (i32, i32) }
        struct Outer { inner: Inner }
        impl Outer {
            fun inner_mut(&mut self): &mut Inner borrows self { &mut self.inner }
        }
        impl Inner {
            fun peek(&self): &(i32, i32) borrows self { &self.pair }
        }
        fun main() {
            mut o = Outer { inner = Inner { pair = (7, 3) } };
            if o.inner_mut().peek() is (let a, let b) {
                o.inner.pair.1 = 99;
                print(b);
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_wrapped_view_capture_over_a_borrows_call_is_not_copied() {
    // The line the widening had to stop at, and the one the measurement found
    // (§9): admitting `borrows` calls newly reaches `Option<&mut T>` returns,
    // whose `Some(let v)` capture IS a view. References are transparent, so
    // `&mut List<i32>` is an aggregate by every type test in the pass and the
    // first candidate copied it — which deep-copies the borrowed storage, so
    // `v[0] = 77` landed on the copy and the caller's list never changed
    // (`option-view.vl`, 77 -> 1, a semantic break rather than a cost).
    // A view aliases on purpose: it never copies.
    let source = r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun inner_mut(&mut self): Option<&mut Inner> { Some(&mut self.inner) }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 1 } };
            match h.inner_mut() {
                Some(let v) => { v.n = 77; }
                None => {}
            }
            print(h.inner.n);
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "a view capture was copied, which breaks the alias:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "77\n");
}

#[test]
fn an_owned_call_subject_still_binds_without_copying() {
    // The elision the widening must not take back, in bytes: a call returning
    // an OWNED value produces storage of its own, so its elements have no
    // second owner and B53 §2's "destructuring a FRESH value binds without
    // copying" stands. `call_returns_view` is what separates the two, not
    // "the subject is a call".
    let source = r#"
        import std::print;
        fun make(): (List<i32>, i32) { ([1, 2], 3) }
        fun main() {
            if make() is (let xs, let n) {
                print(xs.len() + n);
            }
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "an owned call result's capture was copied:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "5\n");
}

#[test]
fn a_borrows_call_subject_with_no_write_in_the_leg_is_unchanged() {
    // The neighbour that was already right and must stay right: nothing writes
    // the receiver while the leg is live, so the aggregate capture's copy is
    // the only thing owed and the answer never depended on the timing.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { cells: (List<i32>, i32) }
        impl Holder {
            fun slot(&mut self): &mut (List<i32>, i32) borrows self { &mut self.cells }
        }
        fun main() {
            mut g = Holder { cells = ([1, 2], 3) };
            if g.slot() is (let xs, let n) {
                print(xs.len() + n);
            }
        }
        "#,
        "5\n",
    );
}

// ---------------------------------------------------------------------------
// B54 / A20 (rule 1 at the STORE seams). A place read into a slot of an
// aggregate that outlives the expression must copy: a construction literal's
// element/field/payload (B54), and the argument of a container method that
// keeps it (A20, via `own`). See proposal/element-clones.md.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// B100 (the return rule's loan hole). §3 of element-clones.md exempted a
// `&`/`&mut` parameter from the return copy, framed as "returning through one
// is rule 3's `borrows` projection, deliberately an alias". That is a fact
// about the RETURN, not about the place: a function whose signature hands back
// a VALUE hands back a value, whatever convention the place it read is under.
// R3's own list calls bare, `&` and `&mut` all loans, and the bare half already
// copied — the asymmetry was the bug. See proposal/element-clones.md §9.
// ---------------------------------------------------------------------------

#[test]
fn a_returned_field_place_copies_out_of_its_receiver() {
    // The filed repro (B97's bycatch), now closed. `fun make(&self): (i32, i32)
    // { self.pair }` emitted `return self[0]`, so the caller's result WAS the
    // receiver's field storage and a later write to the receiver showed through
    // it. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun make(&self): (i32, i32) { self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = h.make();
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_returned_field_place_copies_out_of_a_mut_receiver() {
    // `&mut self` is the same loan with a different writability, and the return
    // seam never asked about writability — the caller's storage outlives the
    // call either way.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun make(&mut self): (i32, i32) { self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = h.make();
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_returned_field_of_a_view_parameter_copies() {
    // The free-function spelling: nothing about this is special to a receiver.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun make(h: &Holder): (i32, i32) { h.pair }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = make(&h);
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_view_receiver_forwarded_whole_into_a_by_value_return_copies() {
    // The shape that decides how the exemption is spelled. Asking whether the
    // returned PLACE is a view answers the wrong question here — references are
    // transparent, so `self` inside `&self` is a view by every test — while the
    // signature says plainly that what leaves is a `Holder`, by value. The
    // exemption reads the signature.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun copy(&self): Holder { self }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let c = h.copy();
            h.pair.1 = 99;
            print(c.pair.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_returned_nested_field_of_a_receiver_copies() {
    // The copy lands at the LEAF, so the depth of the projection is irrelevant.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { pair: (i32, i32) }
        struct Holder { inner: Inner }
        impl Holder {
            fun make(&self): (i32, i32) { self.inner.pair }
        }
        fun main() {
            mut h = Holder { inner = Inner { pair = (7, 3) } };
            let p = h.make();
            h.inner.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_returned_list_field_of_a_receiver_copies() {
    // The A20 shape one seam over: the result's ELEMENTS were the receiver's,
    // so growing the result grew the receiver.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { items: List<i32> }
        impl Holder {
            fun items_of(&self): List<i32> { self.items }
        }
        fun main() {
            mut h = Holder { items = [1, 2] };
            mut xs = h.items_of();
            xs.push(9);
            print(h.items.len());
        }
        "#,
        "2\n",
    );
}

#[test]
fn a_returned_field_copies_in_the_tail_arm_that_owes_it() {
    // Keyed by the tail LEAF, so an `if`/`match` tail copies only in the arms
    // that hand back the receiver's storage — the constructed arm stays free.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun pick(&self, first: bool): (i32, i32) {
                if first { self.pair } else { (0, 0) }
            }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = h.pick(true);
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn an_early_ret_of_a_receivers_field_copies() {
    // The `ret` statement is a return seam like the tail is; both feed
    // `return_sites`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun make(&self, early: bool): (i32, i32) {
                if early { ret self.pair }
                (0, 0)
            }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = h.make(true);
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_projection_still_returns_the_alias() {
    // The elision the rule must not eat, and the reason the exemption exists at
    // all: a signature that returns `&mut T` hands back an alias on purpose
    // (rule 3's sanctioned escape), so writing through the result reaches the
    // receiver.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun slot(&mut self): &mut (i32, i32) borrows self { &mut self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            h.slot() = (1, 2);
            print(h.pair.0);
        }
        "#,
        "1\n",
    );
}

#[test]
fn a_readonly_borrows_projection_still_returns_the_alias() {
    // The `&` half of the same exemption — a read-only projection is still a
    // projection, and its result must keep naming the receiver's storage.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun peek(&self): &(i32, i32) borrows self { &self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let v = h.peek();
            h.pair.1 = 99;
            print((*v).1);
        }
        "#,
        "99\n",
    );
}

#[test]
fn a_view_parameter_forwarded_into_a_view_return_still_aliases() {
    // The exemption's own shape, and the twin of the by-value case above: the
    // SAME body — a view parameter handed straight back — is an alias here and
    // a copy there, and only the signature separates them. This is what the
    // `returns_view` question is for; nothing else in the pass distinguishes
    // the two, because a `&mut place` leaf is not a place at all and never
    // reaches the seam.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun same(v: &mut Holder): &mut Holder borrows v { v }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let w = same(&mut h);
            w.pair.1 = 99;
            print(h.pair.1);
        }
        "#,
        "99\n",
    );
}

#[test]
fn a_receiver_forwarded_into_a_view_return_still_aliases() {
    // The method spelling of the same exemption, which is `copy(&self):
    // Holder { self }` with one word changed in the return type.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun me(&mut self): &mut Holder borrows self { self }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let w = h.me();
            w.pair.1 = 99;
            print(h.pair.1);
        }
        "#,
        "99\n",
    );
}

#[test]
fn a_bare_self_receivers_field_return_was_already_right() {
    // The neighbour that names the asymmetry: R3 calls bare `self`, `&self` and
    // `&mut self` all loans, and the bare one already copied. Pinned so the two
    // stay one rule.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun make(self): (i32, i32) { self.pair }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = h.make();
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_returned_own_parameter_still_moves_out_of_a_view_receivers_neighbour() {
    // The `own` elision, unchanged: the caller already gave the value up, so the
    // fluent-builder shape stays free. Proven by the ABSENT `__clone`, since
    // behaviour cannot see the difference.
    let source = r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun through(own h: Holder): Holder { h }
        fun main() {
            let h = Holder { pair = (7, 3) };
            let c = through(h);
            print(c.pair.1);
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "an `own` parameter's return copied:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "3\n");
}

#[test]
fn a_returned_scalar_field_of_a_receiver_needs_no_copy() {
    // The type filter is unchanged: a scalar read IS the copy, so no `__clone`
    // is owed and none is emitted.
    let source = r#"
        import std::print;
        struct Holder { n: i32 }
        impl Holder {
            fun get(&self): i32 { self.n }
        }
        fun main() {
            mut h = Holder { n = 7 };
            let v = h.get();
            h.n = 99;
            print(v);
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(!js.contains("__clone"), "a scalar return copied:\n{js}"),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "7\n");
}

#[test]
fn a_closure_returning_its_own_view_parameters_field_copies() {
    // The closure path, already right before the fix (an unannotated closure
    // parameter is bare) and pinned so the seam's two spellings stay one rule.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun apply(h: &Holder, f: |&Holder| (i32, i32)): (i32, i32) { f(h) }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = apply(&h, |g| g.pair);
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

// ---------------------------------------------------------------------------
// B104 (the classification residual B100 filed). `infer_borrows` recorded `fun
// copy(&self): Holder { self }` as borrowing its receiver — so its result bound
// as a VIEW at every call site — although B100 made that return a COPY. The
// root-set arm whose leaf is a PLACE is the one rule 1's return clause reaches,
// so the two passes now answer the same way about the same seam: where the
// return copies, the place LEFT the loan and the function projects nothing.
// `check_view_escape` still accepts the forwarder, for the same reason (nothing
// escapes when nothing aliased leaves). See proposal/element-clones.md §9.3.
// ---------------------------------------------------------------------------

#[test]
fn a_by_value_forwarders_result_binds_mut() {
    // The filed repro. Both halves in one program: the result is `mut`-bindable
    // (it is a value, not a view), and writing it leaves the receiver alone
    // (B100's copy is what makes the first half true).
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun copy(&self): Holder { self }
        }
        fun main() {
            let h = Holder { pair = (7, 3) };
            mut c = h.copy();
            c.pair.1 = 42;
            print(c.pair.1);
            print(h.pair.1);
        }
        "#,
        "42\n3\n",
    );
}

#[test]
fn a_free_by_value_forwarders_result_binds_mut() {
    // The free-function spelling: nothing here is special to a receiver, and
    // the caller's own value is untouched by the write to the copy.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun copy_of(h: &Holder): Holder { h }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            mut c = copy_of(&h);
            c.pair.1 = 42;
            h.pair.1 = 99;
            print(c.pair.1);
            print(h.pair.1);
        }
        "#,
        "42\n99\n",
    );
}

#[test]
fn a_by_value_forwarder_still_passes_the_escape_check() {
    // The hazard B100 recorded when it refused candidate (c): emptying the
    // root-set makes `check_view_escape` reject the body outright, turning a
    // program that compiles into an error. It must not, and the reason is rule
    // 3's own: the return hands back a value, so no view escapes.
    assert_compiles(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun copy(&self): Holder { self }
        }
        fun main() {
            let h = Holder { pair = (7, 3) };
            print(h.copy().pair.1);
        }
        "#,
    );
}

#[test]
fn a_view_returning_forwarders_result_is_still_a_view() {
    // The other direction, one word apart: the same body under a `&mut Holder`
    // return is a projection, its result is a view, and a view cannot be `mut`.
    assert_fails_with(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun me(&mut self): &mut Holder borrows self { self }
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            mut w = h.me();
            print(w.pair.1);
        }
        "#,
        "cannot be `mut`",
    );
}

#[test]
fn a_view_of_a_local_still_cannot_escape_a_by_value_return() {
    // The escape the new clause must not swallow: rule 1 leaves a place rooted
    // at a LOCAL alone (the frame is a dead owner donating its storage), so no
    // copy converts this one and the view still dangles.
    assert_fails_with(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        impl Holder {
            fun bad(&self): (i32, i32) { let v = &self.pair; v }
        }
        fun main() {
            let h = Holder { pair = (7, 3) };
            print(h.bad().1);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn a_scalar_view_forwarded_into_a_by_value_return_keeps_its_borrow() {
    // A scalar has no aggregate storage for rule 1 to copy, so the alias
    // survives the return and the (conservative) borrow classification must
    // survive with it — rule 4 still sees a live view into `n`. Pins the gate
    // as CLONEABLE-AGGREGATE-only rather than by-value-only.
    assert_fails_with(
        r#"
        import std::print;
        fun same(v: &mut i32): i32 { v }
        fun main() {
            mut n = 5;
            let m = same(&mut n);
            n = 9;
            print(m);
        }
        "#,
        "rule 4",
    );
}

#[test]
fn a_generic_view_forwarded_into_a_by_value_return_keeps_its_borrow() {
    // The generic twin, and why `Type::Generic` is excluded even though rule 1
    // admits it: a `&T` parameter lowers as a `(base, key)` pair at a scalar
    // instantiation, which `__clone` cannot collapse. The alias survives, so
    // the view classification does too.
    assert_fails_with(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun same<T>(v: &T): T { v }
        fun main() {
            let h = Holder { pair = (7, 3) };
            mut c = same(&h);
            print(c.pair.1);
        }
        "#,
        "cannot be `mut`",
    );
}

#[test]
fn a_borrows_call_chain_into_a_by_value_return_keeps_its_borrow() {
    // The Call arm is deliberately ungated: rule 1 never reaches a call leaf
    // (it is not a place), so no copy is inserted and the result really does
    // alias whatever the signature says. Calling it a borrow is what keeps the
    // call site honest about that.
    assert_fails_with(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun peek(h: &Holder): &(i32, i32) borrows h { &h.pair }
        fun get(h: &Holder): (i32, i32) { peek(h) }
        fun main() {
            let h = Holder { pair = (7, 3) };
            mut p = get(&h);
            print(p.1);
        }
        "#,
        "cannot be `mut`",
    );
}

#[test]
fn a_wrapped_view_return_is_still_a_borrow() {
    // The wrapped arm is ungated for the same reason, and its signature could
    // not carry the gate anyway: `Option<&mut Inner>` is not a view return by
    // `returns_view`, which reads the TOP-LEVEL type node.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun inner_mut(&mut self): Option<&mut Inner> { Some(&mut self.inner) }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 1 } };
            match h.inner_mut() {
                Some(let v) => { v.n = 77; }
                None => {}
            }
            print(h.inner.n);
        }
        "#,
        "77\n",
    );
}

#[test]
fn a_resource_forwarded_out_of_a_loan_is_still_refused() {
    // The resource half of the gate is a guard, not a live case: R1 refuses
    // moving a resource out of a loan before the classification is ever
    // consulted. Pinned so the guard's unreachability is a fact, not a hope.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard {
            fun drop(own self) { print("drop " + self.tag); }
            fun take(&self): Guard { self }
        }
        fun main() {
            let g = Guard { tag = "a" };
            print(g.take().tag);
        }
        "#,
        "cannot move the resource",
    );
}

// ---------------------------------------------------------------------------
// B108 / B109 (B104's bycatch, both of them rule 1's). The return seam reached
// only leaves that are PLACES, so two leaf shapes handed back a caller's
// storage untouched — `&self.inner` (a `&place`, whose `place_root` is `None`)
// and `peek(h)` (a `borrows` call, likewise) — and a THIRD leaf, the scalar
// view, reached the seam but fell out of the copy's type filter and handed back
// its `(base, key)` pair as the value.
//
// One rule for all three: the seam reads THROUGH a view leaf to the storage it
// names (`returned_value_places`, the return twin of B97's
// `capture_subject_places`), and materializes a VALUE there — `__clone` for a
// cloneable aggregate, the READ for a scalar (a scalar's copy IS its read,
// B81). A RESOURCE crosses out of the loan instead, which the move scan judges
// exactly as it judges the bare place twin. The borrow CLASSIFICATION is
// untouched: gating it too was measured and refused (it turns seven compiling
// shapes into "a view cannot escape its scope" and reddens B104's own chain
// pin). See proposal/element-clones.md §11.
// ---------------------------------------------------------------------------

#[test]
fn a_scalar_view_forwarded_into_a_by_value_return_hands_back_the_value() {
    // B108's filed repro. Printed `[ [ 5 ], 0 ]` — the view's runtime pair, not
    // the i32 the signature promises. The copy machinery is aggregate-shaped
    // and `__clone` cannot collapse a pair; the crossing emits the read.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun same(v: &mut i32): i32 { v }
        fun main() {
            mut n = 5;
            let m = same(&mut n);
            print(m);
        }
        "#,
        "5\n",
    );
}

#[test]
fn a_generic_view_forwarded_into_a_by_value_return_reads_at_a_scalar() {
    // B108's second shape, and the reason the read cannot be decided where the
    // copy is: a generic `&T` is a `(base, key)` pair at exactly its scalar
    // instantiations and the aggregate's own reference everywhere else, which
    // is abstract in the analyzer. Printed `[ [ 5 ], 0 ]` — and `__clone`,
    // which rule 1 does insert here (`Type::Generic` is admitted), deep-COPIED
    // the pair rather than collapsing it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun same<T>(v: &T): T { v }
        fun main() {
            mut n = 5;
            let m = same(&n);
            print(m);
        }
        "#,
        "5\n",
    );
}

#[test]
fn a_scalar_reference_leaf_in_a_by_value_return_reads_the_place() {
    // The `&place` spelling of the same crossing, which is B108 and B109 at
    // once: `&self.n` lowers to the pair `[self, 0]`, and by-value out it must
    // be the field READ. Printed `[ [ 99 ], 0 ]` — the pair, and a LIVE one, so
    // the later write showed through it too.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { n: i32 }
        impl Holder {
            fun grab(&self): i32 { &self.n }
        }
        fun main() {
            mut h = Holder { n = 3 };
            let v = h.grab();
            h.n = 99;
            print(v);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_scalar_borrows_call_leaf_in_a_by_value_return_reads_the_place() {
    // The third spelling: a `borrows` call returning `&i32`, one indirection
    // over. Same pair, same live alias, same read.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { n: i32 }
        fun peek(h: &Holder): &i32 borrows h { &h.n }
        fun get(h: &Holder): i32 { peek(h) }
        fun main() {
            mut h = Holder { n = 3 };
            let v = get(&h);
            h.n = 99;
            print(v);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_reference_leaf_in_a_by_value_return_copies() {
    // B109's filed repro. `&self.inner` is not a place, so
    // `compute_return_clone_sites` never saw it and the caller's result WAS the
    // receiver's field. Printed 99.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun grab(&self): Inner { &self.inner }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let i = h.grab();
            h.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_call_leaf_in_a_by_value_return_copies() {
    // B109's second shape, one indirection over: the tail is a call, so rule 1
    // had no place to copy and the by-value signature handed back the callee's
    // alias. Printed 99. Which places a call names is read from the callee's
    // `borrows` clause at the call site — B97's answer, asked at a return.
    //
    // The classification stays a VIEW here (B104's ungated Call arm, whose own
    // pin is the `mut` twin of this program): conservative, and the copy is
    // what makes it merely conservative rather than wrong.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun peek(h: &Holder): &(i32, i32) borrows h { &h.pair }
        fun get(h: &Holder): (i32, i32) { peek(h) }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let p = get(&h);
            h.pair.1 = 99;
            print(p.1);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_mut_reference_leaf_in_a_by_value_return_copies() {
    // The `&mut` spelling of B109's first shape — one character apart, same
    // answer, because what decides is the SIGNATURE (B100's finding) and not
    // the leaf's own view-ness.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun grab(&mut self): Inner { &mut self.inner }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let i = h.grab();
            h.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_free_parameters_reference_leaf_in_a_by_value_return_copies() {
    // Nothing here is special to a receiver: a free `&` parameter is the same
    // loan, and `place_root` walks to it the same way.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun grab_of(h: &Holder): Inner { &h.inner }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let i = grab_of(&h);
            h.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_nested_reference_leaf_in_a_by_value_return_copies() {
    // Depth is the place walk's business, not the seam's: `&self.mid.inner`
    // roots at `self` like `&self.inner` does.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Mid { inner: Inner }
        struct Holder { mid: Mid }
        impl Holder {
            fun grab(&self): Inner { &self.mid.inner }
        }
        fun main() {
            mut h = Holder { mid = Mid { inner = Inner { n = 3 } } };
            let i = h.grab();
            h.mid.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_tail_if_arms_reference_leaf_in_a_by_value_return_copies() {
    // The seam is keyed by the LEAF, so a tail `if` copies per arm — the same
    // reason B100 pinned its own conditional shape.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner, other: Inner }
        impl Holder {
            fun grab(&self, first: bool): Inner {
                if first { &self.inner } else { &self.other }
            }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 }, other = Inner { n = 5 } };
            let i = h.grab(true);
            h.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_method_leaf_in_a_by_value_return_copies() {
    // The method spelling of the call shape: the projected argument is the
    // receiver, at position 0 of the call.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun peek(&self): &Inner borrows self { &self.inner }
            fun grab(&self): Inner { self.peek() }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let i = h.grab();
            h.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_call_chain_leaf_in_a_by_value_return_copies() {
    // The CHAIN, which is what makes the read-through recursive: the outer
    // call's projected argument is itself a call, and only one more step
    // reaches a place at all. Without the recursion this hands back the alias.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Mid { inner: Inner }
        struct Outer { mid: Mid }
        impl Mid {
            fun slot(&mut self): &mut Inner borrows self { &mut self.inner }
        }
        impl Outer {
            fun mid_mut(&mut self): &mut Mid borrows self { &mut self.mid }
        }
        fun grab(o: &mut Outer): Inner { o.mid_mut().slot() }
        fun main() {
            mut o = Outer { mid = Mid { inner = Inner { n = 3 } } };
            let i = grab(&mut o);
            o.mid.inner.n = 99;
            print(i.n);
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_borrows_call_on_a_local_in_a_by_value_return_copies_nothing() {
    // The elision the new arms must not eat, and it is B100's own: the frame is
    // a dead owner at the return, so a projection of a LOCAL donates its
    // storage. Reading through the call reaches `h`, a local, and stops.
    let source = r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun peek(h: &Holder): &Inner borrows h { &h.inner }
        fun make(): Inner { let h = Holder { inner = Inner { n = 3 } }; peek(&h) }
        fun main() { print(make().n); }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "a dead owner's donation copied:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "3\n");
}

#[test]
fn an_owned_call_leaf_in_a_by_value_return_copies_nothing() {
    // The other half of "a call owns its result": a callee with no `borrows`
    // clause projects nothing, so reading through it names no place and the
    // seam has nothing to copy.
    let source = r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun fresh(): Inner { Inner { n = 3 } }
        fun grab(h: &Holder): Inner { fresh() }
        fun main() {
            let h = Holder { inner = Inner { n = 1 } };
            print(grab(&h).n);
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "an owned call result copied:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "3\n");
}

#[test]
fn a_reference_leaf_in_a_view_return_still_aliases() {
    // Rule 3's sanctioned projection, unchanged: the signature returns a view,
    // so nothing crosses and `&mut self.inner` stays the alias it is for.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun peek(&mut self): &mut Inner borrows self { &mut self.inner }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            h.peek().n = 99;
            print(h.inner.n);
        }
        "#,
        "99\n",
    );
}

#[test]
fn a_reference_leaf_handing_back_a_resource_is_refused() {
    // R1: a resource cannot copy, so the crossing is a MOVE out of the loan —
    // and `&self.g` is `self.g` with a `&` in front of it, which the move scan
    // already refuses as a partial move. Before the fix this compiled and
    // printed the tag with no `drop` at all: the resource left the loan
    // uncopied AND undestroyed.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        impl Holder {
            fun take(&self): Guard { &self.g }
        }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(h.take().tag);
        }
        "#,
        "cannot move a resource field out of a live aggregate",
    );
}

#[test]
fn a_borrows_call_leaf_handing_back_a_resource_is_refused() {
    // The call spelling of the same crossing: the place it names is the loaned
    // parameter itself, so the diagnostic is R3's — the same one the bare
    // forwarder `fun take(&self): Guard { self }` already gets.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        fun peek(h: &Holder): &Guard borrows h { &h.g }
        fun take(h: &Holder): Guard { peek(h) }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(take(&h).tag);
        }
        "#,
        "cannot move the resource `h` out of this function",
    );
}

#[test]
fn a_reference_leaf_loaning_a_resource_out_of_a_view_return_is_still_allowed() {
    // And the CROSSING is what decides, not the reference: under a view return
    // the very same `&self.g` is rule 3's projection, moves nothing, and stays
    // legal — the two programs differ only in the return type. (The owner's
    // scope-end teardown is `destruction.md`'s subject, not this seam's.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        impl Holder {
            fun peek(&self): &Guard borrows self { &self.g }
        }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(h.peek().tag);
        }
        "#,
        "a\n",
    );
}

// B116 — the `ret` spelling of a return position gets the tail's analysis.
//
// `check_view_escape` read `Expr::FunctionReturn` as an unconditional escape and
// exempted only `function.body.1`, so `ret &self.inner;` was refused while the
// tail spelling one line away compiled (element-clones.md §11.6). A `ret` is a
// return position exactly like the tail (`ret-checking.md`) and rule 1's return
// clause already treated it as one — `return_sites` carries both — so the two
// spellings disagreed about a value the compiler had already decided to copy.
//
// Every pin below is the SAME program in both spellings: a conditional early
// `ret` whose fall-through tail is the same expression. That shape is what
// isolates the escape question from `ret`'s own early-return-only rule — a body
// that ENDS in `ret x;` is separately a type error ("Expected Inner, but got
// void"), which is why B116's filed repro could not be the probe.

#[test]
fn b116_the_ret_spelling_of_a_reference_leaf_agrees_with_the_tail() {
    // B109's first shape, both spellings in one function. The `ret` was refused;
    // the tail compiled and copied. Both now emit the copy, and the same one.
    let javascript = compile(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun grab(&self, flag: bool): Inner {
                if flag { ret &self.inner; }
                &self.inner
            }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let early = h.grab(true);
            let tail = h.grab(false);
            h.inner.n = 99;
            print(early.n);
            print(tail.n);
        }
        "#,
    )
    .expect("a clean compile");
    assert!(
        javascript.contains(
            "function grab(self, flag) {\n\
             \tif (flag) {\n\t\treturn __clone(self[0]);\n\t}\n\
             \treturn __clone(self[0]);\n}"
        ),
        "both spellings should emit the same copy, got:\n{javascript}"
    );
    assert_eq!(
        run_js(&javascript).expect("a clean run"),
        "3\n3\n",
        "neither spelling may hand back the receiver's field"
    );
}

#[test]
fn b116_the_ret_spelling_of_a_scalar_view_reads_the_place() {
    // B108's shape: a scalar has no aggregate to clone, so its copy is its READ
    // (`v[0][v[1]]`). The `ret` gets the same read, not a refusal and not the
    // runtime pair.
    let javascript = compile(
        r#"
        import std::print;
        fun same(v: &mut i32, flag: bool): i32 {
            if flag { ret v; }
            v
        }
        fun main() { mut n = 5; print(same(&mut n, true)); print(same(&mut n, false)); }
        "#,
    )
    .expect("a clean compile");
    assert!(
        javascript.contains(
            "function same(v, flag) {\n\
             \tif (flag) {\n\t\treturn v[0][v[1]];\n\t}\n\
             \treturn v[0][v[1]];\n}"
        ),
        "both spellings should read the scalar place, got:\n{javascript}"
    );
    assert_eq!(
        run_js(&javascript).expect("a clean run"),
        "5\n5\n",
        "neither spelling may hand back the view pair"
    );
}

#[test]
fn b116_the_ret_spelling_of_a_borrows_call_leaf_copies() {
    // B109's second shape: the leaf is a CALL, so the places it hands back are
    // read from the callee's `borrows` clause. Same answer at the `ret`.
    let javascript = compile(
        r#"
        import std::print;
        struct Holder { pair: (i32, i32) }
        fun peek(h: &Holder): &(i32, i32) borrows h { &h.pair }
        fun get(h: &Holder, flag: bool): (i32, i32) {
            if flag { ret peek(h); }
            peek(h)
        }
        fun main() {
            mut h = Holder { pair = (7, 3) };
            let early = get(&h, true);
            h.pair.1 = 99;
            print(early.1);
        }
        "#,
    )
    .expect("a clean compile");
    assert!(
        javascript.contains(
            "\tif (flag) {\n\t\treturn __clone(peek(h2));\n\t}\n\treturn __clone(peek(h2));"
        ),
        "both spellings should copy the call's projection, got:\n{javascript}"
    );
    assert_eq!(
        run_js(&javascript).expect("a clean run"),
        "3\n",
        "neither spelling may hand back the callee's alias"
    );
}

#[test]
fn b116_the_ret_spelling_of_a_resource_reference_leaf_is_refused() {
    // A resource cannot copy (R1), so the crossing is a MOVE and the move scan
    // refuses it — and it must refuse the `ret` for the SAME reason and with the
    // same words, not because the escape check happened to reject the spelling.
    // Lifting the escape check without telling the crossing about `ret` would
    // have compiled this and leaked the guard uncopied AND undestroyed, which is
    // exactly the bug B109 shipped to close.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        impl Holder {
            fun take(&self, flag: bool): Guard {
                if flag { ret &self.g; }
                &self.g
            }
        }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(h.take(true).tag);
        }
        "#,
        "cannot move a resource field out of a live aggregate",
    );
}

#[test]
fn b116_the_ret_spelling_of_a_resource_borrows_call_is_refused() {
    // The call spelling of the same crossing, where the place named is the
    // loaned parameter itself — R3's diagnostic, at the `ret` as at the tail.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        fun peek(h: &Holder): &Guard borrows h { &h.g }
        fun take(h: &Holder, flag: bool): Guard {
            if flag { ret peek(h); }
            peek(h)
        }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(take(&h, true).tag);
        }
        "#,
        "cannot move the resource `h` out of this function",
    );
}

#[test]
fn b116_the_ret_spelling_of_a_view_of_a_local_still_cannot_escape() {
    // The half that must NOT move. Rule 1's return clause leaves a LOCAL alone —
    // the frame is a dead owner donating its storage — so no copy happens and
    // the view really would dangle. Agreement means agreeing on the refusals
    // too: this is refused in both spellings, as the tail always was.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun grab(flag: bool): Inner {
            let local = Inner { n = 3 };
            if flag { ret &local; }
            &local
        }
        fun main() { print(grab(true).n); }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b116_the_ret_spelling_of_a_borrows_projection_is_sanctioned() {
    // The escape check's OTHER exemption, which the `ret` also never got: a
    // `borrows` function may hand back a view of a view parameter, because the
    // caller's argument outlives the call. Rule 3's sanctioned case, now
    // reachable through either spelling — and it emits the projection, not a
    // copy, in both.
    let javascript = compile(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun view_of(h: &Holder, flag: bool): &Inner borrows h {
            if flag { ret &h.inner; }
            &h.inner
        }
        fun main() { let h = Holder { inner = Inner { n = 3 } }; print(view_of(&h, true).n); }
        "#,
    )
    .expect("a clean compile");
    assert!(
        javascript.contains("\tif (flag) {\n\t\treturn h2[0];\n\t}\n\treturn h2[0];"),
        "a sanctioned projection must not gain a copy, got:\n{javascript}"
    );
    assert_eq!(
        run_js(&javascript).expect("a clean run"),
        "3\n",
        "the projection should reach the field"
    );
}

#[test]
fn b116_a_ret_only_resource_crossing_is_named_by_the_move_scan() {
    // The crossing half of B116, isolated: the resource leaves through the
    // `ret` and the TAIL hands back an owned value, so the tail's own crossing
    // says nothing about it. `compute_return_value_crossings` walked
    // `function.body.1` alone, so the `ret`'s `&self.g` named no place and R1
    // never saw the move. It is joined to the return positions now, and the
    // move scan answers with the bare twin's diagnostic.
    assert_fails_with(
        r#"
        import std::print;
        resource struct Guard { tag: str }
        impl Guard { fun drop(own self) { print("drop " + self.tag); } }
        struct Holder { g: Guard }
        impl Holder {
            fun take(&self, flag: bool): Guard {
                if flag { ret &self.g; }
                Guard { tag = "fresh" }
            }
        }
        fun main() {
            let h = Holder { g = Guard { tag = "a" } };
            print(h.take(true).tag);
        }
        "#,
        "cannot move a resource field out of a live aggregate",
    );
}

#[test]
fn b122_a_ret_beside_an_owned_tail_agrees_with_the_conditional_tail() {
    // Found closing B116 and closed by B122: the two spellings here were
    // examined by different questions. The tail loop asked
    // `escapes_as_view(function.body.1)` of the WHOLE body, and an `if` with
    // one owned arm is not a view expression, so it was never asked at all;
    // the `ret` arm asked the leaf, which is. `infer_borrows` walked only the
    // tail, so the function's root-set stayed empty when a view reached the
    // caller only through a `ret` — and rule 1's return clause copied it
    // regardless, which is what made the refusal a false positive rather than
    // a disagreement about the rule. `element-clones.md` §13 closes the
    // measurement §11.3 candidate (d) deferred.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        impl Holder {
            fun early(&self, flag: bool): Inner {
                if flag { ret &self.inner; }
                Inner { n = 0 }
            }
            fun conditional(&self, flag: bool): Inner {
                if flag { Inner { n = 0 } } else { &self.inner }
            }
        }
        fun main() {
            mut h = Holder { inner = Inner { n = 3 } };
            let early = h.early(true);
            let tail = h.conditional(false);
            h.inner.n = 99;
            print(early.n);
            print(tail.n);
        }
        "#,
        "3\n3\n",
    );
}

#[test]
fn b122_a_conditional_tail_arm_may_not_escape_a_view_of_a_local() {
    // The other side of the same hole, and the one that mattered more: rule 3
    // exists to refuse exactly this, and a second owned arm hid it — the whole
    // body's "is this a view expression" question is `false` for an `if` with
    // one owned arm, so the view arm was never asked at all. The `ret`
    // spelling was already refused, so the two spellings used to disagree in
    // the direction that let code through. (Benign as emitted — the frame is
    // dead and nothing else holds the storage — but it was the rule not being
    // applied, not the rule deciding.) `check_view_escape` now asks each
    // return LEAF (`collect_tail_leaves`), so this arm is examined on its own.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun grab(flag: bool): Inner {
            let local = Inner { n = 3 };
            if flag { Inner { n = 0 } } else { &local }
        }
        fun main() { print(grab(false).n); }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b122_a_conditional_tail_arm_order_does_not_matter() {
    // The mirror of the previous pin: the view-of-a-local arm FIRST, the owned
    // arm second. `collect_tail_leaves` walks both arms of an `if`/`else`
    // regardless of order, so which side hides which is not the question —
    // every leaf gets asked.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun grab(flag: bool): Inner {
            let local = Inner { n = 3 };
            if flag { &local } else { Inner { n = 0 } }
        }
        fun main() { print(grab(false).n); }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b122_a_nested_conditional_arm_may_not_escape_a_view_of_a_local() {
    // `collect_tail_leaves` recurses into a nested `if`'s own branches
    // (`collect_tail_leaves_if`), so a view of a local buried two levels deep
    // is still a leaf the walk reaches, not just the immediate arms of the
    // outermost `if`.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun grab(flag: bool, other: bool): Inner {
            let local = Inner { n = 3 };
            if flag {
                if other { Inner { n = 1 } } else { Inner { n = 2 } }
            } else {
                &local
            }
        }
        fun main() { print(grab(false, false).n); }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b122_a_match_leg_may_not_escape_a_view_of_a_local() {
    // The same walk over a `match` tail (`collect_tail_leaves`'s other arm):
    // one leg owned, one leg a view of a local, and the local leg is still
    // examined on its own regardless of which leg the whole match's TYPE
    // would suggest is representative.
    assert_fails_with(
        r#"
        import std::print;
        enum Choice { A, B }
        struct Inner { n: i32 }
        fun grab(choice: Choice): Inner {
            let local = Inner { n = 3 };
            match choice {
                Choice::A => Inner { n = 0 },
                Choice::B => &local,
            }
        }
        fun main() { print(grab(Choice::A).n); }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b122_a_mixed_leaf_return_refuses_only_the_local_view_leaf() {
    // The multi-leaf mix the leaf-wise walk exists to get right: one arm
    // projects a PARAMETER (sound — the caller's argument outlives the call)
    // and the other a LOCAL (unsound). Leaf-wise, the two are asked
    // separately and answered separately — exactly one diagnostic, and its
    // span is the local arm, not the parameter arm and not the whole `if`.
    let source = r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun grab(h: &Holder, flag: bool): Inner {
            let local = Inner { n = 3 };
            if flag { &h.inner } else { &local }
        }
        fun main() {
            let h = Holder { inner = Inner { n = 9 } };
            print(grab(&h, true).n);
        }
        "#;
    assert_fails_once_with(source, "a view cannot escape its scope");
    assert_fails_spanning(source, "&local", "a view cannot escape its scope");
}

#[test]
fn a_closures_ret_still_cannot_hand_back_a_view() {
    // The boundary of B116's lift. A closure's rets check against its INFERRED
    // tail type and never enter `return_sites`, so they get no exemption — which
    // is right, because a closure may not declare `borrows` and cannot return a
    // view at all (`compute_return_clone_sites` relies on exactly that).
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun main() {
            let h = Holder { inner = Inner { n = 3 } };
            let f = |flag: bool| { if flag { ret &h.inner; } &h.inner };
            print(f(true).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_closure_conditional_tail_arm_may_not_escape_a_view_of_a_closure_local() {
    // The un-masking pin (`element-clones.md` §13.4 / backlog B123): B122 gave
    // `check_view_escape`'s FUNCTION seam a leaf walk, but the closure seam
    // kept the old whole-position question — `escapes_as_view(closure.return_)`
    // asks the closure's whole `Block`/`If`, never leaf-wise, and `is_view_expr`
    // matches neither directly. Every existing pin happened to also spell a
    // `ret`, which the per-expr `Expr::FunctionReturn` arm catches unconditionally
    // regardless of this hole — so the blindness was self-masked. Here there is
    // no `ret` anywhere: the view of a closure-local reaches the caller only
    // through one arm of the closure's conditional TAIL, and the whole-block
    // question was `false` for an `if`, so nothing asked the arm that
    // mattered. Wrongly compiled before this fix (verified against the live
    // compiler, planted red); the `ret` spelling of the identical shape was
    // already refused
    // (`b123_a_closure_ret_and_conditional_tail_arm_agree_refusing_a_view_of_a_closure_local`).
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let grab = |flag: bool| {
                let local = Inner { n = 3 };
                if flag { Inner { n = 0 } } else { &local }
            };
            print(grab(false).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_closure_ret_and_conditional_tail_arm_agree_refusing_a_view_of_a_closure_local() {
    // The REFUSE-direction agreement pin (B116/B122 style): the same shape,
    // spelled the two ways a closure return can be spelled, must answer
    // identically. The `ret` spelling was already refused (the per-expr
    // `Expr::FunctionReturn` arm has no exemption for a closure either), and
    // is not new — what B123 fixes is that the conditional-tail spelling used
    // to disagree, letting the identical view of a closure-local through.
    // Both refuse now.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let via_ret = |flag: bool| {
                let local = Inner { n = 3 };
                if flag { ret &local; }
                Inner { n = 0 }
            };
            print(via_ret(false).n);
        }
        "#,
        "a view cannot escape its scope",
    );
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let via_tail = |flag: bool| {
                let local = Inner { n = 3 };
                if flag { Inner { n = 0 } } else { &local }
            };
            print(via_tail(false).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_closure_ret_and_conditional_tail_arm_agree_accepting_an_owned_leaf() {
    // The ACCEPT-direction agreement pin. Unlike the function seam (B122's
    // `b122_a_ret_beside_an_owned_tail_agrees_with_the_conditional_tail`), a
    // closure has no exemption at all to accept a SOUND view through — it may
    // not declare `borrows`, so every view leaf is unconditionally an escape
    // (P4c). The accept side that exists is the neutral one: an OWNED leaf,
    // which `escapes_as_view` was never going to flag either way, must still
    // compile through both spellings after the leaf walk — proving the walk
    // widens what gets ASKED, not what gets REFUSED.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let via_ret = |flag: bool| {
                if flag { ret Inner { n = 1 }; }
                Inner { n = 0 }
            };
            let via_tail = |flag: bool| {
                if flag { Inner { n = 1 } } else { Inner { n = 0 } }
            };
            print(via_ret(true).n);
            print(via_tail(false).n);
        }
        "#,
        "1\n0\n",
    );
}

#[test]
fn b123_a_closure_conditional_tail_arm_order_does_not_matter() {
    // The mirror of `b123_a_closure_conditional_tail_arm_may_not_escape_a_view_of_a_closure_local`:
    // the view-of-a-local arm FIRST, the owned arm second. `collect_tail_leaves`
    // walks both arms of an `if`/`else` regardless of order.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let grab = |flag: bool| {
                let local = Inner { n = 3 };
                if flag { &local } else { Inner { n = 0 } }
            };
            print(grab(false).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_nested_closure_conditional_arm_may_not_escape_a_view_of_a_closure_local() {
    // `collect_tail_leaves_if`'s recursion into a nested `if`'s own branches
    // reaches the closure seam too — a view of a closure-local buried two
    // levels deep is still a leaf the walk finds.
    assert_fails_with(
        r#"
        import std::print;
        struct Inner { n: i32 }
        fun main() {
            let grab = |flag: bool, other: bool| {
                let local = Inner { n = 3 };
                if flag {
                    if other { Inner { n = 1 } } else { Inner { n = 2 } }
                } else {
                    &local
                }
            };
            print(grab(false, false).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_closure_match_leg_may_not_escape_a_view_of_a_closure_local() {
    // `collect_tail_leaves`'s `match` arm reaches the closure seam too: one
    // leg owned, one leg a view of a closure-local, and the local leg is
    // still examined on its own.
    assert_fails_with(
        r#"
        import std::print;
        enum Choice { A, B }
        struct Inner { n: i32 }
        fun main() {
            let grab = |choice: Choice| {
                let local = Inner { n = 3 };
                match choice {
                    Choice::A => Inner { n = 0 },
                    Choice::B => &local,
                }
            };
            print(grab(Choice::A).n);
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn b123_a_mixed_leaf_closure_return_refuses_each_forbidden_view_leaf_separately() {
    // Three arms: one owned, one a view of a CAPTURE (`&h.inner`, the same
    // shape `a_closures_ret_still_cannot_hand_back_a_view` already refuses
    // through `ret`), one a view of a closure-LOCAL. Unlike the function
    // seam's mixed pin (`b122_a_mixed_leaf_return_refuses_only_the_local_view_leaf`,
    // which has one SOUND leaf and refuses exactly once), a closure has no
    // sound view leaf at all — both view arms are forbidden, so the leaf walk
    // must refuse BOTH, separately, each naming its own span rather than
    // collapsing into one diagnostic or naming the enclosing `if`.
    let source = r#"
        import std::print;
        struct Inner { n: i32 }
        struct Holder { inner: Inner }
        fun main() {
            let h = Holder { inner = Inner { n = 9 } };
            let grab = |flag: bool, other: bool| {
                if flag {
                    Inner { n = 0 }
                } else if other {
                    &h.inner
                } else {
                    let local = Inner { n = 3 };
                    &local
                }
            };
            print(grab(false, false).n);
        }
        "#;
    let matching = failure_diagnostics(source)
        .into_iter()
        .filter(|(message, _)| message.contains("a view cannot escape its scope"))
        .count();
    assert_eq!(
        matching, 2,
        "expected exactly two escape diagnostics, one per forbidden view leaf"
    );
    assert_fails_spanning(source, "&h.inner", "a view cannot escape its scope");
    assert_fails_spanning(source, "&local", "a view cannot escape its scope");
}

#[test]
fn a_list_literal_element_copies_its_source_place() {
    // B54: `[xs]` installed the caller's storage as element 0, so growing the
    // result's element grew `xs`. Printed 3.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs = [1, 2];
            mut ys = [xs];
            ys[0].push(9);
            print(xs.len());
            print(ys[0].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_tuple_literal_element_copies_its_source_place() {
    // The same seam through a tuple, whose elements store flat.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs = [1, 2];
            mut pair = (xs, 1);
            pair.0.push(9);
            print(xs.len());
            print(pair.0.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_struct_literal_field_copies_its_source_place() {
    // Rule 1 names "field initialization" outright; it was not enforced.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { items: List<i32> }
        fun main() {
            mut xs = [1, 2];
            mut holder = Holder { items = xs };
            holder.items.push(9);
            print(xs.len());
            print(holder.items.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_variant_payload_copies_its_source_place() {
    // A variant constructor has no `Parameter` entries, so the `own`-argument
    // arm never saw it: `Some(xs)` captured `xs`'s storage as the payload.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut xs = [1, 2];
            let held = Some(xs);
            xs.push(9);
            match held {
                Some(let inner) => print(inner.len()),
                None => print(0),
            }
            print(xs.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_construction_does_not_see_later_writes_to_its_source() {
    // The read direction of the list-literal seam: the source grows, and the
    // already-built list must not.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs = [1, 2];
            let held = [xs];
            xs.push(9);
            print(held[0].len());
            print(xs.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_nested_construction_copies_at_every_level() {
    // A struct literal inside a list literal: the copy has to reach the inner
    // field, not just the outer element.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Row { cells: List<i32> }
        fun main() {
            mut cells = [1, 2];
            mut rows = [Row { cells = cells }];
            rows[0].cells.push(9);
            print(cells.len());
            print(rows[0].cells.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_pushed_place_copies_into_the_receiver() {
    // A20's root: `push` STORES its argument, so the argument is owned by the
    // callee — `own item: T`. Without it `acc.push(xs)` filed the caller's
    // storage into `acc`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs = [1, 2];
            mut acc: List<List<i32>> = List::new();
            acc.push(xs);
            acc[0].push(9);
            print(xs.len());
            print(acc[0].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn filter_does_not_share_elements_with_its_receiver() {
    // A20: `filter` pushes the loop element straight through.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs: List<List<i32>> = List::new();
            xs.push([1, 2]);
            mut kept = xs.filter(|c| true);
            kept[0].push(9);
            print(xs[0].len());
            print(kept[0].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn reverse_does_not_share_elements_with_its_receiver() {
    // A20's record claimed `reverse` "happens not to alias" because it rebuilds
    // through `push`. It does alias: rebuilding through `push` copies the SPINE
    // only, and `self[index]` hands the element over uncopied.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs: List<List<i32>> = List::new();
            xs.push([1, 2]);
            xs.push([3]);
            mut flipped = xs.reverse();
            flipped[1].push(9);
            print(xs[0].len());
            print(flipped[1].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn sort_by_does_not_share_elements_with_its_receiver() {
    // A20: the intrinsic is `list.slice().sort(cmp)` — a new spine over the
    // same elements.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::compare::Ordering;
        struct Cell { n: i32 }
        fun main() {
            mut cells: List<Cell> = List::new();
            cells.push(Cell { n = 5 });
            mut sorted = cells.sort_by(|a, b| a.n.compare(b.n));
            sorted[0].n = 99;
            print(cells[0].n);
            print(sorted[0].n);
        }
        "#,
        "5\n99\n",
    );
}

#[test]
fn map_does_not_share_elements_with_its_receiver() {
    // A20's fourth method, and the one the STORE rule alone does not reach:
    // `map` pushes `fn(item)`, a call result, which the elision framework
    // assumes is owned. It is not owned when the closure returns a place it
    // borrowed — so the copy lands at the closure's RETURN.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs: List<List<i32>> = List::new();
            xs.push([1, 2]);
            mut mapped = xs.map(|c| c);
            mapped[0].push(9);
            print(xs[0].len());
            print(mapped[0].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_list_method_chain_does_not_share_elements() {
    // The composed case: every hop of `map(...).filter(...)` has to hold.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs: List<List<i32>> = List::new();
            xs.push([1, 2]);
            mut out = xs.map(|c| c).filter(|c| true);
            out[0].push(9);
            print(xs[0].len());
            print(out[0].len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_returned_parameter_place_does_not_alias_the_caller() {
    // "Calls own their result" is the assumption every copy elision rests on
    // (`compute_clone_sites`' own doc comment). A function returning a
    // by-value parameter broke it outright: the caller's binding skipped its
    // copy because the initializer was a call, and the call handed back the
    // caller's own storage.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun identity(c: List<i32>): List<i32> { c }
        fun main() {
            mut xs = [1, 2];
            mut got = identity(xs);
            got.push(9);
            print(xs.len());
            print(got.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_returned_field_of_a_parameter_does_not_alias_the_caller() {
    // The projecting getter — the shape that makes `map`'s closure leak.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { items: List<i32> }
        fun items_of(holder: Holder): List<i32> { holder.items }
        fun main() {
            mut holder = Holder { items = [1, 2] };
            mut got = items_of(holder);
            got.push(9);
            print(holder.items.len());
            print(got.len());
        }
        "#,
        "2\n3\n",
    );
}

#[test]
fn a_returned_local_still_moves() {
    // The elision the return rule must NOT eat: a function's own local is a
    // dead owner at the tail, so it donates its storage rather than copying.
    // Behaviour is identical either way — `copy-elision.js`/`list-methods.js`
    // pin the absence of `__clone` in bytes — so this only guards the output.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun build(): List<List<i32>> {
            mut result: List<List<i32>> = List::new();
            result.push([1, 2]);
            result
        }
        fun main() {
            mut built = build();
            built[0].push(9);
            print(built[0].len());
        }
        "#,
        "3\n",
    );
}

// --- B64: a CLOSURE returns from a frame it does not own ----------------------
//
// The return rule's two free cases — a local (a dead owner at the tail) and an
// `own` parameter (the callee's own storage) — both rest on "the returning frame
// owns this". Inside a closure that is false for anything the closure did not
// declare: the capture's frame does not die at the closure's return, and a
// closure runs many times where a body runs once. `element-clones.md` §7 filed
// the local half; the `own`-parameter half fell out of the same walk.

#[test]
fn a_closure_returning_a_captured_local_does_not_alias_it() {
    // §7's repro. `|| xs` handed out `xs`'s live storage, so pushing to the
    // result grew `xs` — the same leak `fun identity(c) { c }` had before the
    // parameter half of this rule, spelled inline.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            mut xs = [ 1, 2 ];
            let get = || xs;
            mut got = get();
            got.push(9);
            print(got.len());
            print(xs.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_closure_returning_a_captured_own_parameter_does_not_alias_it() {
    // The half §7 did not name, and the reason the fix is not "captures behave
    // like bare parameters": an `own` parameter IS free to return directly (the
    // callee owns it — that is the fluent-builder elision), but a closure over
    // it hands out the SAME storage on every call. Two calls, two independent
    // lists. The bare-parameter twin already worked and is the control.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun make_bare(items: List<i32>): || List<i32> { || items }
        fun make_own(own items: List<i32>): || List<i32> { || items }
        fun main() {
            let bare = make_bare([ 1, 2 ]);
            mut first = bare();
            first.push(9);
            print(bare().len());
            let owned = make_own([ 1, 2 ]);
            mut second = owned();
            second.push(9);
            print(owned().len());
        }
        "#,
        "2\n2\n",
    );
}

#[test]
fn a_closure_returning_its_own_local_still_moves() {
    // The elision the capture rule must NOT eat: a closure's own local is a
    // dead owner at ITS tail, exactly like a function's. Behaviour cannot see
    // the difference — a copy would be correct too — so the proof is the
    // emitted bytes, and the program below has no other `__clone` site.
    let source = r#"
        import std::print;
        fun main() {
            let build = || {
                mut result = [ 1, 2 ];
                result.push(3);
                result
            };
            mut first = build();
            first.push(9);
            print(first.len());
            print(build().len());
        }
        "#;
    match compile(source) {
        Ok(js) => assert!(
            !js.contains("__clone"),
            "the closure's own local no longer donates:\n{js}"
        ),
        Err(errors) => panic!("expected a clean compile, got: {errors:#?}"),
    }
    assert_compiles_and_runs(source, "4\n3\n");
}

#[test]
fn a_closure_returning_a_captured_field_does_not_alias_it() {
    // Keyed by the place's ROOT, so a projection out of a captured aggregate
    // copies on the same rule — the `map`-closure shape, one frame in.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Holder { items: List<i32> }
        fun main() {
            mut holder = Holder { items = [ 1, 2 ] };
            let items_of = || holder.items;
            mut got = items_of();
            got.push(9);
            print(got.len());
            print(holder.items.len());
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_closures_own_is_capture_is_not_a_resource_capture() {
    // Found on the way, pre-existing on v0.25.0 and fixed by the same walk: R9
    // built its declared-inside set without the bindings an `is` pattern
    // introduces, so a closure testing its OWN parameter reported the capture
    // it had just bound as a resource captured from the frame around it. The
    // `match` twin was always fine — only the `is` arm was missing.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        resource struct Db { handle: i32 }
        fun main() {
            let read = |o: Option<Db>| {
                if o is Some(let d) { d.handle } else { 0 }
            };
            print(read(Some(Db { handle = 4 })));
        }
        "#,
        "4\n",
    );
}

#[test]
fn a_guard_that_lifts_emits_its_temporary() {
    // B59, the `?` shape: the lift compiles to a temp plus an `if` over the
    // container's variant, all of which the else-if chain used to drop.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            let held: Option<List<i32>> = Some([1, 2, 3]);
            match held {
                Some(let inner) if (held?.len()).unwrap_or(0) > 2 => print(inner.len()),
                _ => print(0),
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_guard_that_matches_emits_its_temporary() {
    // B59, the nested-`match` shape: an inner match is a subject temp, a result
    // temp and an if-chain — three statements with nowhere to go.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            let held: Option<List<i32>> = Some([1, 2, 3]);
            match held {
                Some(let inner) if match inner.len() { 0 => false, _ => true } => {
                    print(inner.len());
                }
                _ => print(0),
            }
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_later_guarded_leg_gets_its_own_slot() {
    // B59, ordering: the leg that needs the slot is not the first, so its
    // statements have to run only after the earlier leg has declined — a slot
    // hoisted to the top of the match would pop before the first guard is
    // even asked.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun main() {
            mut held: Option<List<i32>> = Some([1, 2, 3]);
            match held {
                Some(let inner) if inner.len() > 5 => print(1),
                Some(mut inner) if inner.pop() is Some(let last) => {
                    print(last);
                    print(inner.len());
                }
                _ => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn a_guard_that_reads_a_copied_capture_reads_the_copy() {
    // B59: the copy a capture owes is declared ahead of a guard that READS it —
    // the guard and the body must see the same binding. `inner` is returned (the
    // value seam), so it copies; the guard's `len` is the copy's.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        fun keep(held: Option<List<i32>>): List<i32> {
            match held {
                Some(let inner) if inner.len() > 1 => inner,
                _ => List::new(),
            }
        }
        fun main() {
            let held: Option<List<i32>> = Some([1, 2]);
            mut got = keep(held);
            got.push(9);
            print(got.len());
            match held {
                Some(let inner) => print(inner.len()),
                None => print(0),
            }
        }
        "#,
        "3\n2\n",
    );
}

#[test]
fn trait_conformance_ignores_parameter_mut() {
    // `mut` is the impl's local business — a trait signature without it is
    // satisfied by an impl with it (and the receiver likewise).
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Doubler { fun doubled(self, x: i32): i32; }
        struct Twice {}
        impl Twice with Doubler {
            fun doubled(mut self, mut x: i32): i32 { x = x * 2; x }
        }
        fun main() { print(Twice {}.doubled(21)); }
        "#,
        "42\n",
    );
}

#[test]
fn shared_write_is_a_view_not_a_value() {
    // `write()` returns a view (`&mut T`), so binding its result to a value slot
    // is rejected (transparent references R1) — use `read()` or `*`.
    assert_fails(
        r#"
        import std::shared::Shared;
        fun main() { let c = Shared::new(5); let x: i32 = c.write(); }
        "#,
    );
}

// --- R8: no implicit borrow at the call site -------------------------------

#[test]
fn r8_explicit_borrow_and_reborrow() {
    // A `&`/`&mut` parameter takes an explicit `&[mut] place`, or an existing
    // view forwarded (re-borrowed) — both compile.
    assert_compiles(
        r#"
        fun bump(x: &mut i32) { x += 1; }
        fun via(y: &mut i32) { bump(y); }
        fun main() { mut a = 0; bump(&mut a); via(&mut a); }
        "#,
    );
}

#[test]
fn r8_method_receiver_is_implicitly_borrowed() {
    // R8 exempts the `self` receiver: `c.inc()` on a `&mut self` method needs no
    // `&mut c` at the call site.
    assert_compiles(
        r#"
        struct C { v: i32 }
        impl C { fun inc(&mut self) { self.v = self.v + 1; } }
        fun main() { mut c = C { v = 0 }; c.inc(); }
        "#,
    );
}

#[test]
fn r8_reject_implicit_borrow() {
    // Passing a bare value place to a `&mut` parameter is rejected — there is no
    // implicit borrow (a scalar would otherwise emit a broken `(base,key)` read).
    assert_fails(
        r#"
        fun bump(x: &mut i32) { x += 1; }
        fun main() { mut a = 0; bump(a); }
        "#,
    );
}

// --- [must_use] -------------------------------------------------------------

#[test]
fn must_use_dropped_result_warns() {
    // A dropped `[must_use]` result (a bare statement) is a warning.
    let messages = warnings(
        r#"
        [must_use]
        fun make(): i32 { 42 }
        fun main() { make(); }
        "#,
    );
    assert!(
        messages.iter().any(|message| message.contains("must_use")),
        "expected a must_use warning, got {messages:?}"
    );
}

#[test]
fn must_use_consumed_result_no_warning() {
    // Binding, discarding with `let _`, or passing as an argument consumes the
    // result — no warning.
    let messages = warnings(
        r#"
        import std::print;
        [must_use]
        fun make(): i32 { 42 }
        fun consume(x: i32) { print(x); }
        fun main() {
            let a = make();
            let _ = make();
            consume(make());
            print(a);
        }
        "#,
    );
    assert!(
        messages.is_empty(),
        "expected no warnings, got {messages:?}"
    );
}

// --- [deprecated] (proposal/deprecation.md) ---------------------------------

/// A copy of the real std with one extra module, `std::deprecated_probe`,
/// whose `stale()` is `[deprecated("use fresh()")]` and whose `wrapper()`
/// calls it std-internally — the §5 mechanism leg's std half, end to end
/// through `resolve_std` and the module loader (the copy's modules register
/// as `std_sources` exactly as the real std's do).
fn deprecation_fixture_std(tag: &str) -> (PathBuf, PackageSpec) {
    fn copy_tree(from: &Path, to: &Path) {
        std::fs::create_dir_all(to).expect("create the fixture std directory");
        for entry in std::fs::read_dir(from).expect("read the std tree") {
            let entry = entry.expect("read a std tree entry");
            let target = to.join(entry.file_name());
            if entry.file_type().expect("stat a std tree entry").is_dir() {
                copy_tree(&entry.path(), &target);
            } else {
                std::fs::copy(entry.path(), &target).expect("copy a std source");
            }
        }
    }
    let root =
        std::env::temp_dir().join(format!("vilan-deprecated-std-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    // `macro_std` rides along: the macro world resolves it BESIDE `std`.
    let tree = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../vilan");
    let std_root = root.join("std");
    copy_tree(&tree.join("std"), &std_root);
    copy_tree(&tree.join("macro_std"), &root.join("macro_std"));
    std::fs::write(
        std_root.join("src").join("deprecated_probe.vl"),
        r#"// Test-only module: a deprecated item beside its replacement, plus a
// std-internal caller (deprecation.md §5's mechanism leg).
fun fresh(): i32 { 1 }

[deprecated("use fresh()")]
fun stale(): i32 { 1 }

fun wrapper(): i32 { stale() }
"#,
    )
    .expect("write the fixture std module");
    let spec = vilan_core::manifest::resolve_std(&std_root);
    (root, spec)
}

#[test]
fn a_deprecated_functions_call_warns_at_the_callee_name() {
    // The family head, verbatim, anchored at the callee NAME (A1/A4 — names
    // over argument lists). The use precedes the declaration so the first
    // occurrence of `one` is the use site.
    assert_warns_spanning(
        r#"
        fun main() { one(); }
        [deprecated("use two()")]
        fun one() { }
        fun two() { }
        "#,
        "one",
        "`one` is deprecated; use two()",
    );
}

#[test]
fn an_unmarked_function_does_not_warn() {
    let messages = warnings(
        r#"
        fun one() { }
        fun main() { one(); }
        "#,
    );
    assert!(
        messages.is_empty(),
        "expected no warnings, got {messages:?}"
    );
}

#[test]
fn every_use_site_of_a_deprecated_function_warns_independently() {
    // Per USE SITE, not once per form (§1, B5): two calls and a passed-as-value
    // reference are three independent fixes, so three warnings.
    let warnings = warning_diagnostics(
        r#"
        fun apply(action: sync || void) { action(); }
        fun main() { old(); old(); apply(old); }
        [deprecated("use fresh()")]
        fun old() { }
        fun fresh() { }
        "#,
    );
    let deprecation_count = warnings
        .iter()
        .filter(|(message, _)| message.contains("`old` is deprecated; use fresh()"))
        .count();
    assert_eq!(
        deprecation_count, 3,
        "each use site warns once; got {warnings:#?}"
    );
}

#[test]
fn a_use_inside_another_deprecated_item_still_warns() {
    // DECIDED (recorded in deprecation.md's ship record): no Rust-style
    // suppression inside deprecated items. Per §1 each use site is an
    // independent fix — the deprecated wrapper's body must migrate too, and
    // std's own hygiene rule (migrate your callers in the deprecating train)
    // reads the same way for user code.
    let warnings = warning_diagnostics(
        r#"
        fun main() { old_outer(); }
        [deprecated("use fresh()")]
        fun old_outer() { old_inner(); }
        [deprecated("use fresh()")]
        fun old_inner() { }
        fun fresh() { }
        "#,
    );
    let heads: Vec<&str> = warnings
        .iter()
        .filter(|(message, _)| message.contains("is deprecated"))
        .map(|(message, _)| message.as_str())
        .collect();
    assert_eq!(
        heads,
        vec![
            "`old_outer` is deprecated; use fresh()",
            "`old_inner` is deprecated; use fresh()",
        ],
        "both use sites warn — the one in `main` and the one inside the deprecated wrapper"
    );
}

#[test]
fn a_deprecated_method_warns_at_the_member_name() {
    // The attribute parses on a member `fun` (one `parse_function`), and the
    // warning anchors at the MEMBER name (`.old_area`), not the whole access.
    assert_warns_spanning(
        r#"
        fun main() {
            let sq = Square { side = 3 };
            let _ = sq.old_area();
        }
        struct Square { side: i32 }
        impl Square {
            [deprecated("use area()")]
            fun old_area(self): i32 { self.side * self.side }
            fun area(self): i32 { self.side * self.side }
        }
        "#,
        "old_area",
        "`old_area` is deprecated; use area()",
    );
}

#[test]
fn a_std_marked_item_warns_at_its_use() {
    // The std half of §5's mechanism leg: an item marked in (fixture) std
    // source warns at its user-code use, head and span, through the real
    // module loader.
    let (root, std) = deprecation_fixture_std("warns");
    let source = r#"
        import std::deprecated_probe::{ stale };
        fun main() { let _ = stale(); }
    "#;
    let warnings = warning_diagnostics_with_std(source, std);
    let matching: Vec<_> = warnings
        .iter()
        .filter(|(message, _)| message.contains("`stale` is deprecated; use fresh()"))
        .collect();
    assert_eq!(
        matching.len(),
        1,
        "exactly the call site warns (the import line is not a use); got {warnings:#?}"
    );
    let expected = source.rfind("stale").expect("the call site");
    assert_eq!(
        matching[0].1,
        expected..expected + "stale".len(),
        "the warning anchors at the callee name"
    );
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
fn a_deprecated_form_used_only_inside_std_stays_silent() {
    // A2: the check keys on the use site's source. `wrapper()` calls the
    // deprecated `stale()` INSIDE std — the user program that only calls
    // `wrapper` sees no warning, which is also what keeps the
    // std-must-be-warning-clean gate green.
    let (root, std) = deprecation_fixture_std("silent");
    let warnings = warning_diagnostics_with_std(
        r#"
        import std::deprecated_probe::{ wrapper };
        fun main() { let _ = wrapper(); }
        "#,
        std,
    );
    assert!(
        warnings.is_empty(),
        "a std-internal use of a deprecated form is silent; got {warnings:#?}"
    );
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
fn enum_constructor_propagates_expected_type_to_payload() {
    // Bidirectional inference (B1): a constructor argument is typed against the
    // *expected* enum's arguments, not the abstract parameter. `Ok(Option::from_json
    // (t))` in a `Result<Option<User>, str>` context types `from_json` against
    // `Option<User>`, so it round-trips. (Was a generic-binding-flow bug.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        [derive(Json)] struct User { id: i32, name: str }
        fun main() {
            let decoded: Result<Option<User>, str> =
                Option::from_json("{\"id\":1,\"name\":\"Ada\"}");
            match decoded {
                Ok(Some(let u)) => print(u.name),
                Ok(None) => print("none"),
                Err(let e) => print(e),
            }
        }
        "#,
        "Ada\n",
    );
}

// --- Known bugs: generic-binding flow (backlog B1, see proposal/type-solver.md) ---
//
// These assert the *desired* behaviour and are `#[ignore]`d because they currently
// produce `undefined` — the two remaining faces of the generic-binding-flow class.
// Remove `#[ignore]` as each lands.

#[test]
fn generic_field_method_dispatch_runs() {
    // `(self.inner).handle(x)` on a generic-bounded field. Field access now
    // substitutes the struct's declared field generic through the subject's actual
    // arguments (`resolve_field_accessor`), so `self.inner` carries the receiver's
    // `T` id rather than the struct definition's — the dispatch binding composes
    // through `current_substitution` and emits the concrete `Doubler::handle`
    // instead of the empty abstract trait method.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Handler { fun handle(self, x: i32): i32; }
        struct Doubler { factor: i32 }
        impl Doubler with Handler { fun handle(self, x: i32): i32 { x * self.factor } }
        struct Wrap<T: Handler> { inner: T }
        impl Wrap<type T: Handler> {
            fun run(self, x: i32): i32 { (self.inner).handle(x) }
        }
        fun main() { let w = Wrap { inner = Doubler { factor = 3 } }; print(w.run(7)); }
        "#,
        "21\n",
    );
}

#[test]
fn generic_field_from_a_variable_dispatches() {
    // Same as above but the field value is a *variable*, so the `Wrap` initializer
    // (priority 1) is reached before `d` is grounded (priority 10) and defers. It
    // must not publish a type while deferred (the unbound parameter would fall back
    // to its constraint, `Wrap<Handler>`), and a pending generic initializer infers
    // as `Unresolved` so `let w = ..` defers instead of grounding on an abstract
    // `Wrap`. With both, `w` grounds to `Wrap<Doubler>` once the initializer
    // resolves, and the dispatch reaches the concrete `Doubler::handle`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Handler { fun handle(self, x: i32): i32; }
        struct Doubler { factor: i32 }
        impl Doubler with Handler { fun handle(self, x: i32): i32 { x * self.factor } }
        struct Wrap<T: Handler> { inner: T }
        impl Wrap<type T: Handler> {
            fun run(self, x: i32): i32 { (self.inner).handle(x) }
        }
        fun main() {
            let d = Doubler { factor = 3 };
            let w = Wrap { inner = d };
            print(w.run(7));
        }
        "#,
        "21\n",
    );
}

#[test]
fn from_json_indirect_element_type_runs() {
    // `decode` returns `Result<Option<User>, str>`; its body is now inferred against
    // that return type (the `ReturnType` constraint), so `Ok(Option::from_json(text))`
    // types `from_json` against `Option<User>` — the constructor propagation (fix #1)
    // then threads `User` into the decode. Previously the body was inferred bottom-up
    // and lowered to the abstract `from_json_value` → `Some(undefined)`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        [derive(Json)] struct User { id: i32, name: str }
        fun decode(text: str): Result<Option<User>, str> { Option::from_json(text) }
        fun main() {
            match decode("{\"id\":1,\"name\":\"Ada\"}") {
                Ok(Some(let u)) => print(u.name),
                Ok(None) => print("none"),
                Err(let e) => print(e),
            }
        }
        "#,
        "Ada\n",
    );
}

#[test]
fn deep_dependency_chain_resolves_across_passes() {
    // Ordering test for the dependency-driven re-queue (item 5 v2): each `id` call's
    // generic `T` binds from its argument, which is the *next* `id` call — so the
    // outer calls can only resolve several passes after the innermost. The runner
    // wakes each deferred call when its input lands (with the run-all backstop as a
    // safety net), so the whole nest resolves to `i32` and prints `7`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::format;
        fun id<T>(x: T): T { x }
        fun main() {
            let deep = id(id(id(id(id(id(7))))));
            print(format(deep));
        }
        "#,
        "7\n",
    );
}

#[test]
fn from_json_return_type_flows_through_match_arm() {
    // The RPC-client shape: the `from_json` decode sits inside a `match` arm whose
    // enclosing function declares the return type. The return type must reach the
    // arm body *through* the match — `resolve_match` propagates the function's
    // expected type into each leg, so `Ok(Option::from_json(json))` binds `User`
    // even though a `match` sits between the call and the signature. Without the
    // propagation the leg was inferred bottom-up → abstract decoder → `Some(undefined)`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        [derive(Json)] struct User { id: i32, name: str }
        fun decode(tag: str, json: str): Result<Option<User>, str> {
            match tag {
                "ok" => Option::from_json(json),
                _ => Err("bad tag"),
            }
        }
        fun main() {
            match decode("ok", "{\"id\":1,\"name\":\"Ada\"}") {
                Ok(Some(let u)) => print(u.name),
                Ok(None) => print("none"),
                Err(let e) => print(e),
            }
        }
        "#,
        "Ada\n",
    );
}

// --- Monomorphization unification (the one `emit_instance` / `call_substitution`
//     path; commit 6b96d3f) and dependency re-queue (item 5 v2) edge cases --------

#[test]
fn multi_parameter_generic_function_instantiations() {
    // The unified emitter keys an instance by its bound types ordered by constraint
    // id; the old free-function emitter keyed by *positional* type arguments. For a
    // two-parameter function those orders coincide (constraint ids are minted in
    // parameter order), and this pins that: `first<A, B>` must instantiate
    // `<i32, str>`, the *swapped* `<str, i32>`, and the same-type `<i32, i32>` as
    // distinct, non-colliding instances — a key bug would cross-wire them.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun first<A, B>(a: A, b: B): A { a }
        fun second<A, B>(a: A, b: B): B { b }
        fun main() {
            print(first(1, "x"));
            print(first("y", 2));
            print(second(1, "z"));
            print(first(3, 4));
        }
        "#,
        "1\ny\nz\n3\n",
    );
}

#[test]
fn multi_parameter_generic_method_monomorphizes() {
    // A two-generic impl whose methods return each parameter — the binding flows
    // through `method_call_substitution` (both `A` and `B` bound from the receiver
    // `Pair<i32, str>`) and field access substitutes the field's declared generic
    // through the receiver's arguments. Both reach the one `emit_instance` path.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Pair<A, B> { left: A, right: B }
        impl Pair<type A, type B> {
            fun show_left(self): A { self.left }
            fun show_right(self): B { self.right }
        }
        fun main() {
            let p = Pair { left = 7, right = "hi" };
            print(p.show_left());
            print(p.show_right());
        }
        "#,
        "7\nhi\n",
    );
}

#[test]
fn operator_monomorphizes_on_generic_aggregate() {
    // `==` on `Option<Point>` overloads to the aggregate's `eq`, monomorphized
    // against the recorded type-arg substitution — the operator path through
    // `binary_op_dispatch` + `method_call_substitution` into the one emitter.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        [derive(PartialEq)] struct Point { x: i32, y: i32 }
        fun main() {
            let a: Option<Point> = Some(Point { x = 1, y = 2 });
            let b: Option<Point> = Some(Point { x = 1, y = 2 });
            let c: Option<Point> = Some(Point { x = 9, y = 9 });
            if a == b { print("ab-eq") } else { print("ab-neq") }
            if a == c { print("ac-eq") } else { print("ac-neq") }
        }
        "#,
        "ab-eq\nac-neq\n",
    );
}

#[test]
fn single_level_container_from_json_roundtrip_runs() {
    // A single-level `List<i32>` decode: `from_json` calls `from_json_value`, whose
    // element type comes only from the enclosing `List<i32>` instantiation — the
    // inherited-substitution channel of `call_substitution`. Verifies it threads the
    // element type at runtime (the nested case is still open — see the ignored test).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::result::Result::{ self, Ok, Err };
        fun main() {
            let nums: Result<List<i32>, str> = List::from_json("[1,2,3]");
            match nums {
                Ok(let ns) => print(ns.to_json()),
                Err(let e) => print(e),
            }
        }
        "#,
        "[1,2,3]\n",
    );
}

#[test]
fn nested_container_from_json_roundtrip_runs() {
    // The `List<List<T>>` round-trip (the last row of the type-solver bug table).
    // The inner `List`'s element binding must thread through the *outer*
    // `from_json_value`: `resolve_dispatch` now binds an impl's generics from the
    // concrete receiver type (`bind_generics`) and emits a monomorphized instance,
    // so the nested `T::from_json_value` resolves at each level instead of lowering
    // to the abstract decoder (which yielded `[[undefined,...]]`). Triple nesting
    // exercises the recursion through two intermediate container instances.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::result::Result::{ self, Ok, Err };
        fun main() {
            let grid: Result<List<List<i32>>, str> = List::from_json("[[1,2],[3,4]]");
            match grid {
                Ok(let g) => print(g.to_json()),
                Err(let e) => print(e),
            }
            let deep: Result<List<List<List<i32>>>, str> = List::from_json("[[[1]],[[2,3]]]");
            match deep {
                Ok(let d) => print(d.to_json()),
                Err(let e) => print(e),
            }
        }
        "#,
        "[[1,2],[3,4]]\n[[[1]],[[2,3]]]\n",
    );
}

#[test]
fn mixed_nested_container_from_json_roundtrips() {
    // Mixed nesting through the same monomorphizing dispatch: `Option<List<i32>>`,
    // `List<Option<i32>>` (with a JSON `null` -> `None`), and a `List` of derived
    // structs — each inner decoder is monomorphized for its element via the impl's
    // generics bound from the concrete type.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        [derive(Json)] struct P { x: i32 }
        fun main() {
            let a: Result<Option<List<i32>>, str> = Option::from_json("[1,2,3]");
            match a {
                Ok(let av) => print(av.to_json()),
                Err(let e) => print(e),
            }
            let b: Result<List<Option<i32>>, str> = List::from_json("[1,null,3]");
            match b {
                Ok(let bv) => print(bv.to_json()),
                Err(let e) => print(e),
            }
            let c: Result<List<P>, str> = List::from_json("[{\"x\":1},{\"x\":2}]");
            match c {
                Ok(let cv) => print(cv.to_json()),
                Err(let e) => print(e),
            }
        }
        "#,
        "[1,2,3]\n[1,null,3]\n[{\"x\":1},{\"x\":2}]\n",
    );
}

// --- Method & argument passing (a historically fragile area) -----------------
//   Runtime checks, because the recurring failures here were silent miscompiles
//   (a dispatch resolving to `undefined`, a `&mut` lowering to broken JS) that a
//   compile-only test would pass. Covers: generic-bounded value dispatch
//   (roadmap Tier 1.2 / M2), a method routing its own generic into a nested call
//   (Bug C / B5), auto-deref through a view-returning call (B2), and `&`/`&mut`
//   argument passing (C5 / R8). Two open cases are pinned as ignored tests.

#[test]
fn generic_bounded_value_method_dispatch() {
    // A trait method called on a value of a generic-bounded type (`x: T: Display`)
    // dispatches to the concrete impl per monomorphization, at each call type —
    // not the abstract trait method (which would print `undefined`). Roadmap 1.2.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun describe<T: Display>(x: T): str { x.to_string() }
        fun main() {
            print(describe(42));
            print(describe("hi"));
        }
        "#,
        "42\nhi\n",
    );
}

#[test]
fn generic_bounded_value_operator_dispatch() {
    // `==` on a value of a generic-bounded type (`a: T: PartialEq`) re-resolves to
    // the concrete impl per monomorphization — for a primitive (native `===`) and
    // a `str`. Roadmap 1.2 / generic-equality.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::compare::PartialEq;
        fun same<T: PartialEq>(a: T, b: T): bool { a == b }
        fun main() {
            if same(3, 3) { print("y") } else { print("n") }
            if same(1, 2) { print("y") } else { print("n") }
            if same("a", "a") { print("y") } else { print("n") }
        }
        "#,
        "y\nn\ny\n",
    );
}

#[test]
fn method_routes_own_generic_to_nested_call() {
    // A method on a generic impl passes the impl's type parameter into a *nested*
    // generic call (`format(self.v)`), which must monomorphize for the concrete
    // element at each instantiation (Bug C / B5). The receiver's `T` reaches the
    // nested call through the field access + the inherited substitution.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::{ Display, format };
        struct Wrap<T: Display> { v: T }
        impl Wrap<type T: Display> {
            fun render(self): str { format(self.v) }
        }
        fun main() {
            print(Wrap { v = 7 }.render());
            print(Wrap { v = "hi" }.render());
        }
        "#,
        "7\nhi\n",
    );
}

#[test]
fn auto_deref_through_view_returning_call() {
    // Field and method access on a `borrows` view-returning call: `o.slot().n` and
    // `o.slot().get()` auto-deref the returned `&mut Inner` to reach the inner
    // struct's member (backlog B2). Locks the behavior in (a regression would make
    // the access miss the deref).
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Inner { n: i32 }
        impl Inner { fun get(self): i32 { self.n } }
        struct Outer { inner: Inner }
        impl Outer { fun slot(&mut self): &mut Inner borrows self { &mut self.inner } }
        fun main() {
            mut o = Outer { inner = Inner { n = 5 } };
            print(o.slot().n);
            print(o.slot().get());
        }
        "#,
        "5\n5\n",
    );
}

#[test]
fn mut_view_argument_mutates_through_call_chain() {
    // R8: a `&mut` argument is passed as an explicit `&mut place` and mutates the
    // caller's place; forwarding the view to a further call (`via` -> `bump`)
    // re-borrows it and keeps writing through. Runtime, so the `(base, key)`
    // place-write is exercised end to end.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun bump(x: &mut i32) { x += 1; }
        fun via(y: &mut i32) { bump(y); }
        fun main() {
            mut a = 0;
            bump(&mut a);
            print(a);
            via(&mut a);
            print(a);
        }
        "#,
        "1\n2\n",
    );
}

#[test]
fn mut_view_as_method_argument_mutates() {
    // A `&mut` parameter on a *non-`self`* method argument (`target`) mutates the
    // caller's place across repeated calls — distinct from the implicitly-borrowed
    // `self` receiver. C5 / R8.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Counter { n: i32 }
        impl Counter { fun add_into(self, target: &mut i32) { target += self.n; } }
        fun main() {
            mut total = 10;
            let c = Counter { n = 5 };
            c.add_into(&mut total);
            c.add_into(&mut total);
            print(total);
        }
        "#,
        "20\n",
    );
}

#[test]
fn mixed_value_view_and_own_arguments() {
    // One call mixing the three argument modes: a by-value `base` (read), a `&mut`
    // view `acc` (writes through to the caller), and an `own scratch` (a private
    // mutable copy the caller never sees). Each must keep its own semantics.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun combine(base: i32, acc: &mut i32, own scratch: i32): i32 {
            acc += base;
            scratch += 100;
            scratch
        }
        fun main() {
            mut a = 1;
            let s = combine(2, &mut a, 7);
            print(a); // 3 — written through the view
            print(s); // 107 — the own copy
        }
        "#,
        "3\n107\n",
    );
}

#[test]
fn reject_bare_value_to_shared_reference_param() {
    // R8 for a shared `&` parameter (the complement of `r8_reject_implicit_borrow`,
    // which covers `&mut`): a bare value place is rejected — pass `& <place>`.
    assert_fails(
        r#"
        fun read_it(x: &i32): i32 { *x }
        fun main() { let a = 5; let n = read_it(a); }
        "#,
    );
}

#[test]
fn generic_mut_view_parameter_writes_through() {
    // A generic `&mut T` view now behaves exactly like a concrete `&mut <T>`. For a
    // scalar pointee (`i32`, `f64`, `str`, `u32`) the read/write goes through the
    // `(base, key)` place-write, decided at monomorphization (the analyzer can't,
    // with `T` abstract — it emitted the aggregate `Object.assign`, leaving `a`
    // unchanged). For an aggregate pointee it stays the in-place copy.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun replace<T>(slot: &mut T, value: T) { slot = value; }
        fun main() {
            mut a = 1;
            replace(&mut a, 9);
            print(a);             // 9 — i32 written through
            mut f = 1.0;
            replace(&mut f, 2.5);
            print(f);             // 2.5 — f64
            mut s = "hi";
            replace(&mut s, "hey");
            print(s);             // hey — str
        }
        "#,
        "9\n2.5\nhey\n",
    );
}

#[test]
fn generic_mut_view_reads_and_swaps() {
    // Reading through a generic `&mut T` view (`*a`) and a `swap<T>` that both reads
    // and writes both views — the place-read `slot[0][slot[1]]` is also picked at
    // monomorphization for a scalar `T`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::display::Display;
        fun peek<T: Display>(slot: &mut T): str { (*slot).to_string() }
        fun swap<T>(a: &mut T, b: &mut T) { let t = *a; a = *b; b = t; }
        fun main() {
            mut a = 5;
            print(peek(&mut a));
            mut x = 1;
            mut y = 2;
            swap(&mut x, &mut y);
            print(x);
            print(y);
        }
        "#,
        "5\n2\n1\n",
    );
}

#[test]
fn generic_mut_view_of_a_generic_local() {
    // The caller side: a `&mut` of a *generic-typed local* (`mut local = x` where
    // `x: T`) forwarded to another generic view parameter. The local must be boxed
    // and the reference must build the `(base, key)` pair when `T` resolves to a
    // scalar here — decided in the transformer (`generic_referenced_roots`), since
    // the analyzer saw `T` abstract. An aggregate `T` stays unboxed. (Before the
    // fix the scalar case crashed: `slot[0][slot[1]]` on an unboxed value.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun inner<T>(slot: &mut T, value: T) { slot = value; }
        fun outer<T>(x: T, value: T): T { mut local = x; inner(&mut local, value); local }
        struct P { x: i32 }
        fun main() {
            print(outer(1, 9));                       // scalar local -> 9
            print(outer(P { x = 1 }, P { x = 9 }).x); // aggregate local -> 9
        }
        "#,
        "9\n9\n",
    );
}

#[test]
fn generic_mut_view_aggregate_pointee_copies_in_place() {
    // The aggregate side of the same parameter: a generic `&mut T` where `T`
    // resolves to a struct rebinds via the in-place copy (not a `(base, key)`
    // write), so the caller's value updates. Guards that the scalar fix didn't
    // change the aggregate path.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct P { x: i32 }
        fun replace<T>(slot: &mut T, value: T) { slot = value; }
        fun main() {
            mut p = P { x = 1 };
            replace(&mut p, P { x = 9 });
            print(p.x);
        }
        "#,
        "9\n",
    );
}

#[test]
fn bare_trait_value_method_call_is_rejected() {
    // Calling a method on a value typed as a *bare trait* (`let x: Display = 5`)
    // has no concrete type to dispatch to — vilan has no trait objects — and used
    // to silently lower to the empty abstract method (`undefined`). It is now a
    // clean compile error pointing at the generic-parameter / concrete-type fix
    // (backlog B4). The legitimate use of a bare-trait type is a *bound*
    // (`<T: Display>`), exercised by `generic_dispatch_to_extern_impl` et al.
    assert_fails(
        r#"
        import std::display::Display;
        fun main() {
            let x: Display = 5;
            let s = x.to_string();
        }
        "#,
    );
}

#[test]
fn trait_default_self_dispatch_still_runs() {
    // The flip side of the rejection: inside a trait *default* body a `Self`
    // receiver — including a chain through a `Self`-returning method and a
    // non-`self` `Self`-typed parameter — is legitimate and re-dispatches to the
    // concrete type at codegen. Guards that the bare-trait-value check doesn't
    // catch these.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Stepper {
            fun step(self): i32;
            fun twice(self): i32 { self.step() + self.step() }
            fun plus(self, other: Self): i32 { self.twice() + other.step() }
        }
        struct One {}
        impl One with Stepper { fun step(self): i32 { 1 } }
        fun main() {
            let a = One {};
            let b = One {};
            print((a).plus(b));
        }
        "#,
        "3\n",
    );
}

// --- B6: inferred-element list, closure-param field access -------------------

#[test]
fn inferred_list_closure_param_field_access() {
    // A `List::new()` + `push` list has its element type inferred from `push`,
    // which lands (via a `SlotUnification`) *after* a following `map`/`filter`
    // would resolve. A method on such a receiver now defers while a `push`/`run`
    // to fill the slot is still pending, so the closure parameter types against
    // the concrete element and a field access on it works — no `mut xs: List<P>`
    // annotation needed (backlog B6 / roadmap Tier 1.2). Parity with a literal
    // list.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct P { x: i32 }
        fun main() {
            mut xs = List::new();
            xs.push(P { x = 10 });
            xs.push(P { x = 20 });
            let big = xs.filter(|p| p.x > 15);
            print(big.len());
            let labels = xs.map(|p| p.x);
            print(labels.len());
        }
        "#,
        "1\n2\n",
    );
}

#[test]
fn inferred_list_never_pushed_still_resolves() {
    // The deferral must not strand a `List::new()` that is *never* pushed: with no
    // pending `SlotUnification`, its methods resolve immediately (element stays
    // `Unknown`/`any`) rather than deferring forever.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let xs = List::new();
            print(xs.len());
            let ys = xs.map(|n| 1);
            print(ys.len());
        }
        "#,
        "0\n0\n",
    );
}

#[test]
fn inline_match_on_method_result_field_access() {
    // An inline `match` on a method call that returns `Option<element>`
    // (`match xs.get(0) { Some(let p) => p.x }`) typed its capture `p` only on a
    // late pass; the field accessor on `p` was woken by that resolution but the
    // fixpoint's backstop branch could terminate *before* running the woken
    // constraint (its `wake_ready` result was ignored). The loop now continues
    // while a wake is pending, so the access resolves. Worked when bound to a
    // `let` first (an extra pass) — now works inline too, for `get` and `pop`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        struct P { x: i32 }
        fun main() {
            mut xs = List::new();
            xs.push(P { x = 42 });
            match xs.get(0) {
                Some(let p) => print(p.x),
                None => print(0),
            }
            match xs.pop() {
                Some(let p) => print(p.x),
                None => print(0),
            }
        }
        "#,
        "42\n42\n",
    );
}

#[test]
fn impl_binder_inherits_struct_bound() {
    // `impl Wrapper<type T>` omits the bound the struct declares (`struct
    // Wrapper<T: Greeter>`). The impl can only ever apply to a `Wrapper`, whose
    // existence already requires `T: Greeter`, so the binder *inherits* that
    // bound — and a trait method call on the `T`-typed field resolves, exactly as
    // if `impl Wrapper<type T: Greeter>` had been written.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        struct Wrapper<T: Greeter> { inner: T }
        impl Wrapper<type T> {
            fun run(self): str { (self.inner).greet() }
        }
        fun main() {
            print(Wrapper { inner = Hello { name = "x" } }.run());
        }
        "#,
        "hi x\n",
    );
}

#[test]
fn impl_binder_inherits_multiple_bounds() {
    // A multi-bound declared parameter (`T: A + B`) keeps *both* bounds when
    // inherited: the extra bounds hang off the same constraint id the binder
    // reuses, so methods from either trait resolve on the field.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Named { fun name(self): str; }
        trait Aged { fun age(self): i32; }
        struct Person { n: str, a: i32 }
        impl Person with Named { fun name(self): str { self.n } }
        impl Person with Aged { fun age(self): i32 { self.a } }
        struct Card<T: Named + Aged> { who: T }
        impl Card<type T> {
            fun render(self): str { (self.who).name() }
            fun years(self): i32 { (self.who).age() }
        }
        fun main() {
            let card = Card { who = Person { n = "Ada", a = 36 } };
            print(card.render());
            print(card.years());
        }
        "#,
        "Ada\n36\n",
    );
}

#[test]
fn impl_binder_inherits_per_position_with_multiple_params() {
    // Two declared parameters with *different* bounds — the inherited constraint
    // is matched to the binder by position, not conflated.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Named { fun name(self): str; }
        trait Aged { fun age(self): i32; }
        struct Tag { n: str }
        impl Tag with Named { fun name(self): str { self.n } }
        struct Years { y: i32 }
        impl Years with Aged { fun age(self): i32 { self.y } }
        struct Pair<A: Named, B: Aged> { left: A, right: B }
        impl Pair<type A, type B> {
            fun label(self): str { (self.left).name() }
            fun count(self): i32 { (self.right).age() }
        }
        fun main() {
            let pair = Pair { left = Tag { n = "Ada" }, right = Years { y = 7 } };
            print(pair.label());
            print(pair.count());
        }
        "#,
        "Ada\n7\n",
    );
}

#[test]
fn impl_binder_mixes_explicit_and_inherited_bounds() {
    // One binder restates its bound explicitly, the other infers it — both must
    // resolve. The explicit one already worked; this pins that adding inheritance
    // for the other did not break the mixed form.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Named { fun name(self): str; }
        trait Aged { fun age(self): i32; }
        struct Tag { n: str }
        impl Tag with Named { fun name(self): str { self.n } }
        struct Years { y: i32 }
        impl Years with Aged { fun age(self): i32 { self.y } }
        struct Pair<A: Named, B: Aged> { left: A, right: B }
        impl Pair<type A: Named, type B> {
            fun label(self): str { (self.left).name() }
            fun count(self): i32 { (self.right).age() }
        }
        fun main() {
            let pair = Pair { left = Tag { n = "Ada" }, right = Years { y = 7 } };
            print(pair.label());
            print(pair.count());
        }
        "#,
        "Ada\n7\n",
    );
}

#[test]
fn impl_binder_inherits_enum_bound() {
    // Inheritance works for an enum subject too, not just structs.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        enum Box<T: Greeter> { Full(T), Empty }
        impl Box<type T> {
            fun shout(self): str {
                match self {
                    Box::Full(let inner) => inner.greet(),
                    Box::Empty => "empty",
                }
            }
        }
        fun main() {
            print(Box::Full(Hello { name = "x" }).shout());
        }
        "#,
        "hi x\n",
    );
}

#[test]
fn impl_binder_without_a_declared_bound_stays_unconstrained() {
    // Inheritance only borrows a bound the subject actually declares. An
    // unconstrained `struct Plain<T>` confers nothing, so a trait method call on
    // the `T`-typed field must still be rejected — the fix must not invent bounds.
    assert_fails(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Plain<T> { inner: T }
        impl Plain<type T> {
            fun run(self): str { (self.inner).greet() }
        }
        fun main() {
            print(0);
        }
        "#,
    );
}

#[test]
fn impl_binder_inherits_bound_from_a_later_declared_struct() {
    // The same program as `impl_binder_inherits_struct_bound`, but with the
    // struct declared *after* the impl. The walk registers the binder
    // unbounded and retrofits the struct's bound just before solving, once
    // every declaration exists — declaration order no longer matters.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        impl Wrapper<type T> {
            fun run(self): str { (self.inner).greet() }
        }
        struct Wrapper<T: Greeter> { inner: T }
        fun main() {
            print(Wrapper { inner = Hello { name = "x" } }.run());
        }
        "#,
        "hi x\n",
    );
}

#[test]
fn impl_binder_inherits_multiple_bounds_from_a_later_declared_struct() {
    // The deferred retrofit carries MULTI-bounds too: `T: Greeter + Counter`
    // declared after the impl, methods from both traits resolving.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        trait Counter { fun count(self): i32; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        impl Hello with Counter { fun count(self): i32 { self.name.len() } }
        impl Wrapper<type T> {
            fun describe(self): str {
                (self.inner).greet()
            }
            fun tally(self): i32 {
                (self.inner).count()
            }
        }
        struct Wrapper<T: Greeter + Counter> { inner: T }
        fun main() {
            let wrapped = Wrapper { inner = Hello { name = "xy" } };
            print(wrapped.describe());
            print(wrapped.tally());
        }
        "#,
        "hi xy\n2\n",
    );
}

#[test]
fn impl_binder_inherits_bound_from_a_later_declared_enum() {
    // Enum subjects inherit through the same deferred path as structs.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        impl Holder<type T> {
            fun open(self): str {
                match self {
                    Holder::Item(let inner) => inner.greet(),
                }
            }
        }
        enum Holder<T: Greeter> {
            Item(T),
        }
        fun main() {
            print(Holder::Item(Hello { name = "e" }).open());
        }
        "#,
        "hi e\n",
    );
}

#[test]
fn a_boundless_trait_argument_binder_inherits_the_traits_bound() {
    // `with DescribeInto<type S>` omits the bound; the TRAIT declares
    // `S: Sink`, so the binder inherits it — the subject-binder rule applied
    // to the with-clause.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        trait Sink { fun put(self, value: i32); }
        struct Collector { total: Shared<i32> }
        impl Collector with Sink {
            fun put(self, value: i32) {
                self.total.write() = self.total.read() + value;
            }
        }
        trait DescribeInto<S: Sink> {
            fun describe_into(self, sink: S);
        }
        struct Point { x: i32 }
        impl Point with DescribeInto<type S> {
            fun describe_into(self, sink: S) {
                sink.put(self.x);
            }
        }
        fun main() {
            let point = Point { x = 5 };
            let collector = Collector { total = Shared::new(0) };
            point.describe_into(collector);
            print(collector.total.read());
        }
        "#,
        "5\n",
    );
}

#[test]
fn subject_and_trait_argument_binders_compose_on_one_impl() {
    // `impl Box<type T> with DescribeInto<type S: Sink>` — the receiver binds
    // T, the argument binds S, one call resolves both.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        trait Sink { fun put(self, value: i32); }
        struct Collector { total: Shared<i32> }
        impl Collector with Sink {
            fun put(self, value: i32) {
                self.total.write() = self.total.read() + value;
            }
        }
        trait Sized2 { fun size(self): i32; }
        struct Pair { a: i32, b: i32 }
        impl Pair with Sized2 { fun size(self): i32 { 2 } }
        trait DescribeInto<S> {
            fun describe_into(self, sink: S);
        }
        struct Box2<T: Sized2> { inner: T }
        impl Box2<type T> with DescribeInto<type S: Sink> {
            fun describe_into(self, sink: S) {
                sink.put((self.inner).size());
            }
        }
        fun main() {
            let boxed = Box2 { inner = Pair { a = 1, b = 2 } };
            let collector = Collector { total = Shared::new(40) };
            boxed.describe_into(collector);
            print(collector.total.read());
        }
        "#,
        "42\n",
    );
}

#[test]
fn async_trait_method_through_generic_bound_auto_awaits() {
    // An inferred-async trait method (`fetch` awaits) dispatched through a generic
    // bound (`self.inner: T`, `T: Fetcher`). The call graph used to mis-resolve the
    // dispatch to the trait's *signature* (a bodyless method, never async — the
    // dispatch is keyed by the call id, which `resolve_target` only consulted for
    // `OnType`), so the enclosing `run` was left non-`async` while the transformer,
    // resolving the concrete async impl, still inserted the `await` — `await` inside
    // a non-async function, invalid JS that crashed at load. Async-ness now
    // propagates through the dispatch's candidate impls, so `run` (and its caller
    // `main`) are async and the program runs.
    assert_compiles_and_runs(
        r#"
        import std::print;
        [extern("Promise.resolve")]
        async external fun resolved(value: str): str;
        trait Fetcher { fun fetch(self): str; }
        struct Remote { tag: str }
        impl Remote with Fetcher {
            fun fetch(self): str { await resolved(self.tag) }
        }
        struct Wrapper<T: Fetcher> { inner: T }
        impl Wrapper<type T> {
            fun run(self): str { (self.inner).fetch() }
        }
        fun main() {
            print(Wrapper { inner = Remote { tag = "hi" } }.run());
        }
        "#,
        "hi\n",
    );
}

#[test]
fn async_impl_through_generic_bound_propagates_transitively() {
    // The impl method is async *transitively* — it doesn't `await` itself, it calls
    // an async function — so its async-ness is only settled by the fixpoint. The
    // dispatch must pick that up after propagation, not just from a direct `await`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        [extern("Promise.resolve")]
        async external fun resolved(value: str): str;
        fun load(tag: str): str { await resolved(tag) }
        trait Fetcher { fun fetch(self): str; }
        struct Remote { tag: str }
        impl Remote with Fetcher {
            fun fetch(self): str { load(self.tag) }
        }
        struct Wrapper<T: Fetcher> { inner: T }
        impl Wrapper<type T> {
            fun run(self): str { (self.inner).fetch() }
        }
        fun main() {
            print(Wrapper { inner = Remote { tag = "hey" } }.run());
        }
        "#,
        "hey\n",
    );
}

#[test]
fn mixed_async_and_sync_impls_through_generic_bound_both_run() {
    // Two impls of one trait — one async, one sync — both reached through the bound.
    // The dispatch is conservatively async (some candidate impl awaits), so even the
    // sync instance compiles to an async function; awaiting its non-promise result is
    // a JS no-op, and both instantiations run correctly.
    assert_compiles_and_runs(
        r#"
        import std::print;
        [extern("Promise.resolve")]
        async external fun resolved(value: str): str;
        trait Fetcher { fun fetch(self): str; }
        struct Remote { tag: str }
        impl Remote with Fetcher { fun fetch(self): str { await resolved(self.tag) } }
        struct Local { tag: str }
        impl Local with Fetcher { fun fetch(self): str { self.tag } }
        struct Wrapper<T: Fetcher> { inner: T }
        impl Wrapper<type T> { fun run(self): str { (self.inner).fetch() } }
        fun main() {
            print(Wrapper { inner = Remote { tag = "remote" } }.run());
            print(Wrapper { inner = Local { tag = "local" } }.run());
        }
        "#,
        "remote\nlocal\n",
    );
}

#[test]
fn async_trait_default_body_through_generic_bound_auto_awaits() {
    // The async method is the trait's *default* body (the impl doesn't override it),
    // dispatched through the bound. The candidate is the trait default, not an impl
    // member — so candidate resolution must consider the trait's own declarations.
    assert_compiles_and_runs(
        r#"
        import std::print;
        [extern("Promise.resolve")]
        async external fun resolved(value: str): str;
        trait Greeter {
            fun name(self): str;
            fun greet(self): str { await resolved(self.name()) }
        }
        struct Hello { who: str }
        impl Hello with Greeter { fun name(self): str { self.who } }
        struct Wrapper<T: Greeter> { inner: T }
        impl Wrapper<type T> { fun run(self): str { (self.inner).greet() } }
        fun main() {
            print(Wrapper { inner = Hello { who = "ada" } }.run());
        }
        "#,
        "ada\n",
    );
}

#[test]
fn sync_method_through_generic_bound_is_not_made_async() {
    // The precision guard: a generic dispatch whose trait has *no* async impl must
    // not become async. Asserted structurally — the emitted JS has no `async`/`await`
    // anywhere — so an over-eager propagation (e.g. matching an async method of the
    // same name in an unrelated trait) would fail here, not just slip past `runs`.
    let js = compile(
        r#"
        import std::print;
        trait Greeter { fun greet(self): str; }
        struct Hello { name: str }
        impl Hello with Greeter { fun greet(self): str { "hi " + self.name } }
        struct Wrapper<T: Greeter> { inner: T }
        impl Wrapper<type T> { fun run(self): str { (self.inner).greet() } }
        fun main() { print(Wrapper { inner = Hello { name = "x" } }.run()); }
        "#,
    )
    .expect("compiles");
    assert!(
        !js.contains("async") && !js.contains("await"),
        "a purely-sync generic dispatch must not be made async:\n{js}"
    );
}

#[test]
fn generic_element_serialized_in_a_closure_through_a_bounded_method() {
    // A closure passed to a generic method (`feed.each(|T| ..)`) on a parameterized-bound
    // receiver (`F: Feed<T>`), serializing the element `T` inside the closure. Two gaps
    // used to break this: the closure parameter lost its `T: Json` bound — a compile error
    // ("cannot call method 'to_json' on T") — and `T`, which appears *only* in the bound
    // `F: Feed<T>`, was never derived from the concrete `Nums: Feed<i32>` at the call site,
    // so `to_json` monomorphized to the empty abstract method and yielded `undefined`.
    // Both are fixed (the parameterized-bound substitution in the `Type::Generic` method
    // arm, and the derive-from-bound step in `resolve_call_subject`).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::Json;
        trait Feed<T> { fun each(self, observer: |T| void); }
        struct Nums {}
        impl Nums with Feed<i32> {
            fun each(self, observer: |i32| void) { observer(7); observer(9); }
        }
        fun pump<T: Json, F: Feed<T>>(feed: F, out: |str| void) {
            feed.each(|value| out(value.to_json()))
        }
        fun main() { pump(Nums {}, |s| print(s)); }
        "#,
        "7\n9\n",
    );
}

#[test]
fn generic_source_element_serialized_in_a_sub_closure() {
    // The reactive shape the fix unblocks: forward a `Source<T>`'s values, serialized
    // inside the `sub` closure, where `T` appears only in the `S: Source<T>` bound.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::Json;
        import std::reactive::{ Source, Signal, Subscription };
        fun forward<T: Json, S: Source<T>>(source: S, out: |str| void): Subscription {
            source.sub(|value| out(value.to_json()))
        }
        fun main() {
            let s = Signal::new(7);
            let _ = forward(s, |json| print(json));
            s.set(9);
        }
        "#,
        "7\n9\n",
    );
}

#[test]
fn generic_element_type_derived_from_a_parameterized_bound() {
    // A struct payload `T` (not a scalar) crosses the same paths: the element flows
    // through the closure and a `[derive(Json)]` `to_json`, and `T` is derived from the
    // bound. Pins that the fix threads a concrete *aggregate* type, not just `i32`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::Json;
        trait Feed<T> { fun each(self, observer: |T| void); }
        [derive(Json)]
        struct Point { x: i32, y: i32 }
        struct Points {}
        impl Points with Feed<Point> {
            fun each(self, observer: |Point| void) { observer(Point { x = 1, y = 2 }); }
        }
        fun dump<T: Json, F: Feed<T>>(feed: F) {
            feed.each(|point| print(point.to_json()))
        }
        fun main() { dump(Points {}); }
        "#,
        "{\"x\":1,\"y\":2}\n",
    );
}

#[test]
fn generic_bound_derivation_through_a_method_call() {
    // The same fix on the *method* path (`bind_method_own_generics`): a struct method
    // `<T: Json, S: Source<T>>` whose `T` appears only in the bound, serializing the
    // element in a `sub` closure. Called as `sink.forward(signal, ..)`, `T` is derived
    // from the concrete signal's `Source` impl — the shape `examples/rpc`'s `expose` uses.
    // The source argument is *inferred* (`let s = Signal::new(7)`, no annotation), so its
    // type lands only after the call is first seen; `resolve_method_call` defers while the
    // bound-owner is unresolved and re-derives on a later pass (mirroring the free-function
    // path), so the inferred case works too.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::Json;
        import std::reactive::{ Source, Signal, Subscription };
        struct Sink {}
        impl Sink {
            fun forward<T: Json, S: Source<T>>(self, source: S, out: |str| void): Subscription {
                source.sub(|value| out(value.to_json()))
            }
        }
        fun main() {
            let s = Signal::new(7);
            let _ = Sink {}.forward(s, |json| print(json));
            s.set(9);
        }
        "#,
        "7\n9\n",
    );
}

#[test]
fn owner_take_disposes_a_mapped_and_a_root_subscription() {
    // Pins `vilan/test/reactive.js`'s reachable miscompilation as *observable* runtime
    // behaviour — the golden alone proved an unreliable gate (it drifted stale), so an
    // executed assertion is the stronger pin. `Owner::take<T: Disposable>` (an *unparameterized*
    // bound) stores `|| item.dispose()` in a cleanup closure for later. Two `take` sites are
    // needed to trigger it: `take(mapped.sub(..))` where `mapped = root.map(..)` resolves its
    // element *late* (through `map`'s generic), and `take(root.sub(..))` which resolves early.
    // The pre-fix analyzer bound the *mapped* site's `T` before its argument landed and
    // monomorphized that `take` to the empty abstract `Disposable::dispose` (the *root* site
    // stayed concrete), so disposing the owner never removed the mapped subscriber and it
    // leaked. reactive.js hides it (its owner is never disposed); here we dispose the owner,
    // so a leaked subscription keeps firing: pre-fix this printed a trailing `a=10`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, Owner };
        fun main() {
            let owner = Owner::new();
            let count = Signal::new(0);
            let doubled = count.map(|n| n * 2);
            owner.take(doubled.sub(|n| print(i"a={n}")));   // mapped/late site
            owner.take(count.sub(|n| print(i"b={n}")));     // root/early site
            count.set(1);       // a=2, b=1
            owner.dispose();    // the *real* dispose must remove BOTH subscribers
            count.set(5);       // silent iff both disposed; leaks "a=10" if the mapped take went abstract
        }
        "#,
        "a=0\nb=0\na=2\nb=1\n",
    );
}

// === Reactive batching (proposal/reactive-batching.md) ============================

#[test]
fn lone_set_notifies_synchronously() {
    // Outside a `batch`, `set` notifies inline (eager) — a lone set fires its observers
    // before the next statement, exactly as before batching existed.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal };
        fun main() {
            let a = Signal::new(0);
            let _ = a.sub(|v| print(i"a={v}"));   // immediate: a=0
            a.set(1);                             // eager -> a=1 now
            print("after");
            a.set(2);                             // a=2
        }
        "#,
        "a=0\na=1\nafter\na=2\n",
    );
}

#[test]
fn batch_commits_value_immediately_but_defers_notification() {
    // Inside a `batch`, a root's value is committed at once (`s.get()` is fresh), but a
    // *derived* value recomputes only at the flush boundary — so mid-batch it is stale,
    // then settles. Pins the "defer notification, not the value" divergence.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, batch };
        fun main() {
            let s = Signal::new(0);
            let doubled = s.map(|n| n * 2);
            batch(|| {
                s.set(5);
                print(i"in-batch s={s.get()} doubled={doubled.get()}");   // s=5 fresh, doubled=0 stale
            });
            print(i"after doubled={doubled.get()}");                      // 10 (settled at flush)
        }
        "#,
        "in-batch s=5 doubled=0\nafter doubled=10\n",
    );
}

#[test]
fn batch_coalesces_a_multi_input_observer() {
    // A node fed by two inputs (hand-rolled `d = a + b`, recomputed when either changes)
    // recomputes with both inputs settled inside a `batch` — glitch-free. The `d` observer
    // fires once (11 -> 22), with no intermediate (a-new, b-old) reading.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, batch };
        fun main() {
            let a = Signal::new(1);
            let b = Signal::new(10);
            let d = Signal::new(a.get() + b.get());
            let _ = a.sub(|_| { d.set(a.get() + b.get()); });
            let _ = b.sub(|_| { d.set(a.get() + b.get()); });
            let _ = d.sub(|v| print(i"d={v}"));   // immediate: d=11
            batch(|| {
                a.set(2);
                b.set(20);
            });                                    // coalesced -> d=22 once
        }
        "#,
        "d=11\nd=22\n",
    );
}

#[test]
fn without_a_batch_a_multi_input_observer_glitches() {
    // The same graph without a `batch`: each eager `set` fires the observer, so it sees the
    // intermediate (a=2, b=10) state — the glitch (`d=12`) the batch above elides. Pins that
    // batching is what removes it (the opt-in boundary).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal };
        fun main() {
            let a = Signal::new(1);
            let b = Signal::new(10);
            let d = Signal::new(a.get() + b.get());
            let _ = a.sub(|_| { d.set(a.get() + b.get()); });
            let _ = b.sub(|_| { d.set(a.get() + b.get()); });
            let _ = d.sub(|v| print(i"d={v}"));   // d=11
            a.set(2);                              // d=12 (glitch: b still 10)
            b.set(20);                             // d=22
        }
        "#,
        "d=11\nd=12\nd=22\n",
    );
}

#[test]
fn batch_cascade_settles_in_one_flush() {
    // A linear cascade `a -> map -> map -> observer` settles to its final value in one flush
    // when the root is set inside a `batch` — the observer fires once with the fully-cascaded
    // value (20 -> 60), never an intermediate.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, batch };
        fun main() {
            let a = Signal::new(1);
            let b = a.map(|n| n + 1);      // b = a + 1
            let c = b.map(|n| n * 10);     // c = b * 10
            let _ = c.sub(|v| print(i"c={v}"));   // immediate: c=20
            batch(|| { a.set(5); });               // a=5 -> b=6 -> c=60
        }
        "#,
        "c=20\nc=60\n",
    );
}

#[test]
fn nested_batches_flush_at_the_outer_boundary() {
    // An inner `batch` does not flush (depth stays > 0) — notifications wait for the outermost
    // boundary and coalesce to the final value. `mid` prints before any observer fires.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, batch };
        fun main() {
            let a = Signal::new(0);
            let _ = a.sub(|v| print(i"a={v}"));   // immediate: a=0
            batch(|| {
                a.set(1);
                batch(|| {
                    a.set(2);
                });
                print("mid");        // inner batch did NOT flush -> no a-notify yet
                a.set(3);
            });                       // outer flush -> a=3 (once, final)
        }
        "#,
        "a=0\nmid\na=3\n",
    );
}

#[test]
fn dispose_in_a_batch_scrubs_the_pending_notify() {
    // A subscription disposed *after* its source was set in the same `batch` must not fire:
    // `dispose` scrubs the pending queue, so the enqueued notify is removed before the flush.
    // Pins the "disposed is silent" resolution (no `tick 1` from the batch, no `tick 2` after).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, batch };
        fun main() {
            let counter = Signal::new(0);
            let sub = counter.sub(|n| print(i"tick {n}"));   // immediate: tick 0
            batch(|| {
                counter.set(1);     // enqueues `sub`'s notify
                sub.dispose();      // scrubs it from the pending queue
            });                      // flush -> nothing
            print("done");
            counter.set(2);          // sub disposed -> silent
        }
        "#,
        "tick 0\ndone\n",
    );
}

// --- `Signal::update`: in-place mutation (A18, proposal/signal-update.md) ---
// The closure receives a writable view of the STORED value and the runtime
// notifies once, unconditionally, after it returns. `sync` is the `await`
// fence; the view obeys rule 3 like any other.

#[test]
fn update_mutates_a_list_in_place_and_a_later_get_sees_it() {
    // A18's headline case: a push through the view, no copy-transform-return.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        fun main() {
            let todos = Signal::new([1, 2]);
            todos.update(|&mut list| { list.push(5); });
            print(todos.get().len());
        }
        "#,
        "3\n",
    );
}

#[test]
fn update_generalizes_over_every_collection() {
    // The point of the design: one method serves `Map` and `Set` (and a user
    // struct) exactly as it serves `List` — no per-container twin.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::map::Map;
        import std::set::Set;
        import std::reactive::Signal;
        struct Counter { hits: i32 }
        fun main() {
            let scores: Signal<Map<str, i32>> = Signal::new(Map::new());
            scores.update(|&mut m| { m.insert("a", 1); m.insert("b", 2); });
            print(scores.get().len());

            let tags: Signal<Set<i32>> = Signal::new(Set::new());
            tags.update(|&mut s| { s.insert(7); });
            print(tags.get().len());

            let counter = Signal::new(Counter { hits = 0 });
            counter.update(|&mut c| { c.hits = 9; });
            print(counter.get().hits);
        }
        "#,
        "2\n1\n9\n",
    );
}

#[test]
fn update_over_a_scalar_signal_writes_through_the_view() {
    // The scalar leg. `Shared::write()` over a scalar pointee lowers to its
    // `(base, key)` pair, so the closure's `&mut i32` writes the cell rather
    // than a stray number (which crashed at runtime before the fix).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        fun main() {
            let count = Signal::new(1);
            count.update(|&mut n| { n = *n + 10; });
            print(count.get());
        }
        "#,
        "11\n",
    );
}

#[test]
fn update_notifies_exactly_once_per_call() {
    // Unconditional and single: two `update`s produce two notifications, one
    // each, after the closure returns — never per mutation inside it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, Owner };
        fun main() {
            let owner = Owner::new();
            let xs = Signal::new([0]);
            owner.take(xs.sub(|list| print(i"len {list.len()}")));   // immediate: len 1
            xs.update(|&mut list| { list.push(1); list.push(2); });  // ONE notify, len 3
            xs.update(|&mut list| { list.push(3); });                // len 4
        }
        "#,
        "len 1\nlen 3\nlen 4\n",
    );
}

#[test]
fn update_notifies_even_when_the_closure_writes_nothing() {
    // Unconditional, deliberately: `update` matches `set`, which never
    // compares either. A no-op `mutate` still publishes.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, Owner };
        fun main() {
            let owner = Owner::new();
            let xs = Signal::new([0]);
            owner.take(xs.sub(|list| print(i"len {list.len()}")));
            xs.update(|&mut list| { });
        }
        "#,
        "len 1\nlen 1\n",
    );
}

#[test]
fn update_coalesces_under_batch() {
    // `update` shares `set`'s notify half verbatim, so turn deferral and dedup
    // are inherited: two updates inside one `batch` settle as ONE notification
    // at the boundary, carrying the final value.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::{ Signal, Owner, batch };
        fun main() {
            let owner = Owner::new();
            let xs = Signal::new([0]);
            owner.take(xs.sub(|list| print(i"len {list.len()}")));   // immediate: len 1
            batch(|| {
                xs.update(|&mut list| { list.push(1); });
                xs.update(|&mut list| { list.push(2); });
                print("inside");
            });
        }
        "#,
        "len 1\ninside\nlen 3\n",
    );
}

#[test]
fn a_reentrant_get_inside_update_sees_the_in_progress_value() {
    // `mutate` writes STORAGE, so a read from inside the closure observes the
    // mutations made so far — uniformly for an aggregate and for a scalar (a
    // scalar view writes the same `(cell, "v")` slot `get` reads).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        fun main() {
            let xs = Signal::new([1, 2]);
            xs.update(|&mut list| {
                list.push(3);
                print(i"aggregate {xs.get().len()}");
            });
            let n = Signal::new(1);
            n.update(|&mut value| {
                value = *value + 10;
                print(i"scalar {n.get()}");
            });
        }
        "#,
        "aggregate 3\nscalar 11\n",
    );
}

#[test]
fn update_refuses_a_view_escaping_its_closure() {
    // Rule 3 holds for the callback's parameter exactly as for any other view:
    // storing it in a struct field is the ordinary escape error.
    assert_fails_with(
        r#"
        import std::reactive::Signal;
        struct Hold { slot: &mut List<i32> }
        fun main() {
            let xs = Signal::new([1]);
            xs.update(|&mut list| { let held = Hold { slot = list }; });
        }
        "#,
        "a view cannot escape its scope",
    );
}

#[test]
fn set_with_still_copies_and_transforms() {
    // `update` does not replace `set_with`: the transform form is unchanged,
    // and its `mut` copy is still a copy (the source list is untouched).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        fun main() {
            mut seed = [1, 2];
            let numbers = Signal::new(seed);
            numbers.set_with(|mut list| {
                list.push(5);
                list
            });
            print(numbers.get().len());
            print(seed.len());
            let count = Signal::new(1);
            count.set_with(|n| n + 4);
            print(count.get());
        }
        "#,
        "3\n2\n5\n",
    );
}

// --- the language mechanism `update` needed: a closure literal's parameters
// --- take the full parameter grammar (conventions included), not just `mut`.

#[test]
fn a_closure_parameter_takes_the_mut_view_convention() {
    // `|&mut x|` is the prefix spelling; the callee mutates the CALLER's value.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun apply(target: &mut List<i32>, mutate: sync |&mut List<i32>| void) {
            mutate(target);
        }
        fun main() {
            mut data = [1, 2];
            apply(&mut data, |&mut list| { list.push(5); });
            print(data.len());
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_closure_parameter_takes_the_view_convention_from_its_type() {
    // The type-position spelling, inferred the same way a `fun` parameter's is.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun apply(target: &mut List<i32>, mutate: sync |&mut List<i32>| void) {
            mutate(target);
        }
        fun main() {
            mut data = [1, 2];
            apply(&mut data, |list: &mut List<i32>| { list.push(5); });
            print(data.len());
        }
        "#,
        "3\n",
    );
}

#[test]
fn a_bare_closure_parameter_still_refuses_mutation() {
    // The asymmetry closed only the view spelling: an unannotated parameter is
    // still by value, and mutating it still steers to `mut` or `&mut`.
    assert_fails_with(
        r#"
        fun apply(seed: List<i32>, mutate: sync |List<i32>| void) { mutate(seed); }
        fun main() {
            apply([1, 2], |list| { list.push(5); });
        }
        "#,
        "cannot mutate immutable 'list'",
    );
}

#[test]
fn a_closure_parameter_refuses_mut_combined_with_a_convention() {
    // `mut` and a convention stay non-composable in closure position too
    // (proposal/mut-parameters.md §2), now that both are spellable there.
    assert_fails_with(
        r#"
        fun apply(target: &mut List<i32>, mutate: sync |&mut List<i32>| void) {
            mutate(target);
        }
        fun main() {
            mut data = [1];
            apply(&mut data, |&mut mut list| { list.push(5); });
        }
        "#,
        "it cannot combine with `own` or a view",
    );
}

#[test]
fn a_scalar_shared_write_passes_as_a_mut_view() {
    // The pre-existing bug `update`'s scalar leg exposed, pinned on its own
    // terms — no `Signal` involved. `Shared::write()` over a scalar handed the
    // callee the VALUE, and `slot[0][slot[1]]` on a number crashed at runtime.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        fun replace<T>(slot: &mut T, value: T) { slot = value; }
        fun main() {
            let cell: Shared<i32> = Shared::new(1);
            replace(cell.write(), 9);
            print(cell.read());
            let listed: Shared<List<i32>> = Shared::new([1, 2]);
            replace(listed.write(), [3, 4, 5]);
            print(listed.read().len());
        }
        "#,
        "9\n3\n",
    );
}

#[test]
fn a_shared_write_assignment_is_unchanged_for_both_pointees() {
    // The assign-through path keeps taking the `v` slot, so the pair lowering
    // above cannot regress `cell.write() = x` for a scalar or an aggregate.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        fun main() {
            let flag: Shared<bool> = Shared::new(false);
            flag.write() = true;
            print(flag.read());
            let listed: Shared<List<i32>> = Shared::new([1]);
            listed.write().push(2);
            listed.write() = [7, 8, 9];
            print(listed.read().len());
        }
        "#,
        "true\n3\n",
    );
}

#[test]
fn a_sync_void_parameter_refuses_an_async_closure() {
    // B61: the `sync` marker is the whole contract — what the callback returns
    // decides ADAPTATION, not whether the contract binds. `sync || void` used
    // to accept an awaiting closure that the identical `sync || i32` refused.
    assert_fails_with(
        r#"
        import std::time::sleep;
        fun run_now(body: sync || void) { body(); }
        fun main() {
            run_now(|| { sleep(1); });
        }
        "#,
        "requires a synchronous closure (`sync`)",
    );
}

#[test]
fn a_sync_void_parameter_still_takes_a_synchronous_closure() {
    // The other half of B61: the marker refuses awaiting callbacks, not every
    // callback. A void `sync` parameter is the ordinary case.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun run_now(body: sync || void) { body(); }
        fun main() {
            run_now(|| { print(1); });
        }
        "#,
        "1\n",
    );
}

#[test]
fn a_sync_void_parameter_refuses_a_forwarded_async_closure() {
    // B61 reaches the transitive path too: the closure passed to `run_now` is
    // async only for the instance of `forward` whose `f` awaits, which is the
    // per-instance check — and it gated on the same adaptation shape, so a
    // void `sync` parameter escaped it as well. The value-returning twin is
    // `a_forwarded_async_closure_into_a_sync_contract_is_refused`.
    assert_fails_noting(
        r#"
        import std::time::sleep;
        fun run_now(body: sync || void) { body(); }
        fun forward(f: || i32) { run_now(|| { f(); }); }
        fun main() {
            forward(|| { sleep(1); 2 });
        }
        "#,
        "passes an async closure that reaches `body`, which requires a synchronous closure (`sync`)",
        "run_now(|| { f(); })",
        "forwarded into the `sync` parameter `body` here",
    );
}

#[test]
fn signal_update_refuses_an_awaiting_closure() {
    // A18 declared `Signal::update`'s `mutate` parameter `sync` because a view
    // may not be live across an `await` (spec §6.6) — a correct declaration
    // that did not bite until B61. It bites now.
    assert_fails_with(
        r#"
        import std::reactive::Signal;
        import std::time::sleep;
        fun main() {
            let items: Signal<List<i32>> = Signal::new([1]);
            items.update(|&mut list| { sleep(1); list.push(2); });
        }
        "#,
        "requires a synchronous closure (`sync`)",
    );
}

// === RPC foundation: the generic `call` helper (examples/rpc §4.1) ================

#[test]
fn generic_call_over_a_bounded_transport_decodes() {
    // The RPC foundation's `call<T, Tx: Transport>` shape: a generic function that calls a trait
    // method on a bound-generic transport, `await`s it, and decodes the reply as a generic
    // `T: FromJson` — invoked from a *generic* client that passes its own `Tx`-typed field. Pins
    // that this whole generic-through-generic path monomorphizes (the example isn't auto-run).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::{ Json, FromJson };
        import std::result::Result::{ self, Ok, Err };
        import std::promise::Promise;
        trait Wire { fun send(self, msg: str): Promise<str>; }
        struct Echo {}
        impl Echo with Wire {
            fun send(self, msg: str): Promise<str> { async { msg } }   // echoes the request
        }
        [derive(Json)]
        struct Pt { x: i32 }
        fun fetch<T: FromJson, Tx: Wire>(transport: Tx, msg: str): Result<T, str> {
            let reply = await transport.send(msg);
            T::from_json(reply)                           // decode the generic T from the reply
        }
        struct Client<Tx: Wire> { transport: Tx }
        impl Client<type Tx> {
            fun get(self): Result<Pt, str> {
                fetch(self.transport, "{\"x\":42}")        // T=Pt inferred from the return type
            }
        }
        fun main() {
            let c = Client { transport = Echo {} };
            match c.get() {
                Ok(let p) => print(i"x={p.x}"),
                Err(let e) => print(i"err {e}"),
            }
        }
        "#,
        "x=42\n",
    );
}

// === [derive(Wire)] — the data boundary (proposal/transport-rpc.md §3) ============

#[test]
fn wire_derives_the_json_round_trip() {
    // `[derive(Wire)]` reuses the Json round-trip: a Wire struct/enum encodes and decodes,
    // including nested Wire structs, `List<Wire>`, and Wire enums.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::result::Result::{ self, Ok, Err };
        [derive(Wire)]
        struct Point { x: i32, y: i32 }
        [derive(Wire)]
        struct Line { from: Point, to: Point, tags: List<str> }
        [derive(Wire)]
        enum Shape { Seg(Line), Empty }
        fun main() {
            let line = Line { from = Point { x = 1, y = 2 }, to = Point { x = 3, y = 4 }, tags = ["a"] };
            match Line::from_json(line.to_json()) {                          // decoding yields a Result (I3)
                Ok(let back) => {
                    print(i"{back.from.x} {back.from.y} {back.to.x} {back.to.y}");   // 1 2 3 4
                    match Shape::from_json(Shape::Seg(back).to_json()) {
                        Ok(Shape::Seg(let l)) => print(i"seg {l.from.x}"),           // seg 1
                        Ok(Shape::Empty) => print("empty"),
                        Err(let e) => print(e),
                    }
                }
                Err(let e) => print(e),
            }
        }
        "#,
        "1 2 3 4\nseg 1\n",
    );
}

#[test]
fn wire_rejects_a_non_wire_field() {
    // The boundary: a `[derive(Wire)]` type with a non-Wire field (`Password` has no codec)
    // is a compile error — the leak the type system prevents by construction.
    assert_fails(
        r#"
        struct Password { hash: str }
        [derive(Wire)]
        struct User { id: i32, password: Password }
        fun main() {}
        "#,
    );
}

#[test]
fn wire_rejects_a_list_of_non_wire() {
    // The recursive rule: `List<Secret>` is not Wire because `Secret` is not. This pins the
    // Wire check specifically — without it, the conditional `List<T: Json>` impl would let
    // `List<Secret>` slip through the codegen unchecked (the conditional-bound gap).
    assert_fails(
        r#"
        struct Secret { s: str }
        [derive(Wire)]
        struct Bag { items: List<Secret> }
        fun main() {}
        "#,
    );
}

// === [rpc] / [expose] — the service-surface checks (transport-rpc.md §4.2) ========

#[test]
fn rpc_accepts_a_wire_signature() {
    // An `[rpc]` method whose whole signature is Wire compiles: multiple parameters,
    // a container (`List<str>`), a nested `[derive(Wire)]` struct, an `Option` return —
    // and `self` is exempt from the check.
    assert_compiles(
        r#"
        import std::option::Option::{ self, Some, None };
        [derive(Wire)]
        struct Pt { x: i32 }
        struct Service {}
        impl Service {
            [rpc] fun locate(self, id: i32, tags: List<str>, at: Pt): Option<Pt> {
                Some(at)
            }
        }
        fun main() {}
        "#,
    );
}

#[test]
fn rpc_rejects_a_non_wire_parameter() {
    // The exposure rule: an `[rpc]` method cannot take a non-Wire type — the
    // dispatcher would have to decode it off the wire.
    assert_fails(
        r#"
        struct Password { hash: str }
        struct Service {}
        impl Service {
            [rpc] fun store(self, secret: Password) {}
        }
        fun main() {}
        "#,
    );
}

#[test]
fn rpc_rejects_a_non_wire_return() {
    // ...nor return one — the reply crosses the wire.
    assert_fails(
        r#"
        struct Password { hash: str }
        struct Service {}
        impl Service {
            [rpc] fun leak(self): Password {
                Password { hash = "x" }
            }
        }
        fun main() {}
        "#,
    );
}

#[test]
fn expose_accepts_a_signal_of_wire() {
    // An `[expose]`d field must be a `Signal` of a Wire element — a scalar and a
    // `[derive(Wire)]` struct both qualify.
    assert_compiles(
        r#"
        import std::reactive::Signal;
        [derive(Wire)]
        struct Pt { x: i32 }
        struct Session {
            [expose] status: Signal<str>,
            [expose] cursor: Signal<Pt>,
            hidden: i32,
        }
        fun main() {}
        "#,
    );
}

#[test]
fn expose_rejects_a_non_signal_field() {
    // Exposure is observation: a plain value has nothing to subscribe to.
    assert_fails(
        r#"
        struct Session {
            [expose] name: str,
        }
        fun main() {}
        "#,
    );
}

#[test]
fn expose_rejects_a_signal_of_non_wire() {
    // The observed values cross the wire, so the element must be Wire.
    assert_fails(
        r#"
        import std::reactive::Signal;
        struct Password { hash: str }
        struct Session {
            [expose] secret: Signal<Password>,
        }
        fun main() {}
        "#,
    );
}

// === [trait_only] / [doc(hidden)] — namespace hygiene (transport-rpc.md §3.2) =====

#[test]
fn trait_only_method_is_hidden_from_the_concrete_type() {
    // A `[trait_only]` trait method never resolves on the concrete type's own
    // surface — the direct call is an error even though the impl provides it.
    assert_fails(
        r#"
        import std::print;
        trait Marker { [trait_only] fun tag(self): str; }
        struct Pt { x: i32 }
        impl Pt with Marker { fun tag(self): str { "pt" } }
        fun main() { print(Pt { x = 1 }.tag()); }
        "#,
    );
}

#[test]
fn trait_only_method_resolves_through_a_bound() {
    // ...but through a trait bound it resolves and monomorphizes normally.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Marker { [trait_only] fun tag(self): str; }
        struct Pt { x: i32 }
        impl Pt with Marker { fun tag(self): str { "pt" } }
        fun describe<T: Marker>(value: T): str { value.tag() }
        fun main() { print(describe(Pt { x = 1 })); }
        "#,
        "pt\n",
    );
}

#[test]
fn trait_only_static_is_hidden_from_the_concrete_type() {
    // The same exclusion covers statics: `Pt::make()` is an error when `make`
    // is `[trait_only]` — the `from_json`-style surface stays clean.
    assert_fails(
        r#"
        trait Factory { [trait_only] fun make(): i32; }
        struct Pt {}
        impl Pt with Factory { fun make(): i32 { 7 } }
        fun main() { let n = Pt::make(); }
        "#,
    );
}

#[test]
fn trait_only_static_resolves_through_a_bound() {
    // ...while `T::make()` through the bound stays the sanctioned path.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Factory { [trait_only] fun make(): i32; }
        struct Pt {}
        impl Pt with Factory { fun make(): i32 { 7 } }
        fun build<T: Factory>(witness: T): i32 { T::make() }
        fun main() { print(build(Pt {})); }
        "#,
        "7\n",
    );
}

#[test]
fn trait_only_default_method_is_bound_reachable_but_hidden() {
    // A `[trait_only]` *default* method: an empty impl inherits it for the
    // bound path, but it is not promoted onto the concrete surface.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Marker { [trait_only] fun tag(self): str { "default" } }
        struct Pt { x: i32 }
        impl Pt with Marker {}
        fun via_bound<T: Marker>(value: T): str { value.tag() }
        fun main() { print(via_bound(Pt { x = 1 })); }
        "#,
        "default\n",
    );
    assert_fails(
        r#"
        import std::print;
        trait Marker { [trait_only] fun tag(self): str { "default" } }
        struct Pt { x: i32 }
        impl Pt with Marker {}
        fun main() { print(Pt { x = 1 }.tag()); }
        "#,
    );
}

#[test]
fn trait_only_does_not_shadow_an_inherent_method() {
    // The collision-safety point: a type's OWN method with the same name stays
    // reachable on the concrete surface — the `[trait_only]` trait method never
    // shadows it (nor is shadowed by it at the bound).
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Marker { [trait_only] fun tag(self): str { "trait-default" } }
        struct Pt { x: i32 }
        impl Pt { fun tag(self): str { "own" } }
        impl Pt with Marker {}
        fun main() { print(Pt { x = 1 }.tag()); }
        "#,
        "own\n",
    );
}

#[test]
fn bound_dispatch_prefers_the_trait_method_on_a_name_collision() {
    // FIXED: the analyzer resolved `value.tag()` through the `Marker` bound,
    // but the transformer's name-based re-dispatch found the concrete type's
    // INHERENT `tag` first. The resolved trait is now recorded per call
    // (bound_dispatch_traits) and emission dispatches on that trait's surface
    // — override, else default — so an inherent name collision can't shadow it.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Marker { fun tag(self): str { "trait-default" } }
        struct Pt { x: i32 }
        impl Pt { fun tag(self): str { "own" } }
        impl Pt with Marker {}
        fun via_bound<T: Marker>(value: T): str { value.tag() }
        fun main() { print(via_bound(Pt { x = 1 })); }
        "#,
        "trait-default\n",
    );
}

// === [service(Client)] generation (transport-rpc.md §4.2) =========================

#[test]
fn service_generates_dispatcher_client_and_mirror() {
    // The whole §4.2 surface, end to end and in-process: `[service(Client)]` generates
    // `Session::dispatcher(self)` (routes both `[rpc]` methods — multi-arg and no-arg),
    // the sibling `Client<T: Transport>` with `Result`-wrapped requestors, and a
    // `RemoteSource` mirror for the `[expose]`d field (whose update arrives in the same
    // wire turn as the mutating call's reply — hence `status = bumped` before `bump -> 5`).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::reactive::Signal;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, FromJson };
        import std::json::json_codec;
        import std::rpc::{ local_rpc, duplex_pair, ReactiveServer, ReactiveClient, RemoteSource };

        [service(Client)]
        struct Session {
            [expose] status: Signal<str>,
            count: Shared<i32>,
        }

        impl Session {
            [rpc]
            fun bump(self, by: i32): i32 {
                self.count.write() = self.count.read() + by;
                self.status.set("bumped");
                self.count.read()
            }

            [rpc]
            fun total(self): i32 {
                self.count.read()
            }
        }

        fun main() {
            let session = Session { status = Signal::new("idle"), count = Shared::new(0) };
            let transport = local_rpc(session.dispatcher().into_protocol(json_codec()));
            let (client_end, server_end) = duplex_pair();
            let channel = ReactiveServer::new(server_end, json_codec()).expose(session.status);
            let mirror: RemoteSource<str> = ReactiveClient::new(client_end, json_codec()).source(channel);
            let client = Client { transport, codec = json_codec(), status = mirror };
            let watching = client.status.sub(|s| {
                print(i"status = {s}");
            });
            match client.bump(5) {
                Ok(let n) => print(i"bump -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            match client.total() {
                Ok(let n) => print(i"total -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            let hashes_match = session.contract_hash() == client.contract_hash();
            print(i"hashes match = {hashes_match}");
            watching.dispose();
        }
        "#,
        "status = idle\nstatus = bumped\nbump -> 5\ntotal -> 5\nhashes match = true\n",
    );
}

#[test]
fn service_client_name_defaults_to_struct_client() {
    // Bare `[service]` names the generated client `<Struct>Client`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, json_codec };
        import std::rpc::{ local_rpc };

        [service]
        struct Counter {
            count: Shared<i32>,
        }

        impl Counter {
            [rpc]
            fun get(self): i32 {
                self.count.read()
            }
        }

        fun main() {
            let counter = Counter { count = Shared::new(41) };
            let transport = local_rpc(counter.dispatcher().into_protocol(json_codec()));
            let client = CounterClient { transport, codec = json_codec() };
            match client.get() {
                Ok(let n) => print(i"n = {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
        }
        "#,
        "n = 41\n",
    );
}

#[test]
fn service_contract_verify_matches_and_catches_drift() {
    // The generated `verify()` (Q6 v2): a client fetches the server's contract hash
    // over the built-in `__contract` route and compares. Against its own service:
    // `Ok(true)`. Against a *different* service's dispatcher (a drifted contract —
    // the versioning failure mode): `Ok(false)`, a clean signal instead of decode
    // garbage.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, json_codec };
        import std::rpc::{ local_rpc };

        [service(AClient)]
        struct Alpha { count: Shared<i32> }
        impl Alpha {
            [rpc] fun ping(self): i32 { 1 }
        }

        [service(BClient)]
        struct Beta { count: Shared<i32> }
        impl Beta {
            [rpc] fun rename(self, name: str): str { name }
        }

        fun main() {
            let alpha_transport = local_rpc(Alpha { count = Shared::new(0) }.dispatcher().into_protocol(json_codec()));
            let matching = AClient { transport = alpha_transport, codec = json_codec() };
            match matching.verify() {
                Ok(let same) => print(i"self = {same}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            // A BClient pointed at Alpha's dispatcher — the drift case.
            let drifted = BClient { transport = alpha_transport, codec = json_codec() };
            match drifted.verify() {
                Ok(let same) => print(i"drift = {same}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
        }
        "#,
        "self = true\ndrift = false\n",
    );
}

// === Async rpc handlers (the dispatch spine awaits — J2 through the wire) =========

#[test]
fn an_async_rpc_method_replies_after_its_await() {
    // The user-shaped case: a `[rpc]` method that awaits (here `sleep_for`)
    // compiles, and its reply carries the value computed AFTER the suspension.
    // The `[service]` macro wraps each route in a held `turn`, and every seam
    // of the spine (`Dispatcher.handle` → `RpcProtocol.respond` →
    // `LocalTransport.call`) awaits through a re-marked `let` (J2 v1).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, json_codec };
        import std::rpc::{ local_rpc };
        import std::time::{ sleep_for, Duration };

        [service(SlowClient)]
        struct Slow { calls: Shared<i32> }

        impl Slow {
            [rpc]
            fun slow_double(self, by: i32): i32 {
                self.calls.write() = self.calls.read() + 1;
                sleep_for(Duration::millis(10));
                by * 2
            }
        }

        fun main() {
            let service = Slow { calls = Shared::new(0) };
            let transport = local_rpc(service.dispatcher().into_protocol(json_codec()));
            let client = SlowClient { transport, codec = json_codec() };
            match client.slow_double(7) {
                Ok(let n) => print(i"slow_double -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            print(i"calls = {service.calls.read()}");
        }
        "#,
        "slow_double -> 14\ncalls = 1\n",
    );
}

#[test]
fn sync_and_async_rpc_methods_coexist_on_one_service() {
    // J2 in both directions through the retyped spine: the sync method rides
    // the same `async |..|`-seamed dispatch (awaiting a plain value just
    // resolves), the async one settles before its reply encodes.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, json_codec };
        import std::rpc::{ local_rpc };
        import std::time::{ sleep_for, Duration };

        [service(MixedClient)]
        struct Mixed { count: Shared<i32> }

        impl Mixed {
            [rpc]
            fun quick(self): i32 { 1 }

            [rpc]
            fun slow(self): i32 {
                sleep_for(Duration::millis(5));
                2
            }
        }

        fun main() {
            let transport = local_rpc(
                Mixed { count = Shared::new(0) }.dispatcher().into_protocol(json_codec()),
            );
            let client = MixedClient { transport, codec = json_codec() };
            match client.quick() {
                Ok(let n) => print(i"quick -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            match client.slow() {
                Ok(let n) => print(i"slow -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
        }
        "#,
        "quick -> 1\nslow -> 2\n",
    );
}

#[test]
fn an_async_rpc_methods_writes_settle_as_one_wave_with_its_reply() {
    // The wire turn HOLDS across the handler's await (an awaiting `turn` body, the true
    // at-end cadence): a write before and a write after the suspension
    // coalesce, so the mirror sees ONE update — the final value — alongside
    // the reply. (Per-segment settling would leak "working" as its own
    // update before the reply.)
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::reactive::Signal;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, FromJson };
        import std::json::json_codec;
        import std::rpc::{ local_rpc, duplex_pair, ReactiveServer, ReactiveClient, RemoteSource };
        import std::time::{ sleep_for, Duration };

        [service(JobClient)]
        struct Job {
            [expose] status: Signal<str>,
        }

        impl Job {
            [rpc]
            fun run(self): i32 {
                self.status.set("working");
                sleep_for(Duration::millis(10));
                self.status.set("done");
                7
            }
        }

        fun main() {
            let job = Job { status = Signal::new("idle") };
            let transport = local_rpc(job.dispatcher().into_protocol(json_codec()));
            let (client_end, server_end) = duplex_pair();
            let channel = ReactiveServer::new(server_end, json_codec()).expose(job.status);
            let mirror: RemoteSource<str> = ReactiveClient::new(client_end, json_codec()).source(channel);
            let client = JobClient { transport, codec = json_codec(), status = mirror };
            let watching = client.status.sub(|s| {
                print(i"status = {s}");
            });
            match client.run() {
                Ok(let n) => print(i"run -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            watching.dispose();
        }
        "#,
        "status = idle\nstatus = done\nrun -> 7\n",
    );
}

#[test]
fn a_no_arg_rpc_methods_writes_coalesce_in_the_wire_turn() {
    // The hole the wave pin uncovered, pinned on its own (no async involved):
    // no-arg methods once took a bare `.on(..)` fast path that skipped the
    // wire turn entirely, so each write leaked as its own update. Every
    // method route now goes through `route_block`'s turn — two writes in a
    // sync no-arg method arrive at the mirror as ONE update, the final value.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::reactive::Signal;
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, FromJson };
        import std::json::json_codec;
        import std::rpc::{ local_rpc, duplex_pair, ReactiveServer, ReactiveClient, RemoteSource };

        [service(FlipClient)]
        struct Flip {
            [expose] state: Signal<str>,
        }

        impl Flip {
            [rpc]
            fun flip(self): i32 {
                self.state.set("mid");
                self.state.set("final");
                1
            }
        }

        fun main() {
            let flip = Flip { state = Signal::new("start") };
            let transport = local_rpc(flip.dispatcher().into_protocol(json_codec()));
            let (client_end, server_end) = duplex_pair();
            let channel = ReactiveServer::new(server_end, json_codec()).expose(flip.state);
            let mirror: RemoteSource<str> = ReactiveClient::new(client_end, json_codec()).source(channel);
            let client = FlipClient { transport, codec = json_codec(), state = mirror };
            let watching = client.state.sub(|s| {
                print(i"state = {s}");
            });
            match client.flip() {
                Ok(let n) => print(i"flip -> {n}"),
                Err(let error) => print(i"err {error.to_json()}"),
            }
            watching.dispose();
        }
        "#,
        "state = start\nstate = final\nflip -> 1\n",
    );
}

#[test]
fn a_hand_written_async_route_dispatches_through_respond() {
    // The foundation API without the macro: an async handler registered with
    // `Dispatcher.on` (its `async |..|` parameter), driven through `respond`
    // directly — the reply envelope encodes the settled outcome.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::json::json_codec;
        import std::wire::Frame;
        import std::rpc::{ Dispatcher, reply, encode_request, RpcOutcome };
        import std::time::{ sleep_for, Duration };

        fun main() {
            let protocol = Dispatcher::new()
                .on("slow", |request| {
                    sleep_for(Duration::millis(5));
                    reply(21)
                })
                .into_protocol(json_codec());
            let answer = protocol.respond(encode_request(json_codec(), "slow", []));
            match answer {
                Frame::Text(let envelope) => print(i"answer: {envelope}"),
                Frame::Binary(let bytes) => print("answer: unexpected binary"),
            }
        }
        "#,
        "answer: {\"Success\":21}\n",
    );
}

#[test]
fn rpc_rejects_a_missing_return() {
    // A void `[rpc]` method has no reply payload to encode — the return must be a
    // declared Wire type (fire-and-forget needs its own design).
    assert_fails(
        r#"
        struct Service {}
        impl Service {
            [rpc] fun ping(self) {}
        }
        fun main() {}
        "#,
    );
}

#[test]
fn a_discarded_async_block_still_runs() {
    // `async { .. }` is an *invoked* async arrow: its body starts executing
    // immediately (up to the first await), so it is effectful even when the
    // promise is discarded. The transformer's side-effect analysis used to
    // classify it as pure and elide the whole statement — `let _ = async { pump
    // loop }` silently vanished from codegen (found via SplitDuplex's pump).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let _ = async {
                print("ran");
            };
            print("after");
        }
        "#,
        "ran\nafter\n",
    );
}

#[test]
fn a_parenthesized_type_is_grouping_not_a_tuple() {
    // `(T)` in type position is grouping, not a one-tuple — required to write a
    // closure-typed closure parameter (`|(|| void)| void`, the host-Promise
    // executor shape `std::time::sleep` uses). The inner closure is passed AND
    // called through the parenthesized annotation.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun run_with(callback: |(|| void)| void) {
            callback(|| print("called"));
        }
        fun main() {
            run_with(|done: || void| {
                done();
            });
        }
        "#,
        "called\n",
    );
}

#[test]
fn calling_an_unannotated_closure_parameter_defers() {
    // FIXED: a free call whose SUBJECT is an unannotated closure parameter
    // (`|done| { done(); }`) now defers until bidirectional inference lands
    // the parameter's type — the same rule the method-receiver and argument
    // paths already had (Bug C′'s family).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun run_with(callback: |(|| void)| void) {
            callback(|| print("called"));
        }
        fun main() {
            run_with(|done| {
                done();
            });
        }
        "#,
        "called\n",
    );
}

#[test]
fn doc_hidden_method_stays_callable() {
    // `[doc(hidden)]` is tooling-only: completion omits it, resolution doesn't.
    assert_compiles_and_runs(
        r#"
        import std::print;
        struct Pt { x: i32 }
        impl Pt {
            [doc(hidden)]
            fun secret(self): i32 { self.x }
        }
        fun main() { print(Pt { x = 9 }.secret()); }
        "#,
        "9\n",
    );
}

#[test]
fn emitted_js_preserves_grouping_across_precedence() {
    // A latent emitter miscompile (found by the bits-and-bytes probe,
    // proposal/bits-and-bytes.md §0): the JS printer rendered binary operands
    // flat, so `(1 + 2) * 3` emitted as `1 + 2 * 3` and printed 7. Operands are
    // now parenthesized by JS precedence.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            print((1 + 2) * 3);
            let a = 1;
            let b = 2;
            let c = 3;
            print((a + b) * c);
            print(0 - (a - b));
            print(a - (b - c));
            print((a + b) / (b + c) + 1);
            print((1.0 + 2.0) / (2.0 + 3.0) + 1.0);
        }
        "#,
        "9\n9\n1\n2\n1\n1.6\n",
    );
}

#[test]
fn emitted_js_parenthesizes_right_nested_string_concat() {
    // `+` is left-associative but not insensitive to grouping once strings mix
    // in: `1 + (2 + "x")` is "12x", while flat `1 + 2 + "x"` would be "3x".
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let suffix = "x";
            print(1 + (2 + suffix));
        }
        "#,
        "12x\n",
    );
}

#[test]
fn hex_literals_type_and_evaluate_like_decimal() {
    // `0x` is a spelling, not a type: suffix, context, and the i32 default all
    // apply, and the literal reaches JS verbatim (proposal/bits-and-bytes.md §1).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            print(0xFF);
            print(0x10 + 1);
            let big = 0xDEADn;
            print(big);
            print(i"masked = {0xF0 & 0x1F}");
        }
        "#,
        "255\n17\n57005n\nmasked = 16\n",
    );
}

#[test]
fn bitwise_operators_on_i32_use_signed_js_semantics() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            print(12 & 10);
            print(12 | 3);
            print(12 ^ 10);
            print(1 << 5);
            print(0 - 8 >> 1);
        }
        "#,
        "8\n15\n6\n32\n-4\n",
    );
}

#[test]
fn bitwise_operators_on_u32_stay_unsigned() {
    // JS bitwise is signed; `u32` results re-wrap with `>>> 0` and `>>` is the
    // logical `>>>` — a set high bit must come back as a large unsigned value
    // (proposal/bits-and-bytes.md §2).
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let high: u32 = 0x80000000;
            print(high | 0);
            print(high >> 4);
            print(0xFFFFFFFFu32 >> 28);
            let one: u32 = 1;
            print(one << 31);
            print(0xF0F0F0F0u32 ^ 0xFFFFFFFFu32);
        }
        "#,
        "2147483648\n134217728\n15\n2147483648\n252645135\n",
    );
}

#[test]
fn bitwise_operators_on_bigint_do_not_wrap() {
    // BigInt is arbitrary-precision: the native JS operators apply and the u32
    // `>>> 0` normalization must NOT — `1n << 64n` exceeds 64 bits intact.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            print(0xFFn & 0x0Fn);
            print(1n << 64n);
        }
        "#,
        "15n\n18446744073709551616n\n",
    );
}

#[test]
fn bitwise_precedence_is_rust_order_not_c_order() {
    // `<< >>` over `&` over `^` over `|`, all over comparisons — so
    // `1 << 2 == 4` is `(1 << 2) == 4` and `1 | 2 ^ 2 & 3` is `1 | (2 ^ (2 & 3))`.
    // Emission must survive JS's DIFFERENT (C-style) order via parentheses.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            print(1 << 2 == 4);
            print(1 | 2 ^ 2 & 3);
            print((1 | 2) & 3 == 3);
            let masked = 0xFF & 0x0F;
            print(masked == 15);
        }
        "#,
        "true\n1\ntrue\ntrue\n",
    );
}

#[test]
fn shifts_coexist_with_nested_generics() {
    // `<<`/`>>` are two ADJACENT control tokens in expression position;
    // `List<List<i32>>` (type position) and comparisons are untouched.
    assert_compiles_and_runs(
        r#"
        import std::print;
        fun main() {
            let nested: List<List<i32>> = [[1, 2], [3]];
            let shifted = nested.len() << 2;
            print(shifted);
            print(1 < 2);
        }
        "#,
        "8\ntrue\n",
    );
}

#[test]
fn split_shift_stays_a_parse_error() {
    // Adjacency is load-bearing: `a < < b` must not silently become a shift.
    assert_fails(
        r#"
        fun main() {
            let a = 1;
            let b = 2;
            let c = a < < b;
        }
        "#,
    );
}

#[test]
fn bitand_dispatches_to_the_operator_trait() {
    // `&` on a struct routes through `std::operators::BitAnd::bit_and`,
    // mirroring `+`/`Add`.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::operators::BitAnd;
        struct Flags { bits: i32 }
        impl Flags with BitAnd {
            fun bit_and(self, other: Flags): Flags {
                Flags { bits = self.bits & other.bits }
            }
        }
        fun main() {
            let a = Flags { bits = 12 };
            let b = Flags { bits = 10 };
            print((a & b).bits);
        }
        "#,
        "8\n",
    );
}

#[test]
fn missing_bitwise_impl_names_the_trait() {
    // A non-native type without the impl gets the operator diagnostic naming
    // the trait, mirroring `Add`.
    assert_fails(
        r#"
        struct Flags { bits: i32 }
        fun main() {
            let a = Flags { bits = 1 };
            let b = Flags { bits = 2 };
            let c = a ^ b;
        }
        "#,
    );
}

#[test]
fn bytes_buffers_round_trip() {
    // `std::bytes` (proposal/bits-and-bytes.md §3): alloc/len/get/set with the
    // host's `& 0xFF` store semantics, slice, concat, and a multibyte UTF-8
    // round-trip. The codec substrate.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::bytes::{ Bytes, encode_utf8, decode_utf8 };
        fun main() {
            let buffer = Bytes::alloc(4);
            print(buffer.len());
            buffer.set(0, 0xDE);
            buffer.set(1, 0x1FF);
            print(buffer.get(0));
            print(buffer.get(1));
            print(buffer.get(2));
            let joined = Bytes::concat(buffer.slice(0, 2), buffer);
            print(joined.len());
            let text = "héllo 🎉";
            let encoded = encode_utf8(text);
            print(encoded.len());
            print(decode_utf8(encoded) == text);
        }
        "#,
        "4\n222\n255\n0\n6\n11\ntrue\n",
    );
}

#[test]
fn generic_trait_method_dispatches_through_a_bound() {
    // FIXED: a trait method with its OWN generic parameters (describe<S: Sink>)
    // used to no-op silently through `T: Describable` — the OnConstraint
    // emission re-targeted the concrete impl's method without the call's
    // own-generic bindings (whose ids belong to the TRAIT member), so the
    // instance emitted with S unbound. The bindings now cross the re-dispatch
    // as ordered values, zipped onto the target's own generics.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        trait Sink { fun put(self, value: i32); }
        struct Collector { total: Shared<i32> }
        impl Collector with Sink {
            fun put(self, value: i32) {
                self.total.write() = self.total.read() + value;
            }
        }
        trait Describable {
            fun describe<S: Sink>(self, sink: S);
        }
        struct Point { x: i32, y: i32 }
        impl Point with Describable {
            fun describe<S: Sink>(self, sink: S) {
                sink.put(self.x);
                sink.put(self.y);
            }
        }
        fun encode<T: Describable, S: Sink>(value: T, sink: S) {
            value.describe(sink);
        }
        fun main() {
            let collector = Collector { total = Shared::new(0) };
            let point = Point { x = 3, y = 4 };
            point.describe(collector);
            print(collector.total.read());
            encode(point, collector);
            print(collector.total.read());
        }
        "#,
        "7\n14\n",
    );
}

#[test]
fn impl_binder_in_trait_argument_position() {
    // One impl serving every sink: the binder sits in the TRAIT argument,
    // registered like a subject binder (bound-less ones inherit the trait's
    // declared bound for the position) — transport-rpc.md §6.1's other gap,
    // closed.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        trait Sink { fun put(self, value: i32); }
        struct Collector { total: Shared<i32> }
        impl Collector with Sink {
            fun put(self, value: i32) {
                self.total.write() = self.total.read() + value;
            }
        }
        trait DescribeInto<S> {
            fun describe_into(self, sink: S);
        }
        struct Point { x: i32 }
        impl Point with DescribeInto<type S: Sink> {
            fun describe_into(self, sink: S) {
                sink.put(self.x);
            }
        }
        fun main() {
            let point = Point { x = 3 };
            let collector = Collector { total = Shared::new(0) };
            point.describe_into(collector);
            print(collector.total.read());
        }
        "#,
        "3\n",
    );
}

#[test]
fn hand_written_wire_impls_round_trip_through_json() {
    // The §6.1 visitor, proven hand-written before the derive targets it: a
    // struct (scalar/list/option/nested-enum fields) and an enum (0/1/2-arity
    // variants) describe to `JsonWriter` and rebuild from `JsonReader`. The
    // encoded text must match the established `to_json` wire format exactly
    // (externally-tagged variants, arity>1 payload arrays, bare `Some`,
    // `null` for `None`), and structural failures are sticky decode errors —
    // backlog I3's validating decode.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        import std::wire::{ Wire, Serialize, Deserialize };
        import std::json::{ encode_json, decode_json };

        enum Status {
            Offline,
            Away(str),
            Busy(str, i32),
        }

        impl Status with Wire {
            fun describe<S: Serialize>(self, serializer: S) {
                match self {
                    Status::Offline => {
                        serializer.begin_variant("Offline", 0);
                        serializer.end_variant();
                    },
                    Status::Away(let reason) => {
                        serializer.begin_variant("Away", 1);
                        reason.describe(serializer);
                        serializer.end_variant();
                    },
                    Status::Busy(let task, let minutes) => {
                        serializer.begin_variant("Busy", 2);
                        task.describe(serializer);
                        minutes.describe(serializer);
                        serializer.end_variant();
                    },
                }
            }

            fun rebuild<D: Deserialize>(deserializer: D): Status {
                let tag = deserializer.variant_tag();
                match tag {
                    "Offline" => {
                        deserializer.begin_variant("Offline", 0);
                        deserializer.end_variant();
                        Status::Offline
                    },
                    "Away" => {
                        deserializer.begin_variant("Away", 1);
                        let reason = str::rebuild(deserializer);
                        deserializer.end_variant();
                        Status::Away(reason)
                    },
                    "Busy" => {
                        deserializer.begin_variant("Busy", 2);
                        let task = str::rebuild(deserializer);
                        let minutes = i32::rebuild(deserializer);
                        deserializer.end_variant();
                        Status::Busy(task, minutes)
                    },
                    _ => {
                        deserializer.fail(i"unknown variant '{tag}'");
                        Status::Offline
                    },
                }
            }
        }

        struct Profile {
            id: i32,
            name: str,
            scores: List<i32>,
            nickname: Option<str>,
            status: Status,
        }

        impl Profile with Wire {
            fun describe<S: Serialize>(self, serializer: S) {
                serializer.begin_struct(5);
                serializer.field("id");
                self.id.describe(serializer);
                serializer.field("name");
                self.name.describe(serializer);
                serializer.field("scores");
                self.scores.describe(serializer);
                serializer.field("nickname");
                self.nickname.describe(serializer);
                serializer.field("status");
                self.status.describe(serializer);
                serializer.end_struct();
            }

            fun rebuild<D: Deserialize>(deserializer: D): Profile {
                deserializer.begin_struct();
                deserializer.field("id");
                let id = i32::rebuild(deserializer);
                deserializer.field("name");
                let name = str::rebuild(deserializer);
                deserializer.field("scores");
                let scores: List<i32> = List::rebuild(deserializer);
                deserializer.field("nickname");
                let nickname: Option<str> = Option::rebuild(deserializer);
                deserializer.field("status");
                let status = Status::rebuild(deserializer);
                deserializer.end_struct();
                Profile { id = id, name = name, scores = scores, nickname = nickname, status = status }
            }
        }

        fun main() {
            let profile = Profile {
                id = 7,
                name = "ada \"the\" first",
                scores = [3, 1, 4],
                nickname = None,
                status = Status::Busy("proofs", 45),
            };
            let encoded = encode_json(profile);
            print(encoded);
            let decoded: Result<Profile, str> = decode_json(encoded);
            match decoded {
                Ok(let back) => {
                    print(back.id);
                    print(back.scores.len());
                    match back.status {
                        Status::Busy(let task, let minutes) => print(i"busy {task} {minutes}"),
                        _ => print("wrong status"),
                    }
                },
                Err(let reason) => print(i"decode failed: {reason}"),
            }
            print(encode_json(Profile { id = 1, name = "bob", scores = [], nickname = Some("bo"), status = Status::Away("lunch") }));
            let missing: Result<Profile, str> = decode_json("{\"id\":1,\"name\":\"x\",\"scores\":[]}");
            match missing {
                Ok(let value) => print("should have failed"),
                Err(let reason) => print(i"err: {reason}"),
            }
            let unknown: Result<Status, str> = decode_json("{\"Vanished\":1}");
            match unknown {
                Ok(let value) => print("should have failed"),
                Err(let reason) => print(i"err: {reason}"),
            }
        }
        "#,
        "{\"id\":7,\"name\":\"ada \\\"the\\\" first\",\"scores\":[3,1,4],\"nickname\":null,\"status\":{\"Busy\":[\"proofs\",45]}}\n7\n3\nbusy proofs 45\n{\"id\":1,\"name\":\"bob\",\"scores\":[],\"nickname\":\"bo\",\"status\":{\"Away\":\"lunch\"}}\nerr: missing field 'nickname'\nerr: unknown variant 'Vanished'\n",
    );
}

#[test]
fn qualified_generic_static_resolves_inner_trait_statics() {
    // FIXED: `List<i32>::rebuild(d)` (the qualified-generic spelling) used to
    // emit the inner `T::rebuild` as an EMPTY function — the accessor resolution
    // discarded the subject's type args entirely. A qualified subject now seeds
    // the matched impl's binder bindings into ITS call's substitution.
    //
    // `build` returns `Self`, not `Build`: it is the `wire.vl` shape, and this
    // program was written in the same stand-in style std was, before B4 §11
    // gave those declarations their real spelling.
    assert_compiles_and_runs(
        r#"
        import std::print;
        trait Build {
            fun build(seed: i32): Self;
        }
        impl i32 with Build {
            fun build(seed: i32): i32 { seed + 1 }
        }
        struct Boxy<T> { value: T }
        impl Boxy<type T: Build> {
            fun make(seed: i32): Boxy<T> {
                Boxy { value = T::build(seed) }
            }
        }
        fun main() {
            let via_annotation: Boxy<i32> = Boxy::make(1);
            print(via_annotation.value);
            let via_qualified = Boxy<i32>::make(1);
            print(via_qualified.value);
        }
        "#,
        "2\n2\n",
    );
}

#[test]
fn derived_wire_visitor_matches_to_json_and_round_trips() {
    // `[derive(Wire)]` now also emits the §6.1 visitor impls: the described
    // output must equal the derived `to_json` byte-for-byte, rebuild must
    // round-trip (scalars, List, Option, a nested derived enum), and
    // structural failures surface as sticky decode errors through the
    // GENERATED rebuilds.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, encode_json, decode_json };

        [derive(Wire)]
        enum Status {
            Offline,
            Away(str),
            Busy(str, i32),
        }

        [derive(Wire)]
        struct Profile {
            id: i32,
            name: str,
            scores: List<i32>,
            nickname: Option<str>,
            status: Status,
        }

        fun main() {
            let profile = Profile {
                id = 7,
                name = "ada",
                scores = [3, 1, 4],
                nickname = None,
                status = Status::Busy("proofs", 45),
            };
            let via_visitor = encode_json(profile);
            print(via_visitor == profile.to_json());
            let decoded: Result<Profile, str> = decode_json(via_visitor);
            match decoded {
                Ok(let back) => {
                    print(back.id);
                    match back.status {
                        Status::Busy(let task, let minutes) => print(i"busy {task} {minutes}"),
                        _ => print("wrong"),
                    }
                },
                Err(let reason) => print(i"failed: {reason}"),
            }
            let missing: Result<Profile, str> = decode_json("{\"id\":1}");
            match missing {
                Ok(let value) => print("should fail"),
                Err(let reason) => print(i"err: {reason}"),
            }
            let unknown: Result<Status, str> = decode_json("\"Vanished\"");
            match unknown {
                Ok(let value) => print("should fail"),
                Err(let reason) => print(i"err: {reason}"),
            }
        }
        "#,
        "true\n7\nbusy proofs 45\nerr: missing field 'name'\nerr: unknown variant 'Vanished'\n",
    );
}

#[test]
fn derived_struct_with_two_differently_typed_options() {
    // FIXED (same root as the qualified-static gap): with the subject's type
    // args discarded, `Option<str>::from_json_value(..)` and
    // `Option<i32>::from_json_value(..)` in one generated function fought over
    // one shared binder — use sites failed with "Expected Option<i32>, but got
    // Option<str>". Per-call subject bindings keep the two instantiations apart.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        [derive(Json)]
        struct OnlyOptions {
            nick: Option<str>,
            zero: Option<i32>,
        }
        fun main() {
            let value = OnlyOptions { nick = Some("bo"), zero = Some(0) };
            match value.nick {
                Some(let nick) => print(i"nick {nick}"),
                None => print("no nick"),
            }
            match value.zero {
                Some(let zero) => print(i"zero {zero}"),
                None => print("no zero"),
            }
        }
        "#,
        "nick bo\nzero 0\n",
    );
}

#[test]
fn both_codecs_round_trip_derived_wire_values() {
    // §6.2 end-to-end: one derived value through `json_codec()` and
    // `binary_codec()` — negative i32, high-bit u32, f64, multibyte str,
    // List, BOTH Option marker paths (Some(0) is exactly what the binary
    // `0x01` marker disambiguates from None's `0x00`), and a 2-arity enum.
    // Plus the failure modes: a frame of the wrong kind arrives pre-poisoned,
    // and a truncated binary frame fails sticky instead of crashing.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        import std::wire::{ Wire, Frame, Codec, encode, decode };
        import std::json::{ Json, json_codec };
        import std::binary::binary_codec;

        [derive(Wire)]
        enum Status {
            Offline,
            Busy(str, i32),
        }

        [derive(Wire)]
        struct Probe {
            id: i32,
            big: u32,
            ratio: f64,
            label: str,
            flags: List<bool>,
            zero: Option<i32>,
            status: Status,
        }

        fun sample(zero: Option<i32>): Probe {
            Probe {
                id = 0 - 42,
                big = 0xDEADBEEF,
                ratio = 0.5,
                label = "héllo 🎉",
                flags = [true, false, true],
                zero = zero,
                status = Status::Busy("proofs", 45),
            }
        }

        fun check(name: str, back: Result<Probe, str>) {
            match back {
                Ok(let value) => {
                    let intact =
                        value.id == 0 - 42 && value.big == 0xDEADBEEFu32
                        && value.ratio == 0.5 && value.label == "héllo 🎉"
                        && value.flags.len() == 3;
                    print(i"{name} intact = {intact}");
                    match value.zero {
                        Some(let n) => print(i"{name} zero = {n}"),
                        None => print(i"{name} zero = none"),
                    }
                },
                Err(let reason) => print(i"{name} failed: {reason}"),
            }
        }

        fun main() {
            let json = json_codec();
            let binary = binary_codec();
            check("json", decode(json, encode(json, sample(Some(0)))));
            check("binary", decode(binary, encode(binary, sample(Some(0)))));
            check("binary-none", decode(binary, encode(binary, sample(None))));
            let crossed: Result<Probe, str> = decode(binary, encode(json, sample(Some(0))));
            match crossed {
                Ok(let value) => print("should fail"),
                Err(let reason) => print(i"err: {reason}"),
            }
            match encode(binary, sample(Some(0))) {
                Frame::Binary(let whole) => {
                    let cut: Result<Probe, str> = decode(binary, Frame::Binary(whole.slice(0, 9)));
                    match cut {
                        Ok(let value) => print("should fail"),
                        Err(let reason) => print(i"err: {reason}"),
                    }
                },
                Frame::Text(let text) => print("unexpected"),
            }
        }
        "#,
        "json intact = true\njson zero = 0\nbinary intact = true\nbinary zero = 0\nbinary-none intact = true\nbinary-none zero = none\nerr: binary codec: received a text frame\nerr: unexpected end of frame\n",
    );
}

#[test]
fn generated_decode_gate_rejects_a_garbled_request() {
    // The §4.1 validating decode, end to end through GENERATED code: a raw
    // envelope calling `add` with no arguments makes the handler's arg pull
    // fail (binary: out of bounds), and the generated `decode_failed` gate
    // returns `RpcError::Decode` instead of running the impl on zero values —
    // the server's counter must still be 0 afterwards.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::shared::Shared;
        import std::result::Result::{ self, Ok, Err };
        import std::json::Json;
        import std::binary::binary_codec;
        import std::rpc::{ local_rpc, RpcError, call };

        [service(Client)]
        struct Counter {
            count: Shared<i32>,
        }

        impl Counter {
            [rpc]
            fun add(self, by: i32): i32 {
                self.count.write() = self.count.read() + by;
                self.count.read()
            }
        }

        fun main() {
            let counter = Counter { count = Shared::new(0) };
            let transport = local_rpc(counter.dispatcher().into_protocol(binary_codec()));
            // A hand-built envelope with ZERO args for a one-arg method.
            let garbled: Result<i32, RpcError> = call(transport, binary_codec(), "add", []);
            match garbled {
                Ok(let value) => print("should have failed"),
                Err(let error) => print(i"err: {error.to_json()}"),
            }
            let untouched = counter.count.read();
            print(i"count still {untouched}");
        }
        "#,
        "err: {\"Decode\":\"unexpected end of frame\"}\ncount still 0\n",
    );
}

#[test]
fn ws_parser_handles_the_rfc_vectors() {
    // std::ws (transport-rpc.md §5): the RFC 6455 masked "Hello" vector, the
    // same frame split across two feeds, our own encoder round-tripped, the
    // 16-bit length ladder, fragmentation reassembly, ping surfacing, and
    // close ending the stream (later frames ignored).
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::bytes::{ Bytes, encode_utf8 };
        import std::ws::{ WsParser, WsEvent, text_frame, encode_frame, close_frame };

        fun show(events: List<WsEvent>) {
            for event in events {
                match event {
                    WsEvent::Text(let text) => print(i"text: {text}"),
                    WsEvent::Binary(let bytes) => print(i"binary: {bytes.len()} bytes"),
                    WsEvent::Ping(let payload) => print(i"ping: {payload.len()} bytes"),
                    WsEvent::Closed => print("closed"),
                }
            }
        }

        fun masked_hello(): Bytes {
            let masked = Bytes::alloc(11);
            masked.set(0, 0x81);
            masked.set(1, 0x85);
            masked.set(2, 0x37);
            masked.set(3, 0xFA);
            masked.set(4, 0x21);
            masked.set(5, 0x3D);
            masked.set(6, 0x7F);
            masked.set(7, 0x9F);
            masked.set(8, 0x4D);
            masked.set(9, 0x51);
            masked.set(10, 0x58);
            masked
        }

        fun main() {
            let parser = WsParser::new();
            show(parser.feed(masked_hello()));
            let splitter = WsParser::new();
            show(splitter.feed(masked_hello().slice(0, 5)));
            print("(partial fed)");
            show(splitter.feed(masked_hello().slice(5, 11)));
            let echo = WsParser::new();
            show(echo.feed(text_frame("server says hi")));
            let big = encode_frame(0x2, Bytes::alloc(200));
            print(i"200B frame = {big.len()} bytes on the wire");
            show(echo.feed(big));
            let part1 = text_frame("Hel");
            part1.set(0, 0x01);
            let part2 = text_frame("lo");
            part2.set(0, 0x80);
            let fragmented = WsParser::new();
            show(fragmented.feed(Bytes::concat(part1, part2)));
            let control = WsParser::new();
            show(control.feed(encode_frame(0x9, encode_utf8("hb"))));
            show(control.feed(close_frame()));
            show(control.feed(text_frame("after close")));
            print("done");
        }
        "#,
        "text: Hello\n(partial fed)\ntext: Hello\ntext: server says hi\n200B frame = 204 bytes on the wire\nbinary: 200 bytes\ntext: Hello\nping: 2 bytes\nclosed\ndone\n",
    );
}

#[test]
fn client_connect_enforces_the_contract_and_wires_mirrors() {
    // §4.2's Client::connect, end to end over a real WebSocket: one generated
    // call opens the socket, VERIFIES the contract hash (Q6 enforcement — the
    // drift case below refuses with Err(Contract) before any decode), calls
    // the generated __attach against the runtime session registry
    // (`Service::new`'s default lifecycle), and wires one RemoteSource mirror
    // per [expose]d field in declaration order — both mirrors deliver.
    //
    // Both servers bind port 0 and the ready callbacks report what they got
    // (backlog E19): literals collided in the v0.12.0 release gate
    // (EADDRINUSE on a re-run), on Windows the 45000-48500 band sits inside
    // the ranges Hyper-V/WSL reserve outright (windows-support.md §4), and a
    // probe-then-substitute port keeps a TOCTOU window the OS can close for us.
    assert_compiles_and_runs(
        &r#"
import std::print;
        import std::process::exit;
        import std::time::sleep;
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ Json, FromJson, json_codec };
        import std::reactive::Signal;
        import std::shared::Shared;
        import std::rpc_server::Service;
        import std::http::{ Response, Server };

        // The whole paradigm, zero manual wiring: [expose]d state + [rpc] methods,
        // a Service on the server's builder, Client::connect on the client.
        [service(Client)]
        struct Board {
        	[expose] count: Signal<i32>,
        	[expose] label: Signal<str>,
        	total: Shared<i32>,
        }
        
        impl Board {
        	[rpc]
        	fun add(self, by: i32): i32 {
        		self.count.set(self.count.get() + by);
        		self.total.write() = self.total.read() + by;
        		self.label.set(i"sum {self.count.get()}");
        		self.count.get()
        	}
        }
        
        // A second, DIFFERENT service on another port — the drift case.
        [service(OtherClient)]
        struct Other {
        	value: Shared<i32>,
        }
        
        impl Other {
        	[rpc]
        	fun ping(self): i32 { 1 }
        }
        
        fun main() {
        	let board = Board { count = Signal::new(0), label = Signal::new(""), total = Shared::new(0) };
        	Server::builder()
        		.port(0)
        		.with_service(Service::new(board.dispatcher().into_protocol(json_codec())))
        		.on_request(|request| Response::builder().code(404).body("probe").build())
        		.on_start(|board_server| {
        			let other = Other { value = Shared::new(0) };
        			Server::builder()
        				.port(0)
        				.with_service(Service::new(other.dispatcher().into_protocol(json_codec())))
        				.on_request(|request| Response::builder().code(404).body("probe").build())
        				.on_start(|other_server| drive(board_server.port(), other_server.port()))
        				.build()
        				.start();
        		})
        		.build()
        		.start();
        }
        
        fun drive(board_port: i32, other_port: i32) {
        	// One call: socket + contract enforcement + attach + mirrors.
        	match Client::connect(i"ws://localhost:{board_port}", json_codec()) {
        		Ok(let client) => {
        			// Typed mirrors: values arrive decoded at each field's type.
        			let counting = client.count.sub(|n| {
        				print(i"count = {n}");
        			});
        			let labeling = client.label.sub(|s| {
        				if s != "" {
        					print(i"label = {s}");
        				}
        			});
        			match client.add(7) {
        				Ok(let n) => print(i"add -> {n}"),
        				Err(let error) => print(i"add err {error.to_json()}"),
        			}
        			sleep(300);
        			// Drift: a Board client pointed at Other's server refuses cleanly.
        			match Client::connect(i"ws://localhost:{other_port}", json_codec()) {
        				Ok(let wrong) => print("drift NOT caught"),
        				Err(let error) => print(i"drift: {error.to_json()}"),
        			}
        			sleep(100);
        			exit(0);
        		},
        		Err(let error) => {
        			print(i"connect failed: {error.to_json()}");
        			exit(1);
        		},
        	}
        }

        "#,
        "count = 0\ncount = 7\nlabel = sum 7\nadd -> 7\ndrift: {\"Contract\":\"the server reports a different service surface\"}\n",
    );
}

// --- Bare `ret` (return void) -------------------------------------------------

// `ret` with no value is a void early-return: the guard exits before the print,
// and the non-guarded call falls through to it.
#[test]
fn bare_ret_returns_void_early() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun guard(flag: bool) {
        	if flag {
        		ret;
        	}
        	print("passed");
        }

        fun main() {
        	guard(true);
        	guard(false);
        }
        "#,
        "passed\n",
    );
}

// A `ret` value must match the declared return type (proposal/ret-checking.md:
// `ret` joins the tail's `ReturnType` constraint, which now verifies via
// `reconcile_type` instead of only directing inference).
#[test]
fn ret_value_is_checked_against_the_declared_return_type() {
    assert_fails(
        r#"
        fun bad(): i32 {
        	ret "nope";
        	1
        }

        fun main() {
        	let _ = bad();
        }
        "#,
    );
}

// The void case: a bare `ret` is `ret <void>` — legal exactly when the
// declared return type is void, rejected in a value-returning function.
#[test]
fn bare_ret_in_a_value_returning_function_is_rejected() {
    assert_fails(
        r#"
        fun bad(flag: bool): i32 {
        	if flag {
        		ret;
        	}
        	1
        }

        fun main() {
        	let _ = bad(true);
        }
        "#,
    );
}

// --- Malformed frames are decode errors, never crashes -------------------------

// The JSON codec's reader must arrive PRE-POISONED on text that is not JSON at
// all (wire frames are untrusted input): `decode` returns `Err`, and an RPC
// protocol answers a garbage request with `Failure(Decode)` — it used to throw
// out of `JSON.parse`, letting one malformed request kill a server process.
#[test]
fn malformed_json_frames_fail_sticky_instead_of_crashing() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };
        import std::result::Result::{ self, Ok, Err };
        import std::json::{ json_codec, decode_json };
        import std::wire::{ decode, Frame };
        import std::rpc::{ Dispatcher, reply, RpcOutcome, RpcError };

        fun main() {
        	// The decode seam: garbage text and a garbage binary frame both Err.
        	let direct: Result<i32, str> = decode_json("garbage{{{");
        	match direct {
        		Ok(let value) => print("direct: unexpected Ok"),
        		Err(let reason) => print(i"direct: {reason}"),
        	}
        	let framed: Result<i32, str> = decode(json_codec(), Frame::Text("also not json"));
        	match framed {
        		Ok(let value) => print("framed: unexpected Ok"),
        		Err(let reason) => print(i"framed: {reason}"),
        	}
        	// The RPC seam: a protocol ANSWERS a garbage request (Failure
        	// envelope), it does not throw.
        	let protocol = Dispatcher::new().on("ping", |request| reply(1)).into_protocol(json_codec());
        	let answer = protocol.respond(Frame::Text("garbage{{{"));
        	match answer {
        		Frame::Text(let envelope) => print(i"rpc answers: {envelope}"),
        		Frame::Binary(let bytes) => print("rpc: unexpected binary"),
        	}
        }
        "#,
        "direct: malformed JSON\nframed: malformed JSON\nrpc answers: {\"Failure\":{\"Decode\":\"malformed JSON\"}}\n",
    );
}

// The wider half of the same gap (proposal/ret-checking.md): the TAIL was not
// checked either — `Constraint::ReturnType` directed inference but never
// verified. `fun f(): i32 { "nope" }` used to compile clean.
#[test]
fn function_tail_is_checked_against_the_declared_return_type() {
    assert_fails(
        r#"
        fun bad(): i32 {
        	"nope"
        }

        fun main() {
        	let _ = bad();
        }
        "#,
    );
}

// A void CALL is not a value: caught in tail position...
#[test]
fn a_void_call_tail_is_not_a_value_return() {
    assert_fails(
        r#"
        import std::print;

        fun bad(): i32 {
        	print("side effect")
        }

        fun main() {
        	let _ = bad();
        }
        "#,
    );
}

// ...and in `ret` position.
#[test]
fn a_void_call_ret_is_not_a_value_return() {
    assert_fails(
        r#"
        import std::print;

        fun bad(): i32 {
        	ret print("side effect");
        	1
        }

        fun main() {
        	let _ = bad();
        }
        "#,
    );
}

// One bad `ret` among good ones is flagged — the check is per return site,
// not per function.
#[test]
fn one_bad_ret_among_good_ones_is_flagged() {
    assert_fails(
        r#"
        fun bad(a: bool, b: bool): i32 {
        	if a {
        		ret 1;
        	}
        	if b {
        		ret "two";
        	}
        	3
        }

        fun main() {
        	let _ = bad(true, false);
        }
        "#,
    );
}

// In a function with NO declared return type, a `ret` is return evidence
// like the tail (proposal/ret-checking.md rule 3, amended by B126): here a
// `ret` of a void call beside a body that ends without a value — both void,
// so they agree. Re-pinned from `ret_with_a_value_in_an_undeclared_void_
// function_is_allowed`, whose comment said the value was "discarded, not
// diagnosed"; it is neither now, it is read.
#[test]
fn b126_a_void_ret_agrees_with_a_void_body() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun loud(flag: bool) {
        	if flag {
        		ret print("early");
        	}
        	print("late");
        }

        fun main() {
        	loud(true);
        	loud(false);
        }
        "#,
        "early\nlate\n",
    );
}

// --- B126: an unannotated function's return type is inferred from its
// reachable tail AND every `ret` (proposal/ret-checking.md rule 3, amended
// 2026-08-22). Before: the `Type::Function` arm read the tail id alone, so
// `fun f(x: bool) { ret 1; }` was `void` at every call site and a `ret` of the
// wrong type was invisible — `{ if x { ret "s"; } 2 }` handed a `str` to an
// `i32` binding at runtime. One helper (`inferred_return_type`) now answers
// for the call site, closure coercion, the `for` protocol's `next`, and trait
// conformance; each pin below is one shape of the rule.

// The headline: a body that leaves only by `ret` has an unreachable
// (synthesized void) tail, which is no evidence. Plant-proven: dropping the
// rets from the evidence, or reading the dead tail as reachable, turns this red.
#[test]
fn b126_a_ret_only_body_infers_its_return_type() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun f(x: bool) {
        	ret 1;
        }

        fun main() {
        	let y: i32 = f(true);
        	print(y);
        }
        "#,
        "1\n",
    );
}

// Unchanged by the amendment: no `ret`, the tail decides.
#[test]
fn b126_a_tail_only_body_still_infers_from_its_tail() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun f() {
        	5
        }

        fun main() {
        	let y: i32 = f();
        	print(y);
        }
        "#,
        "5\n",
    );
}

// A reachable tail and a `ret` that agree — both paths run.
#[test]
fn b126_a_ret_and_a_tail_that_agree_infer_one_type() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun f(x: bool) {
        	if x {
        		ret 1;
        	}
        	2
        }

        fun main() {
        	let y: i32 = f(true);
        	print(y);
        	print(f(false));
        }
        "#,
        "1\n2\n",
    );
}

// The disagreement is refused at the `ret`, naming both types and the tail it
// is measured against, with a note at that tail — and it is the ONLY
// diagnostic: the function's calls type as `any` afterwards, so the old
// `Expected i32, but got void` never appears beside it (B5).
#[test]
fn b126_a_ret_disagreeing_with_the_tail_is_refused_at_the_ret() {
    let source = r#"
        fun f(x: bool) {
        	if x {
        		ret "s";
        	}
        	2
        }

        fun main() {
        	let y: i32 = f(true);
        }
        "#;
    let head = "this `ret` returns str, but the function's return type is inferred as i32 from its tail; make every return agree, or declare the return type";
    assert_fails_spanning(source, "ret \"s\"", head);
    assert_fails_once_with(source, "return type is inferred");
    assert_fails_noting(source, head, "2", "the tail it is inferred from");
    assert_fails_without(source, "Expected");
}

// A bare `ret` is `ret <void>` (rule 2's reading): it disagrees with a value
// tail. Before the amendment `f(true)` handed back `undefined` under `i32`.
#[test]
fn b126_a_bare_ret_in_a_value_tailed_function_is_refused() {
    let source = r#"
        fun f(x: bool) {
        	if x {
        		ret;
        	}
        	2
        }

        fun main() {
        	let y: i32 = f(true);
        }
        "#;
    assert_fails_spanning(
        source,
        "ret",
        "a bare `ret` returns nothing, but the function's return type is inferred as i32 from its tail; return a value, or declare the return type",
    );
    assert_fails_without(source, "Expected");
}

// The tail the body CAN reach is evidence even when it is the parser's
// synthesized void after a last statement that does not leave: `f(false)`
// falls through, so typing the function `i32` from its `ret` would be the
// `undefined`-under-`i32` miscompile one layer up. The origin is named as the
// body ending without a value, noted at the closing brace.
#[test]
fn b126_a_value_ret_beside_a_fall_through_is_refused() {
    let source = r#"
        import std::print;

        fun f(x: bool) {
        	if x {
        		ret 1;
        	}
        	print("fell through");
        }

        fun main() {
        	let y: i32 = f(false);
        }
        "#;
    let head = "this `ret` returns i32, but the function's return type is inferred as void from its body ending without a value; make every return agree, or declare the return type";
    assert_fails_spanning(source, "ret 1", head);
    assert_fails_noting_nth(source, head, "}", 1, "the body ends here without a value");
    assert_fails_without(source, "Expected");
}

// The other fall-through spelling: the tail IS an `if` with no `else`, which
// produces void on the path that takes no branch (S3's regime 2, named the
// same way here).
#[test]
fn b126_a_value_ret_beside_an_else_less_if_tail_is_refused() {
    let source = r#"
        fun f(x: bool) {
        	if x {
        		ret 1;
        	}
        }

        fun main() {
        	let y: i32 = f(false);
        }
        "#;
    assert_fails_spanning(
        source,
        "ret 1",
        "this `ret` returns i32, but the function's return type is inferred as void from its tail, an `if` with no `else`; make every return agree, or declare the return type",
    );
    assert_fails_noting(
        source,
        "an `if` with no `else`",
        "if x {\n        \t\tret 1;\n        \t}",
        "an `if` with no `else` produces void",
    );
}

// A `ret` of a void call beside a value tail is the same disagreement, read
// the other way round (rule 2's "a void call ret is not a value return").
#[test]
fn b126_a_void_ret_beside_a_value_tail_is_refused() {
    assert_fails_with(
        r#"
        import std::print;

        fun f(x: bool) {
        	if x {
        		ret print("x");
        	}
        	1
        }

        fun main() {
        	let y: i32 = f(false);
        }
        "#,
        "this `ret` returns void, but the function's return type is inferred as i32 from its tail",
    );
}

// Several `ret`s and no reachable tail: they agree, and every path runs.
#[test]
fn b126_rets_that_agree_infer_one_type() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun sign(x: i32) {
        	if x > 0 {
        		ret 1;
        	}
        	if x < 0 {
        		ret -1;
        	}
        	ret 0;
        }

        fun main() {
        	let y: i32 = sign(5);
        	print(y);
        	print(sign(-3));
        	print(sign(0));
        }
        "#,
        "1\n-1\n0\n",
    );
}

// With no reachable tail the first `ret` sets the type and a later one that
// disagrees is refused at ITSELF, naming the earlier `ret` as the origin; one
// refusal, no cascade at the call.
#[test]
fn b126_rets_that_disagree_are_refused_at_the_later_ret() {
    let source = r#"
        fun f(x: bool) {
        	if x {
        		ret 1;
        	}
        	ret "s";
        }

        fun main() {
        	let y: i32 = f(true);
        }
        "#;
    let head = "this `ret` returns str, but the function's return type is inferred as i32 from an earlier `ret`; make every return agree, or declare the return type";
    assert_fails_spanning(source, "ret \"s\"", head);
    assert_fails_noting(
        source,
        head,
        "ret 1",
        "the earlier `ret` it is inferred from",
    );
    assert_fails_once_with(source, "return type is inferred");
    assert_fails_without(source, "Expected");
}

// A generic return-position call in a `ret` is read WITH the tail's type as
// its expectation, so `List::new()` binds its element from the tail.
#[test]
fn b126_a_ret_of_a_generic_call_binds_from_the_tail() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::list::List;

        fun make(flag: bool) {
        	if flag {
        		ret List::new();
        	}
        	mut items = List::new();
        	items.push(1);
        	items
        }

        fun main() {
        	let xs: List<i32> = make(false);
        	print(xs.len());
        	let empty: List<i32> = make(true);
        	print(empty.len());
        }
        "#,
        "1\n0\n",
    );
}

// A generic function's `ret` of its own parameter agrees with a tail of the
// same parameter type, at every instantiation.
#[test]
fn b126_a_generic_function_infers_from_a_ret_of_its_parameter() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun pick<T>(flag: bool, a: T, b: T) {
        	if flag {
        		ret a;
        	}
        	b
        }

        fun main() {
        	let y: i32 = pick(true, 1, 2);
        	print(y);
        	let s: str = pick(false, "a", "b");
        	print(s);
        }
        "#,
        "1\nb\n",
    );
}

// A closure inside an unannotated function keeps its own frame: its `ret`s
// type the closure (rule 4), the function's `ret`s type the function, and the
// two may differ. The negative half: a closure's bad `ret` is the CLOSURE's
// diagnostic, never the function's.
#[test]
fn b126_a_nested_closures_rets_stay_on_the_closures_frame() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun label(g: |i32| str): str {
        	g(10)
        }

        fun outer(x: bool) {
        	let text = label(|v| {
        		if v > 5 {
        			ret "big";
        		}
        		"small"
        	});
        	if x {
        		ret text.len();
        	}
        	ret 0;
        }

        fun main() {
        	let y: i32 = outer(true);
        	print(y);
        }
        "#,
        "3\n",
    );
    let source = r#"
        fun apply(g: |i32| i32): i32 {
        	g(10)
        }

        fun outer(x: bool) {
        	let inner = apply(|v| {
        		if v > 5 {
        			ret "str";
        		}
        		v
        	});
        	if x {
        		ret inner;
        	}
        	ret 0;
        }

        fun main() {
        	let y: i32 = outer(true);
        }
        "#;
    assert_fails_with(
        source,
        "this `ret` returns str, but the closure's body yields i32",
    );
    assert_fails_without(source, "the function's return type is inferred");
}

// Recursion: a self-call contributes nothing (its type IS the answer under
// construction), so the OTHER returns decide — through a `ret` of an
// expression over the self-call, a tail over it, and a `ret` that is nothing
// but the self-call (which used to be "could not be resolved").
#[test]
fn b126_a_recursive_unannotated_function_infers_from_its_other_returns() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun count(n: i32) {
        	if n == 0 {
        		ret 0;
        	}
        	ret 1 + count(n - 1);
        }

        fun fact(n: i32) {
        	if n <= 1 {
        		ret 1;
        	}
        	n * fact(n - 1)
        }

        fun down(n: i32) {
        	if n == 0 {
        		ret 0;
        	}
        	ret down(n - 1);
        }

        fun main() {
        	let a: i32 = count(3);
        	print(a);
        	let b: i32 = fact(5);
        	print(b);
        	let c: i32 = down(4);
        	print(c);
        }
        "#,
        "3\n120\n0\n",
    );
}

// Mutual recursion: each function's answer is built on the other's, and the
// one built on an unfinished neighbour is not recorded — each computes
// top-level through its own constraint, so both coerce and both call.
#[test]
fn b126_mutually_recursive_unannotated_functions_infer_together() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun a(n: i32) {
        	if n == 0 {
        		ret 0;
        	}
        	b(n - 1)
        }

        fun b(n: i32) {
        	a(n - 1)
        }

        fun main() {
        	let y: i32 = a(4);
        	print(y);
        	let z: i32 = b(3);
        	print(z);
        }
        "#,
        "0\n0\n",
    );
}

// B126 residue (2026-08-22), KNOWN, NOT FIXED: a self-call bound by a `let`
// and read in the tail. The inference path does not read a `let` binding
// through its initializer, so the tail `x + 1` is unresolved while `x`'s own
// constraint is waiting on `g(n - 1)` — and the function's answer never
// lands: "type of variable 'x' could not be resolved". Same on `next` before
// the amendment. Asserts what SHOULD hold; goes green when the binding is
// read through its initializer on the inference path.
#[test]
#[ignore = "B126 residue, 2026-08-22: a self-call bound by a `let` and read in the tail \
            (`let x = g(n - 1); x + 1`) in an unannotated recursive body still fails \
            \"could not be resolved\" — a `let` binding is not read through its \
            initializer on the inference path"]
fn b126_a_let_bound_self_call_read_in_the_tail_resolves() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun g(n: i32) {
        	if n == 0 {
        		ret 1;
        	}
        	let x = g(n - 1);
        	x + 1
        }

        fun main() {
        	let y: i32 = g(3);
        	print(y);
        }
        "#,
        "4\n",
    );
}

// A function whose only return evidence is itself never returns: `never`,
// which satisfies any expectation (as `panic(..)` does). It used to be
// "could not be resolved".
#[test]
fn b126_a_function_that_only_calls_itself_is_never() {
    assert_compiles(
        r#"
        fun forever(n: i32) {
        	forever(n - 1)
        }

        fun main() {
        	if false {
        		let y: i32 = forever(5);
        	}
        }
        "#,
    );
}

// The conformance reader sees the unified type: an unannotated impl member
// that leaves by `ret` conforms when the `ret` agrees with the trait, and is
// refused when it does not (it used to pass leniently and print "wide").
#[test]
fn b126_an_unannotated_impl_method_conforms_by_its_unified_type() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        trait Shape {
        	fun area(self): i32;
        }

        struct Sq { s: i32 }

        impl Sq with Shape {
        	fun area(self) {
        		ret self.s * self.s;
        	}
        }

        fun main() {
        	let q = Sq { s = 3 };
        	print(q.area());
        }
        "#,
        "9\n",
    );
    assert_fails_with(
        r#"
        import std::print;

        trait Shape {
        	fun area(self): i32;
        }

        struct Sq { s: i32 }

        impl Sq with Shape {
        	fun area(self) {
        		ret "wide";
        	}
        }

        fun main() {
        	let q = Sq { s = 3 };
        	print(q.area());
        }
        "#,
        "`Sq`'s `area` returns `str`, but `Shape` declares `i32`",
    );
}

// The rule is the function's, not the shape's: an `async fun` without an
// annotation infers the same way, and an awaited call yields that type.
#[test]
fn b126_an_async_function_without_annotation_infers_from_its_rets() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        async fun f(x: bool) {
        	ret 1;
        }

        async fun g(x: bool) {
        	if x {
        		ret 1;
        	}
        	2
        }

        async fun main() {
        	let y: i32 = f(true);
        	print(y);
        	let z: i32 = g(true);
        	print(z);
        	print(g(false));
        }
        "#,
        "1\n1\n2\n",
    );
}

// The `for` protocol's reader (B92) goes through the same helper: an
// unannotated `next` that leaves by `ret Some(..)`/`ret None` drives the loop
// (it used to be refused as yielding `void`), and one whose `ret` yields a
// non-`Option` is refused by B92's own message with the unified type.
#[test]
fn b126_an_unannotated_next_that_leaves_by_ret_drives_the_loop() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::option::Option::{ self, Some, None };

        struct Two { at: i32 }

        impl Two {
        	fun next(&mut self) {
        		if self.at >= 2 {
        			ret None;
        		}
        		self.at += 1;
        		ret Some(self.at);
        	}
        }

        fun main() {
        	mut two = Two { at = 0 };
        	for item in two {
        		print(item);
        	}
        	print(9);
        }
        "#,
        "1\n2\n9\n",
    );
    assert_fails_with(
        r#"
        import std::print;

        struct Num { at: i32 }

        impl Num {
        	fun next(&mut self) {
        		self.at += 1;
        		ret self.at;
        	}
        }

        fun main() {
        	mut num = Num { at = 0 };
        	for item in num {
        		print(item);
        	}
        }
        "#,
        "its `next` is unannotated and its body yields `i32`",
    );
}

// Closure coercion (B20) reads the helper on both of its paths — the
// inferring one in `reconcile_type` and the recorded one in `compare_type` —
// so a `ret`-only function fits a `|bool| i32` slot (it used to be refused as
// `fn say(bool)` against `|bool| i32`).
#[test]
fn b126_a_ret_only_function_coerces_to_a_closure_slot() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun run(f: |bool| i32) {
        	print(f(true));
        }

        fun say(x: bool) {
        	ret 1;
        }

        fun main() {
        	run(say);
        }
        "#,
        "1\n",
    );
}

// An exhaustive `if`/`else` of `ret`s in tail position types `never` (B124),
// which is no evidence; the `ret`s decide. Before, the function itself was
// `never` and `let y: str = f(false)` compiled and printed `2`.
#[test]
fn b126_an_exhaustive_if_else_of_rets_infers_from_the_rets() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun f(x: bool) {
        	if x {
        		ret 1;
        	} else {
        		ret 2;
        	}
        }

        fun main() {
        	let y: i32 = f(false);
        	print(y);
        }
        "#,
        "2\n",
    );
    assert_fails_with(
        r#"
        import std::print;

        fun f(x: bool) {
        	if x {
        		ret 1;
        	} else {
        		ret 2;
        	}
        }

        fun main() {
        	let y: str = f(false);
        	print(y);
        }
        "#,
        "Expected str, but got i32 instead.",
    );
}

// --- S3: the missing return value re-anchored (editing-dx.md §3) ----------
// The known-bad shape the charter named first: a missing return value used
// to underline the WHOLE closure (or, worse, the whole call) rather than the
// gap. Three regimes, per §3.2-§3.4; pins below are named after the paper's
// probes (P21-P28).

// P22 — regime 1: a named function whose body ends in a non-expression
// statement (here a `let`) has NO tail to anchor at all. Old behavior: a
// zero-width point one byte PAST the closing brace (invisible in an editor,
// §3.2). New: the closing brace itself, one character wide.
#[test]
fn missing_return_value_regime_1_anchors_the_closing_brace() {
    assert_fails_spanning(
        r#"
        fun total(a: i32, b: i32): i32 {
        	let sum: i32 = a + b;
        }

        fun main() {
        	total(1, 2);
        }
        "#,
        "}",
        "Expected i32, but got void instead: this body ends without producing a value.",
    );
}

// Regime 1' for a NAMED function (not one of the paper's own probes — P24's
// closure shape is the paper's example, but the same statement-based
// distinction applies to a plain function body, and CLAUDE.md's "per case,
// not per example" wants the edge covered directly): the last statement IS
// an expression whose value would satisfy the return type, discarded only by
// its trailing `;` — the sharper, actionable message.
#[test]
fn missing_return_value_regime_1_prime_named_function_names_the_semicolon() {
    assert_fails_spanning(
        r#"
        fun total(a: i32, b: i32): i32 {
        	a + b;
        }

        fun main() {
        	total(1, 2);
        }
        "#,
        "}",
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// A last statement that reconciles by NAME-COINCIDENCE only, not because
// removing its `;` would make it the tail: `let` is a declaration, not an
// expression, even though its own type (i32) happens to match the return
// type. Regression guard for the bug this shape reproduced during
// development (a bare `self.variables` miss let a `let`'s binding type stand
// in for "the last statement's value").
#[test]
fn a_declaration_as_the_last_statement_does_not_trigger_regime_1_prime() {
    assert_fails_with(
        r#"
        fun total(a: i32, b: i32): i32 {
        	let sum: i32 = a + b;
        }

        fun main() {
        	total(1, 2);
        }
        "#,
        "this body ends without producing a value.",
    );
}

// P25 — regime 2: an `if` with no `else` in tail position is a REAL
// expression (not the parser's synthesized `Void`), so its span was already
// A1-compliant (§3.3, unchanged) — what §16 deferred as "needs a provenance
// channel" and §17 builds: the WORDING now names the missing `else` as the
// gap (`if_branch_has_final_else` asked again at the diagnostic site,
// editing-dx.md §17.1) instead of the generic mismatch phrasing regimes 1/1'
// no longer use for their own gap.
#[test]
fn missing_return_value_regime_2_if_with_no_else_names_the_gap() {
    assert_fails_with(
        r#"
        fun classify(n: i32): str {
        	if n > 0 {
        		"positive"
        	}
        }

        fun main() {
        	classify(1);
        }
        "#,
        "Expected str, but got void instead: an `if` with no `else` produces void.",
    );
}

// Regression guard for the refinement's own boundary: a void-typed CALL in
// tail position (no trailing `;` — that would be regime 1, §3.2) is a real
// value the body produced too, but it is not an `if`, so it must keep the
// plain mismatch message rather than being swept into regime 2's wording.
#[test]
fn missing_return_value_a_void_call_tail_keeps_the_generic_message() {
    assert_fails_with(
        r#"
        import std::print;

        fun classify(n: i32): str {
        	print(n)
        }

        fun main() {
        	classify(1);
        }
        "#,
        "Expected str, but got void instead.",
    );
}

// P23 — regime 3, unannotated closure bound to an annotated `let`: the
// closure's OWN parameters need no annotation (`|value|`, filled by
// bidirectional inference from `|i32| i32`); once they reconcile, the body
// checks in RETURN POSITION against the annotation's return half instead of
// the whole closure value being compared at the `let` — the closing BRACE,
// not the closure's `|params| { .. }` span, `points.map(..)`'s whole call,
// or anything else upstream.
#[test]
fn missing_return_value_regime_3_context_closure_anchors_its_own_brace() {
    assert_fails_spanning(
        r#"
        fun main() {
        	let scale: |i32| i32 = |value| {
        		let doubled: i32 = value * 2;
        	};
        }
        "#,
        "}",
        "Expected i32, but got void instead: this body ends without producing a value.",
    );
}

// P24 — the one-line spelling of the same shape: the whole mistake is one
// character (`;`), and the message now names it. Old behavior: 22 characters
// underlined (the whole closure) to ask for one to be deleted.
#[test]
fn missing_return_value_regime_3_context_closure_one_liner_names_the_semicolon() {
    assert_fails_spanning(
        r#"
        fun main() {
        	let scale: |i32| i32 = |value| { value * 2; };
        }
        "#,
        "}",
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// P26 — the root-cause probe: a closure's OWN return-type annotation
// (`: i32`) used to be parsed, re-printed by the formatter, and completely
// ignored by type checking (`Closure::return_type` had no analyzer reader at
// all). It now gets rule 2 "directly" — the same return-position check a
// named function's declared return type gets — independent of any
// surrounding context.
#[test]
fn missing_return_value_regime_3_annotated_closure_is_newly_checked() {
    assert_fails_spanning(
        r#"
        import std::print;

        fun main() {
        	let scale: |i32| i32 = |value: i32|: i32 { print(value); };
        }
        "#,
        "}",
        "Expected i32, but got void instead: this body ends without producing a value.",
    );
}

// An annotated closure whose body actually satisfies its OWN declared
// return type compiles clean — the new check is additive, not a false
// positive on the common case.
#[test]
fn an_annotated_closure_whose_body_satisfies_its_own_return_type_compiles() {
    assert_compiles_and_runs(
        r#"
        import std::print;

        fun main() {
        	let scale: |i32| i32 = |value: i32|: i32 { value * 2 };
        	print(scale(5));
        }
        "#,
        "10\n",
    );
}

// P27 — the contrast that bounds the fix: when the PARAMETER type is what
// differs (not the return type), the whole-closure anchor is correct and
// stays untouched — nothing narrower would be honest about a closure that,
// as written, is the wrong VALUE.
#[test]
fn missing_return_value_regime_3_parameter_mismatch_keeps_the_whole_value_anchor() {
    assert_fails_spanning(
        r#"
        fun main() {
        	let scale: |i32| i32 = |value: str| { 1 };
        }
        "#,
        "|value: str| { 1 }",
        "Expected |i32| i32, but got |str| i32 instead.",
    );
}

// P21 — the generic-binding case, closed by B125 (type-solver.md "The
// expectation is an input of generic call resolution"): `map<U>`'s `U` is
// bound from the call site's EXPECTATION (`let widths: List<i32>`) before the
// closure argument is typed, so the closure arm's return-position check has
// a ground target on the first attempt and reports at the closure's own
// brace — not one level out as `List<void>` against the annotation. The
// `type_is_ground` gate is unchanged: it still declines a target nobody has
// bound; the expectation is what binds it now.
#[test]
fn missing_return_value_regime_3_through_a_generic_binding() {
    assert_fails_spanning_nth(
        r#"
        import std::print;

        struct Point { x: i32, y: i32 }

        fun main() {
        	mut points: List<Point> = List::new();
        	points.push(Point { x = 1, y = 10 });
        	let widths: List<i32> = points.map(|point| {
        		point.x * 2;
        	});
        	print(widths.len());
        }
        "#,
        "}",
        2,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// The same binding through a declared return type's TAIL — the expectation
// the function walk seeds for its body tail reaches the call at priority 6
// exactly as the `let` annotation does.
#[test]
fn missing_return_value_regime_3_through_a_generic_binding_in_tail_position() {
    assert_fails_spanning_nth(
        r#"
        import std::print;

        struct Point { x: i32, y: i32 }

        fun widths(points: List<Point>): List<i32> {
        	points.map(|point| {
        		point.x * 2;
        	})
        }

        fun main() {
        	mut points: List<Point> = List::new();
        	points.push(Point { x = 1, y = 10 });
        	print(widths(points).len());
        }
        "#,
        "}",
        1,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// And through a `ret` — the third walk-time expectation seed.
#[test]
fn missing_return_value_regime_3_through_a_generic_binding_in_ret_position() {
    assert_fails_spanning_nth(
        r#"
        import std::print;

        struct Point { x: i32, y: i32 }

        fun widths(points: List<Point>): List<i32> {
        	ret points.map(|point| {
        		point.x * 2;
        	});
        }

        fun main() {
        	mut points: List<Point> = List::new();
        	points.push(Point { x = 1, y = 10 });
        	print(widths(points).len());
        }
        "#,
        "}",
        1,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// The free-function path rides the same binding source (B90 aligned the two
// call paths; B125 keeps them aligned): `apply<U>`'s `U` from the `let`.
#[test]
fn missing_return_value_regime_3_through_a_free_functions_generic_binding() {
    assert_fails_spanning_nth(
        r#"
        import std::print;

        fun apply<U>(xs: List<i32>, f: |i32| U): List<U> {
        	xs.map(f)
        }

        fun main() {
        	let xs = [1, 2];
        	let ys: List<i32> = apply(xs, |x| {
        		x * 2;
        	});
        	print(ys.len());
        }
        "#,
        "}",
        1,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// `Signal::map<U>` — the shape the todo example annotates around; `sync |T|
// U` binds the same way as `List::map`'s `|T| U`.
#[test]
fn missing_return_value_regime_3_through_a_signal_maps_generic_binding() {
    assert_fails_spanning_nth(
        r#"
        import std::print;
        import std::reactive::{ Owner, Signal, owner_scope };

        fun main() {
        	let scope = Owner::new();
        	let n = owner_scope.run(scope, || {
        		let count = Signal::new(1);
        		let doubled: Signal<i32> = count.map(|n| {
        			n * 2;
        		});
        		doubled.get()
        	});
        	print(n);
        	scope.dispose();
        }
        "#,
        "}",
        1,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
}

// The nested shapes: the expectation reaches a call standing in a block
// tail, a value-`if`'s branch tail, or a match leg — seeded at WALK time
// through the syntactic tails (`seed_tail_expectations`), and by
// `resolve_match` before its subject can defer the attempt.
#[test]
fn missing_return_value_regime_3_through_a_generic_binding_in_a_block_tail() {
    let source = r#"
        import std::print;

        struct Point { x: i32, y: i32 }

        fun main() {
        	mut points: List<Point> = List::new();
        	points.push(Point { x = 1, y = 10 });
        	let widths: List<i32> = {
        		points.map(|point| {
        			point.x * 2;
        		})
        	};
        	print(widths.len());
        }
        "#;
    assert_fails_spanning_nth(
        source,
        "}",
        2,
        "Expected i32, but got void instead: the `;` discards this body's last value.",
    );
    assert_fails_without(source, "List<void>");
}

