#[test]
fn reaching_functions_inside_const_are_fine() {
    // The styling shape: property functions bottom out in emit, called from
    // const chains — legal, and the assets flow.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::asset::emit;
        fun padding(): i32 {
            emit("css", ".pA3{padding:1rem}");
            4
        }
        fun main() {
            let width = const padding() * 2;
            print(width);
        }
        main();
        "#,
        "8\n",
    );
}

#[test]
fn analysis_leaves_the_const_results_on_the_program() {
    // The invariant the LSP relies on (const-eval.md §8.3): `analyze_source`
    // already evaluated every `const`, so no consumer needs a second pass to
    // read the values — hover reads `program.const_results` directly.
    let source = r#"
        fun square(n: i32): i32 { n * n }
        fun main() {
            let _folded = const square(7);
        }
        main();
        "#
    .to_string();
    let values = std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(move || {
            let leaked: &'static str = Box::leak(source.into_boxed_str());
            let (program, errors) = analyze_source(
                leaked,
                &std_spec(),
                Path::new("."),
                Path::new("test.vl"),
                Some(Platform::default()),
                &Workspace::default(),
            );
            assert!(errors.is_empty(), "expected a clean analysis: {errors:#?}");
            program
                .map(|program| program.const_results.values().cloned().collect::<Vec<_>>())
                .unwrap_or_default()
        })
        .unwrap()
        .join()
        .unwrap();
    assert_eq!(
        values,
        vec![vilan_core::interpreter::ConstValue::Number(49.0)],
        "the folded value must survive on the program"
    );
}

// Deep failure attribution (const-eval.md §8.2): the primary span stays the
// `const` expression — there is no inner span to move to — but the frame trace
// names the function the failure happened in and notes its declaration.

#[test]
fn a_deep_const_failure_names_the_failing_function() {
    assert_fails_noting(
        r#"
        fun level_three(xs: List<i32>): i32 {
            xs[9]
        }
        fun level_two(xs: List<i32>): i32 {
            level_three(xs) + 1
        }
        fun level_one(): i32 {
            mut xs: List<i32> = List::new();
            xs.push(1);
            level_two(xs)
        }
        fun main() {
            let _value = const level_one();
        }
        main();
        "#,
        "const evaluation failed in `level_three`: index out of bounds",
        "level_three",
        "the compile-time call chain: level_one → level_two → level_three",
    );
}

#[test]
fn a_single_frame_const_failure_notes_the_declaration_without_a_chain() {
    assert_fails_noting(
        r#"
        import std::io::panic;
        fun only(): i32 {
            panic("no");
            1
        }
        fun main() {
            let _value = const only();
        }
        main();
        "#,
        "const evaluation failed in `only`: no",
        "only",
        "`only` is declared here",
    );
}

#[test]
fn a_const_fuel_miss_reports_a_budget_not_a_failure() {
    // §4's promised wording, which the raw interpreter message never carried.
    assert_fails_with(
        r#"
        fun spin(): i32 {
            mut i = 0;
            for {
                i = i + 1;
            }
            i
        }
        fun main() {
            let _value = const spin();
        }
        main();
        "#,
        "const evaluation did not finish within the compile-time budget in `spin`: the fuel \
         budget was exhausted",
    );
}

#[test]
fn a_const_depth_miss_reports_a_budget_and_elides_the_repeated_frames() {
    assert_fails_noting(
        r#"
        fun recurse(n: i32): i32 {
            recurse(n + 1)
        }
        fun main() {
            let _value = const recurse(0);
        }
        main();
        "#,
        "const evaluation did not finish within the compile-time budget in `recurse`: the \
         call-depth cap was exceeded",
        "recurse",
        "the compile-time call chain: … → recurse → recurse → recurse → recurse",
    );
}

// The value escape (const-eval.md §2): a call THROUGH a function or closure
// value resolves to `Indirect(Value)`, which carries no caller edge, so the
// R-fixpoint cannot follow it. v1 refuses at the reference — without which the
// emitted JS carries a live `__emit_asset` call that has no runtime binding.

#[test]
fn a_function_reaching_emit_cannot_escape_as_a_value() {
    let source = r#"
        import std::asset::emit;
        fun styled(): i32 {
            emit("css", ".a{}");
            1
        }
        fun apply(f: || i32): i32 {
            f()
        }
        fun main() {
            let _x = apply(styled);
        }
        main();
        "#;
    let reference = source.rfind("styled").unwrap();
    let diagnostics = failure_diagnostics(source);
    assert!(
        diagnostics
            .iter()
            .any(|(message, range)| message.contains("compile-time-only")
                && *range == (reference..reference + "styled".len())),
        "no value-escape diagnostic at the reference: {diagnostics:#?}"
    );
}

#[test]
fn a_module_level_value_reference_to_an_emit_reaching_function_is_rejected() {
    let source = r#"
        import std::asset::emit;
        fun styled(): i32 {
            emit("css", ".a{}");
            1
        }
        let HANDLER = styled;
        fun main() {}
        main();
        "#;
    let reference = source.rfind("styled").unwrap();
    let diagnostics = failure_diagnostics(source);
    assert!(
        diagnostics
            .iter()
            .any(|(message, range)| message.contains("compile-time-only")
                && *range == (reference..reference + "styled".len())),
        "no value-escape diagnostic at the module-level reference: {diagnostics:#?}"
    );
}

#[test]
fn a_closure_reaching_emit_cannot_escape_as_a_value() {
    assert_fails_with(
        r#"
        import std::asset::emit;
        fun apply(f: || i32): i32 {
            f()
        }
        fun main() {
            let _x = apply(|| {
                emit("css", ".a{}");
                1
            });
        }
        main();
        "#,
        "compile-time-only",
    );
}

#[test]
fn a_closure_wrapping_an_emit_reaching_call_cannot_escape_as_a_value() {
    assert_fails_with(
        r#"
        import std::asset::emit;
        fun styled(): i32 {
            emit("css", ".a{}");
            1
        }
        fun apply(f: || i32): i32 {
            f()
        }
        fun main() {
            let _x = apply(|| styled());
        }
        main();
        "#,
        "compile-time-only",
    );
}

#[test]
fn an_indirect_call_rooted_in_const_stays_legal() {
    // The refusal is about RUNTIME escape only: inside a `const` expression the
    // interpreter calls through the value happily, and the asset still flows.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::asset::emit;
        fun styled(): i32 {
            emit("css", ".a{}");
            1
        }
        fun apply(f: || i32): i32 {
            f()
        }
        fun main() {
            print(const apply(styled));
        }
        main();
        "#,
        "1\n",
    );
    let assets = collected_assets(
        r#"
        import std::print;
        import std::asset::emit;
        fun styled(): i32 {
            emit("css", ".a{}");
            1
        }
        fun apply(f: || i32): i32 {
            f()
        }
        fun main() {
            print(const apply(styled));
        }
        main();
        "#,
    );
    assert_eq!(assets, vec![("css".to_string(), ".a{}".to_string())]);
}

// --- A8: std::style — typed atomic styles, compiled ---------------------------
// The styling system riding const evaluation and the asset channel
// (proposal/ui-styling.md): builder-chain construction inside `const`, atomic
// rules with content-hashed class names, per-property last-wins merge,
// var-carried theme tokens, condition combinators.

#[test]
fn a_style_emits_atomic_rules_and_theme_vars() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, space, Style };
        fun card(): Style {
            style().padding(space(4))
        }
        let _card = const card();
        fun main() {}
        main();
        "#,
    );
    assert!(
        // `*.` rather than `.`: `padding` is a family shorthand, and the
        // marker is what sorts it ahead of its edges (§0bis.4). The CLASS is
        // unchanged — the hash is over `key|declaration`, which the marker
        // never enters.
        assets.contains(&(
            "css".to_string(),
            "*.s1ufvr2{padding:var(--space-4)}".to_string()
        )),
        "{assets:?}"
    );
    assert!(
        assets.contains(&("css".to_string(), ":root{--space-4:1rem}".to_string())),
        "{assets:?}"
    );
}

#[test]
fn last_wins_within_a_chain() {
    // Two paddings, one slot: the class list carries exactly one class — the
    // later one's.
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::style::{ style, space, Style };
        fun padded(): Style {
            style().padding(space(4)).padding(space(6))
        }
        fun main() {
            let card = const padded();
            let classes = card.class_list();
            print(classes.contains(" "));
            let six = const style().padding(space(6));
            print(classes == six.class_list());
        }
        main();
        "#,
        "false\ntrue\n",
    );
}

#[test]
fn add_merges_per_property_right_wins() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::style::{ style, space, Style, Color };
        fun base(): Style {
            style().padding(space(4)).background(Color::gray(50))
        }
        fun accent(): Style {
            style().padding(space(6))
        }
        fun main() {
            let merged = const base() + accent();
            let expected = const style().padding(space(6)).background(Color::gray(50));
            print(merged.class_list().len() > 0);
            print(merged.class_list() == expected.class_list());
        }
        main();
        "#,
        "true\ntrue\n",
    );
}

#[test]
fn extend_with_override_is_a_property_method_on_a_style() {
    assert_compiles_and_runs(
        r#"
        import std::print;
        import std::style::{ style, space, Style };
        fun main() {
            let base = const style().padding(space(4));
            let bigger = const base.padding(space(6));
            let six = const style().padding(space(6));
            print(bigger.class_list() == six.class_list());
        }
        main();
        "#,
        "true\n",
    );
}

#[test]
fn hover_emits_a_pseudo_rule() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, Style, Color };
        fun s(): Style {
            style().hover(style().background(Color::gray(100)))
        }
        let _s = const s();
        fun main() {}
        main();
        "#,
    );
    assert!(
        assets
            .iter()
            .any(|(_, line)| line.contains(":hover{background-color:var(--gray-100)}")),
        "{assets:?}"
    );
}

#[test]
fn breakpoints_wrap_media_and_stack_with_pseudo() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, space, Style };
        fun s(): Style {
            style().md(style().hover(style().padding(space(6))))
        }
        let _s = const s();
        fun main() {}
        main();
        "#,
    );
    assert!(
        assets
            .iter()
            // `{*.` — `padding` is a family shorthand, so its rule carries the
            // sort marker inside the media block (§0bis.4). The class and the
            // declaration are unchanged.
            .any(|(_, line)| line.starts_with("@media (min-width: 768px){*.")
                && line.contains(":hover{padding:var(--space-6)}")),
        "{assets:?}"
    );
}

#[test]
fn dark_prefixes_the_theme_selector() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, Style, Color };
        fun s(): Style {
            style().dark(style().background(Color::gray(900)))
        }
        let _s = const s();
        fun main() {}
        main();
        "#,
    );
    assert!(
        assets
            .iter()
            .any(|(_, line)| line.starts_with(":root[data-theme=\"dark\"] .")),
        "{assets:?}"
    );
}

/// dark × pseudo composes on ONE slot: the dark ancestor selector and the
/// pseudo-class suffix land in the same rule, nested the way CSS nests them.
#[test]
fn dark_stacks_over_a_pseudo_class() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, Style, Color };
        fun s(): Style {
            style().dark(style().hover(style().background(Color::gray(700))))
        }
        let _s = const s();
        fun main() {}
        main();
        "#,
    );
    assert!(
        assets.iter().any(|(_, line)| {
            line.starts_with(":root[data-theme=\"dark\"] .")
                && line.ends_with(":hover{background-color:var(--gray-700)}")
        }),
        "{assets:?}"
    );
}

/// All three axes at once, media outermost. The composed line still starts
/// with '@', so B35's numeric media ordering keeps seeing it.
#[test]
fn a_breakpoint_wraps_dark_over_a_pseudo_class() {
    let assets = collected_assets(
        r#"
        import std::style::{ style, space, Style };
        fun s(): Style {
            style().md(style().dark(style().hover(style().padding(space(6)))))
        }
        let _s = const s();
        fun main() {}
        main();
        "#,
    );
    assert!(
        assets.iter().any(|(_, line)| line
            // The class name `s19fbteb` is byte-identical to what this rule
            // minted before A22: the marker lives in `render_rule`, and the
            // hash is over `key|declaration`.
            == "@media (min-width: 768px){:root[data-theme=\"dark\"] *.s19fbteb:hover{padding:var(--space-6)}}"),
        "{assets:?}"
    );
}

/// Composition has ONE spelling. dark goes outside the pseudo — the same
/// outside-in rule that makes `md(hover(..))` legal — and the refusal names
/// the fix rather than just saying no.
